window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s2-1168","number":1168,"surah":2,"verses":[229],"references":[{"surah":2,"verses":[229]}],"verseLabel":"البقرة: 229","question":"ما سرّ التعبير في قوله تعالى في البقاء ﴿بِمَعْرُوفٍ﴾ وفي الفراق ﴿بِإِحْسَانٍ﴾؟","answer":"المعروف في الإمساك هو حسن العشرة وأداء حقوق الزوجية، وهو مناسب لاستمرارها وتكرار أحوالها. أما التسريح فناسبه الإحسان بأداء الحقوق والملاطفة وترك الأذى؛ لأن بذل الحق والمال عند الفراق قد يكون أشق على النفوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص570، تحت عنوان «وجه التناسب بين التسريح والإحسان»","url":""}]},{"id":"s2-1169","number":1169,"surah":2,"verses":[229],"references":[{"surah":2,"verses":[229]}],"verseLabel":"البقرة: 229","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا يَحِلُّ لَكُمْ أَنْ تَأْخُذُوا مِمَّا آتَيْتُمُوهُنَّ شَيْئًا﴾؟","answer":"نسب العطاء إلى الأزواج ثم نكر ﴿شيئًا﴾ ليشمل القليل والكثير؛ فما صار حقًا للمرأة لا يسترد بالضغط عند الطلاق. والتعبير بـ﴿لا يحل﴾ يحول المروءة إلى حد شرعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص573، تحت «بلاغة القصر بالنفي والاستثناء»","url":""}]},{"id":"s2-1170","number":1170,"surah":2,"verses":[229],"references":[{"surah":2,"verses":[229]}],"verseLabel":"البقرة: 229","question":"ما سرّ الاستثناء بقوله تعالى: ﴿إِلَّا أَنْ يَخَافَا أَلَّا يُقِيمَا حُدُودَ اللَّهِ﴾؟","answer":"أبيح أخذ العوض في الخلع حين يغلب على الزوجين خوف العجز عن إقامة حقوق الزواج؛ فالاستثناء يفتح مخرجًا من ضرر مستمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص573، تحت «بلاغة القصر بالنفي والاستثناء»","url":""}]},{"id":"s2-1171","number":1171,"surah":2,"verses":[229],"references":[{"surah":2,"verses":[229]}],"verseLabel":"البقرة: 229","question":"ما سرّ الانتقال من المثنى ﴿يَخَافَا﴾ إلى الجمع ﴿فَإِنْ خِفْتُمْ﴾؟","answer":"الخوف الأول من الزوجين في خاصة حالهما، والثاني موجه إلى الحكام والأولياء والجماعة الذين يقدرون الحال ويحكمون في الخلع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص574، تحت «بلاغة الالتفات في تنوع القراءات»","url":""}]},{"id":"s2-1172","number":1172,"surah":2,"verses":[229],"references":[{"surah":2,"verses":[229]}],"verseLabel":"البقرة: 229","question":"ما سرّ التعبير في قوله تعالى في الخلع: ﴿فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا افْتَدَتْ بِهِ﴾؟","answer":"رفع الحرج عن الزوج في الأخذ وعن الزوجة في البذل معًا، وسمى البذل افتداءً لأنه يخلصها من رابطة تخشى معها تضييع الحدود. والعبارة تقيده بالحاجة لا بالابتزاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص577، تحت «دلالة أسلوب الاكتفاء في قوله «فلا جناح عليهما فيما افتدت به» في وجه آخر»","url":""}]},{"id":"s2-1173","number":1173,"surah":2,"verses":[229],"references":[{"surah":2,"verses":[229]}],"verseLabel":"البقرة: 229","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَمَنْ يَتَعَدَّ حُدُودَ اللَّهِ فَأُولَئِكَ هُمُ الظَّالِمُونَ﴾؟","answer":"جاء الشرط عامًا بـ﴿من﴾، ثم روعي معناها فجمع الخبر في ﴿فأولئك﴾، وأكد الحكم باسم الإشارة وضمير الفصل وتعريف ﴿الظالمون﴾؛ فالمتعدون حدود الله هم الراسخون في الظلم بوضع الأحكام في غير مواضعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص581، تحت «التذييل في قوله «فأولئك هم الظالمون»»","url":""}]},{"id":"s2-1174","number":1174,"surah":2,"verses":[230],"references":[{"surah":2,"verses":[230]}],"verseLabel":"البقرة: 230","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى تنكح زوجًا غيره﴾ لا: رجلًا غيره؟","answer":"قال ﴿زوجًا﴾ ليشترط عقد زواج صحيح وحياة زوجية حقيقية، لا مجرد عقد صوري على رجل بقصد التحليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص588، تحت «نكتة التعبير «زوجا» دون (رجلا)»","url":""}]},{"id":"s2-1175","number":1175,"surah":2,"verses":[230],"references":[{"surah":2,"verses":[230]}],"verseLabel":"البقرة: 230","question":"ما دلالة قوله تعالى بعد الطلقة الثالثة: ﴿فَلَا تَحِلُّ لَهُ مِنْ بَعْدُ﴾؟","answer":"تبين الجملة حكم الطلقة الثالثة بعد الطلاق الرجعي مرتين: تنقطع الرجعة المباشرة، ولا تحل له إلا بعد تحقق الشرط الذي تذكره الآية، وهو نكاح زوج غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص585، تحت عنوان «دلالة الفاء من قول الله تعالى: ﴿فإن طلقها﴾»","url":""}]},{"id":"s2-1176","number":1176,"surah":2,"verses":[230],"references":[{"surah":2,"verses":[230]}],"verseLabel":"البقرة: 230","question":"ما سرّ التعبير في قوله تعالى عن الزوج الثاني: ﴿فَإِنْ طَلَّقَهَا﴾ ولم يجعل رجوعها إلى الأول أمرًا مطلوبًا؟","answer":"الزواج الثاني علاقة كاملة قد تستمر، فإن انتهت بطلاق طبيعي فقط عاد إمكان النظر في الزواج الأول. صيغة الشرط تمنع تحويل الثاني إلى جسر مرتب سلفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص586، تحت «نكتة التعبير في الشرط بـ«إن» دون «إذا»»","url":""}]},{"id":"s2-1177","number":1177,"surah":2,"verses":[230],"references":[{"surah":2,"verses":[230]}],"verseLabel":"البقرة: 230","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا جُنَاحَ عَلَيْهِمَا أَنْ يَتَرَاجَعَا﴾؟","answer":"رفع الجناح عن الزوجين في العودة بعد زوال المانع، وجاء ﴿يتراجعا﴾ بصيغة التفاعل لأن كل واحد منهما يرجع إلى صاحبه بعقد ومهر جديدين، لا برجعة يملكها الرجل وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص588، تحت «بيان مرجع الضمير في قوله: «يتراجعا»»","url":""}]},{"id":"s2-1178","number":1178,"surah":2,"verses":[230],"references":[{"surah":2,"verses":[230]}],"verseLabel":"البقرة: 230","question":"ما دلالة تقييد العودة بقوله تعالى: ﴿إِنْ ظَنَّا أَنْ يُقِيمَا حُدُودَ اللَّهِ﴾؟","answer":"أي إن غلب على ظنهما القدرة على الوفاء بحقوق الزواج بعد التجربة السابقة؛ فلا تكون العودة تكرارًا لأسباب الفشل والظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص589، تحت «سر التعبير بالخوف دون العلم في قوله «إن ظنا أن يقيما حدود الله»»","url":""}]},{"id":"s2-1179","number":1179,"surah":2,"verses":[230],"references":[{"surah":2,"verses":[230]}],"verseLabel":"البقرة: 230","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿يُبَيِّنُهَا لِقَوْمٍ يَعْلَمُونَ﴾؟","answer":"خص أهل العلم بالبيان تشريفًا لهم وحثًا على تعلم الأحكام وفهم مصالحها والعمل بها؛ لأنهم المنتفعون بحدود الله، وفيه تعريض بمن يعرض عن العلم بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص592، تحت «بلاغة التعريض في قوله: «وتلك حدود الله يبينها لقوم يعلمون»»","url":""}]},{"id":"s2-1180","number":1180,"surah":2,"verses":[231],"references":[{"surah":2,"verses":[231]}],"verseLabel":"البقرة: 231","question":"ما مناسبة النهي عن اتخاذ آيات الله هزوًا في أثناء أحكام الطلاق؟","answer":"جاء النهي في أثناء أحكام الإمساك والتسريح ومنع الضرار تحذيرًا من التهاون بهذه التكاليف واتخاذها لعبًا، وتغليظًا لمقام أحكام الأسرة وحدود الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص605، تحت «وجه النهي عن اتخاذ آيات الله هزوًا»","url":""}]},{"id":"s2-1181","number":1181,"surah":2,"verses":[231],"references":[{"surah":2,"verses":[231]}],"verseLabel":"البقرة: 231","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿أَنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ﴾؟","answer":"لأن نية الرجعة قد تستر قصد الإضرار، فالعلم الشامل يراقب باطن التصرف الذي لا تكشفه الصيغة القانونية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص609، تحت «نكتة التذييل بصيغة المبالغة «عليم»»","url":""}]},{"id":"s2-1182","number":1182,"surah":2,"verses":[231],"references":[{"surah":2,"verses":[231]},{"surah":65,"verses":[2]}],"verseLabel":"البقرة: 231، الطلاق: 2","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍ﴾، وقوله تعالى في سورة الطلاق: ﴿أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ﴾؟","answer":"﴿سرحوهن﴾ في البقرة يناسب سياق بقاء المطلقة في العدة تحت يد الزوج حتى يطلق سراحها بالمعروف، و﴿فارقوهن﴾ في سورة الطلاق يناسب بلوغ الأجل وحصول المفارقة الفعلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص324، تحت «سر التعبير بـ«فارقوهن» دون «سرحوهن»، كما في البقرة»","url":""}]},{"id":"s2-1183","number":1183,"surah":2,"verses":[231],"references":[{"surah":2,"verses":[231]}],"verseLabel":"البقرة: 231","question":"ما سرّ تكرار الأمر بالإمساك أو التسريح بعد ذكره في الآية 229؟","answer":"هناك بيان لأصل الخيار بعد الطلاق، وهنا بيان لوقته وأخلاق تنفيذه عند بلوغ العدة؛ فالتكرار ينقل الحكم من التشريع العام إلى لحظة قد يقع فيها الضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص593، تحت «العلاقة بين أحكام الطلاق، وواجبات المطلق بعد الطلاق»","url":""}]},{"id":"s2-1184","number":1184,"surah":2,"verses":[231],"references":[{"surah":2,"verses":[231]}],"verseLabel":"البقرة: 231","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تُمْسِكُوهُنَّ ضِرَارًا لِتَعْتَدُوا﴾؟","answer":"كشف حيلة الرجعة التي ظاهرها إبقاء الزواج وباطنها إطالة الأذى، وجعل الإمساك نفسه اعتداءً حين ينقلب مقصده من الإصلاح إلى الضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص603، تحت «سر إيثار التعبير بلفظ «ضرارا» على التعبير بلفظي (الضر)، و(الضرر)»","url":""}]},{"id":"s2-1185","number":1185,"surah":2,"verses":[232],"references":[{"surah":2,"verses":[232]}],"verseLabel":"البقرة: 232","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تعضلوهن﴾؟ وما الصورة التي يحملها العضل؟","answer":"العضل حبس ومنع في ضيق، فيصور الولي كمن يحاصر المرأة ويصدها عن زواج رضيه الطرفان؛ فجاء النهي لتحرير حقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص614، تحت «النهي عن عضل المرأة، والاعتداء على حريتها في الرجوع لزوجها»","url":""}]},{"id":"s2-1186","number":1186,"surah":2,"verses":[232],"references":[{"surah":2,"verses":[232]},{"surah":65,"verses":[2]}],"verseLabel":"البقرة: 232، الطلاق: 2","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿ذَلِكَ يُوعَظُ بِهِ مَنْ كَانَ مِنْكُمْ يُؤْمِنُ بِاللَّهِ﴾ بالإفراد و﴿منكم﴾، وقوله تعالى في الطلاق: ﴿ذَلِكُمْ يُوعَظُ بِهِ مَنْ كَانَ يُؤْمِنُ بِاللَّهِ﴾ بالجمع ومن غير ﴿منكم﴾؟","answer":"جاءت البقرة في تشديد شديد على من يظلم النساء أو يعضلهن ويحتال على أموالهن؛ فالإفراد في ﴿ذلك﴾ ثم التبعيض في ﴿منكم﴾ يلمحان إلى قلة المستجيبين المتورعين عن هذه المطامع. أما أحكام سورة الطلاق في هذا الموضع فأيسر امتثالًا وأكثر من يسلك طريقها، كما أن صدر السورة خاطب النبي والأمة معًا؛ فناسب خطاب الجمع ﴿ذلكم﴾ وحذف التبعيض.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص334، تحت «بلاغة التشابه في سورة الطلاق، وسورة البقرة»","url":""}]},{"id":"s2-1187","number":1187,"surah":2,"verses":[232],"references":[{"surah":2,"verses":[232]}],"verseLabel":"البقرة: 232","question":"ما سرّ توجيه الخطاب إلى الجماعة في قوله تعالى: ﴿فَلَا تَعْضُلُوهُنَّ أَنْ يَنْكِحْنَ أَزْوَاجَهُنَّ﴾؟","answer":"الخطاب للأولياء وللمجتمع ومن يملك المنع؛ لأن العضل قد يصدر من الولي أو يتواطأ عليه المحيطون، فحمّل الجماعة مسؤولية رفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص615، تحت «عود الضمير في فعل العضل»","url":""}]},{"id":"s2-1188","number":1188,"surah":2,"verses":[232],"references":[{"surah":2,"verses":[232]}],"verseLabel":"البقرة: 232","question":"ما سرّ إطلاق ﴿أَزْوَاجَهُنَّ﴾ بعد انتهاء الزواج؟","answer":"باعتبار ما كان وما يراد أن يعود، وفي اللفظ تذكير بأن المانع يقطع رابطة عرفها الطرفان ويرتضيان استئنافها، لا أنه يحميها من غريب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص617، تحت «بلاغة المجاز المرسل في قوله «أن ينكحن أزواجهن»»","url":""}]},{"id":"s2-1189","number":1189,"surah":2,"verses":[232],"references":[{"surah":2,"verses":[232]}],"verseLabel":"البقرة: 232","question":"ما سرّ التعبير في قوله تعالى: ﴿ذَلِكُمْ أَزْكَى لَكُمْ وَأَطْهَرُ﴾ ثم ﴿وَاللَّهُ يَعْلَمُ وَأَنْتُمْ لَا تَعْلَمُونَ﴾؟","answer":"ترك العضل أطهر من الضغينة والريبة وأزكى للعلاقات، ولو خالف تقديرات الناس العاجلة؛ فختم بعلم الله ليقدم حكمة الشرع على ظنون الأسرة والمجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص624، تحت «دلالة عبارة التذييل»","url":""}]},{"id":"s2-1190","number":1190,"surah":2,"verses":[233],"references":[{"surah":2,"verses":[233]}],"verseLabel":"البقرة: 233","question":"ما سرّ التعبير في قوله تعالى: ﴿حولين كاملين﴾ لا سنتين؟","answer":"اختير ﴿حولين﴾ لما في الحول من معنى دوران الزمن والتحول، وهو مناسب لتحول الرضيع وتدرجه في النمو، ووصفا بـ﴿كاملين﴾ لدفع توهم نقص شيء من المدة المقررة لتمام الرضاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص635، تحت «سر التعبير بالحول دون السنة»","url":""}]},{"id":"s2-1191","number":1191,"surah":2,"verses":[233],"references":[{"surah":2,"verses":[233]}],"verseLabel":"البقرة: 233","question":"لماذا عبّر عن الأب بـ﴿المولود له﴾ لا الوالد؟","answer":"نسب الولد إليه ليجعل هذه النسبة نفسها علة وجوب النفقة عليه، فيوازن جهد الأم الجسدي بمسؤوليته المالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص641، تحت «سر التعبير عن الوالد بالمولود له»","url":""}]},{"id":"s2-1192","number":1192,"surah":2,"verses":[233],"references":[{"surah":2,"verses":[233]}],"verseLabel":"البقرة: 233","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تكلف نفس إلا وسعها﴾ لا طاقتها؟","answer":"الوسع ما يسع الإنسان فعله بلا حرج بالغ، أما الطاقة فقد تشمل أقصى ما يقدر عليه بمشقة؛ فاختير الأرفق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص638، تحت «وجه العدول عن لفظ الطاقة إلى الوسع»","url":""}]},{"id":"s2-1193","number":1193,"surah":2,"verses":[233],"references":[{"surah":2,"verses":[233]}],"verseLabel":"البقرة: 233","question":"ما سرّ التعبير في قوله تعالى: ﴿وعلى الوارث مثل ذلك﴾ لا: على القريب؟","answer":"الوارث وصف قانوني يحدد من يخلف الأب في المسؤولية بحسب الصلة والحق، أما القريب فلفظ واسع لا يضبط من يلزم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص643، تحت «قصدية التعبير بلفظ «الوارث» دون لفظ (القريب)»","url":""}]},{"id":"s2-1194","number":1194,"surah":2,"verses":[233],"references":[{"surah":2,"verses":[233]},{"surah":65,"verses":[6]}],"verseLabel":"البقرة: 233، الطلاق: 6","question":"ما سرّ التعبير في قوله تعالى في البقرة عن المرضعات: ﴿وَعَلَى الْمَوْلُودِ لَهُ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ﴾، وقال للمطلقات في سورة الطلاق: ﴿فَآتُوهُنَّ أُجُورَهُنَّ﴾؟","answer":"آية الطلاق تتحدث عن امرأة انفصلت عرى الزوجية بينها وبين الأب؛ فإذا أرضعت ولده صارت خدمتها المستقلة مستحقة لأجرة صريحة. أما البقرة فتؤصل مسؤولية الأبوين المشتركة، وتسمي الأم ﴿والدة﴾ والأب ﴿المولود له﴾؛ فعبّرت عن حقها بالنفقة والكسوة في منظومة الحقوق الأسرية المتقابلة، لا بأجرة عمل منفصل. اختلاف اللفظ يكشف اختلاف العلاقة في السياقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص648، تحت «توجيه متشابه النظم بين هذه الآية من البقرة، وآية سورة الطلاق»","url":""}]},{"id":"s2-1195","number":1195,"surah":2,"verses":[233],"references":[{"surah":2,"verses":[233]}],"verseLabel":"البقرة: 233","question":"هل التعريف في قوله تعالى: ﴿وَالْوَالِدَاتُ يُرْضِعْنَ﴾ للعموم أم للعهد؟","answer":"تحتمل «أل» الجنس فتشمل الوالدات جميعًا، وتحتمل العهد فيراد المطلقات المذكورات في السياق. ويرجح المبحث حملها على الأمهات المطلقات لاتصالها بأحكام الطلاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص633، تحت «التعريف بـ(أل) بين العموم والخصوص في قول الله تعالى: ﴿والوالدات﴾»","url":""}]},{"id":"s2-1196","number":1196,"surah":2,"verses":[233],"references":[{"surah":2,"verses":[233]}],"verseLabel":"البقرة: 233","question":"ما سرّ التعبير في قوله تعالى: ﴿حَوْلَيْنِ كَامِلَيْنِ﴾، أليست التثنية كافية؟","answer":"دفع توهم التساهل في كسر شيء من العامين، وأكد أن هذه مدة تمام الرضاع لمن أراده؛ فـ﴿كاملين﴾ تحفظ حق الطفل وتحدد نهاية الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص637، تحت «فائدة تحديد ميقات الرضاعة بالحولين»","url":""}]},{"id":"s2-1197","number":1197,"surah":2,"verses":[233],"references":[{"surah":2,"verses":[233]}],"verseLabel":"البقرة: 233","question":"ما دلالة احتمال البناء للفاعل والمفعول في قوله تعالى: ﴿لا تضار والدة بولدها ولا مولود له بولده﴾؟","answer":"تحتمل الصيغة النهي عن أن يضر أحد الوالدين صاحبه بسبب الولد، والنهي عن أن يقع الضرر عليه بسبب عطفه على ولده وحنوه عليه؛ فتمنع المضارة من كلا الطرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص639–640، تحت عنوان «بلاغة التعبير عن المضارة بصيغة المفاعلة، ووجه القراءتين فيها»","url":""}]},{"id":"s2-1523","number":1523,"surah":2,"verses":[233],"references":[{"surah":2,"verses":[233]}],"verseLabel":"البقرة: 233","question":"ما دلالة إضافة الولد إلى كل من الوالدين في قوله تعالى: ﴿بولدها﴾ و﴿بولده﴾؟","answer":"تستثير الإضافة محبة الولد الفطرية في قلبي والديه وتستعطفهما عليه؛ فهو ولدهما معًا، وحقيق بأن يتفقا على إصلاح شأنه، فلا يجعلانه سببًا للإضرار أو وسيلة للكيد والإعنات.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص640، تحت عنوان «دلالة إضافة الولد إلى الوالدين»","url":""}]},{"id":"s2-1198","number":1198,"surah":2,"verses":[233],"references":[{"surah":2,"verses":[233]}],"verseLabel":"البقرة: 233","question":"لماذا اشترط في الفصال ﴿تَرَاضٍ مِنْهُمَا وَتَشَاوُرٍ﴾؟","answer":"لأن مصلحة الطفل لا يقررها طرف منفرد؛ فالتراضي يمنع الإكراه، والتشاور يطلب تقدير الأصلح قبل القرار. وجمعهما يفرق بين مجرد الموافقة والقرار المبني على نظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص643، تحت «بيان رخصة الفصال بين التراضي، والتشاور»","url":""}]},{"id":"s2-1199","number":1199,"surah":2,"verses":[234],"references":[{"surah":2,"verses":[234]}],"verseLabel":"البقرة: 234","question":"ما سرّ التعبير في قوله تعالى: ﴿ويذرون أزواجًا﴾ لا: يتركون أرامل؟","answer":"سماهن ﴿أزواجًا﴾ باعتبار رابطة الزوجية التي كانت قائمة قبل الموت؛ ليستدعي اللفظ الألفة وذكريات العشرة والوفاء للزوج الذي انتهى الموت مسيرتهما المشتركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص657، تحت «سر العدول عن التعبير بالزوجات إلى الأزواج»","url":""}]},{"id":"s2-1200","number":1200,"surah":2,"verses":[234],"references":[{"surah":2,"verses":[234]}],"verseLabel":"البقرة: 234","question":"لماذا كانت عدة الوفاة ﴿أربعة أشهر وعشرًا﴾ ولم يقل: عشرة أيام؟","answer":"حذف المعدود للعلم بأن المراد عشر ليال بأيامها، وجاء العدد مذكرًا لأن الليالي تغلب في ابتداء حساب الشهور، ولأن لفظ ﴿عشر﴾ أخف في النطق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص659، تحت «علة تذكير العدد»","url":""}]},{"id":"s2-1201","number":1201,"surah":2,"verses":[234],"references":[{"surah":2,"verses":[234]}],"verseLabel":"البقرة: 234","question":"ما فائدة قوله تعالى: ﴿بِأَنْفُسِهِنَّ﴾ في التعبير عن تربص المتوفى عنهن أزواجهن؟","answer":"يؤكد أن النساء أنفسهن مأمورات بمباشرة التربص والانتظار، ويدفع توهم أن غيرهن يباشر ذلك بهن؛ فيكون التريث صادرًا عنهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص658، تحت «سر التعبير بجمع القلة ﴿بأنفسهن﴾»","url":""}]},{"id":"s2-1202","number":1202,"surah":2,"verses":[234],"references":[{"surah":2,"verses":[234]}],"verseLabel":"البقرة: 234","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِذَا بَلَغْنَ أَجَلَهُنَّ﴾، دون أن يقال «قاربن» كما في المطلقات؟","answer":"بلوغ الأجل هنا انقضاء العدة حقيقة، لأن ما بعدها رفع للحرج عن تصرف المرأة؛ أما آيات الطلاق فالمقام مقام قرار الإمساك أو التسريح قرب النهاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص660، تحت «بلاغة الاستعارة التبعية في قوله «بلغن»»","url":""}]},{"id":"s2-1203","number":1203,"surah":2,"verses":[234],"references":[{"surah":2,"verses":[234]}],"verseLabel":"البقرة: 234","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنْفُسِهِنَّ بِالْمَعْرُوفِ﴾؟","answer":"رفع المسؤولية عن الأولياء بعد تمام العدة وأعاد للمرأة حرية شأنها في حدود المعروف، فلا ولاية تمنعها من زينة أو زواج مشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص664، تحت «من متشابه النظم القرآني تعريف لفظ «المعروف» وتنكيره»","url":""}]},{"id":"s2-1204","number":1204,"surah":2,"verses":[235],"references":[{"surah":2,"verses":[235]}],"verseLabel":"البقرة: 235","question":"ما سرّ التعبير في قوله تعالى: ﴿أو أكننتم في أنفسكم﴾ لا: كننتم؟","answer":"الإكنان إخفاء الشيء وصونه في باطن النفس، وهو أدق من مجرد الستر؛ ففرق بين خاطر مكتوم وقول أو وعد ظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص675، تحت «وجه التعبير «أكننتم» دون (كتمتم)»","url":""}]},{"id":"s2-1205","number":1205,"surah":2,"verses":[235],"references":[{"surah":2,"verses":[235]}],"verseLabel":"البقرة: 235","question":"لماذا فرّق بين ﴿عَرَّضْتُمْ بِهِ مِنْ خِطْبَةِ النِّسَاءِ﴾ و﴿أَكْنَنْتُمْ فِي أَنْفُسِكُمْ﴾؟","answer":"أباح الإشارة المحتملة وكتمان الرغبة، ومنع التصريح والعقد في العدة؛ فاختلاف اللفظ يرسم درجات ما في النفس وما يظهر على اللسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص674، تحت «سر عطف الإكنان على التعريض»","url":""}]},{"id":"s2-1206","number":1206,"surah":2,"verses":[235],"references":[{"surah":2,"verses":[235]}],"verseLabel":"البقرة: 235","question":"ما سرّ التعبير في قوله تعالى: ﴿عَلِمَ اللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ﴾؟","answer":"راعى طبيعة النفس وأن الرغبة ستظهر، فلم يكلفها بمحو الخاطر بل ضبط طريقة التعبير عنه. والسين تصور الأمر المتوقع الذي جاء التشريع لتنظيمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص675، تحت «بلاغة التعبير بلفظ «ستذكرونهن»»","url":""}]},{"id":"s2-1207","number":1207,"surah":2,"verses":[235],"references":[{"surah":2,"verses":[235]}],"verseLabel":"البقرة: 235","question":"لماذا استثنى: ﴿إِلَّا أَنْ تَقُولُوا قَوْلًا مَعْرُوفًا﴾ بعد النهي عن المواعدة سرًا؟","answer":"أخرج من المواعدة المحرمة قولًا منضبطًا لا فحش فيه ولا إلزام ولا تصريح يعارض حرمة العدة؛ فالمعروف معيار اللفظ والقصد معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص677، تحت «وجه الاستثناء في قوله تعالى: «إلا أن تقولوا قولًا معروفًا»»","url":""}]},{"id":"s2-1208","number":1208,"surah":2,"verses":[235],"references":[{"surah":2,"verses":[235]}],"verseLabel":"البقرة: 235","question":"لماذا ختم بـ﴿وَاعْلَمُوا أَنَّ اللَّهَ غَفُورٌ حَلِيمٌ﴾ بعد التحذير من علمه؟","answer":"جمع الهيبة والرجاء: يعلم خفايا النفوس فاحذروه، لكنه يغفر الخاطر أو الزلة لمن رجع ويحلم فلا يعاجل بالعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص680، تحت «قصدية التعبير عن مغفرته تعالى بصيغة المبالغة»","url":""}]},{"id":"s2-1209","number":1209,"surah":2,"verses":[236],"references":[{"surah":2,"verses":[236]}],"verseLabel":"البقرة: 236","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا جُنَاحَ عَلَيْكُمْ إِنْ طَلَّقْتُمُ النِّسَاءَ مَا لَمْ تَمَسُّوهُنَّ﴾؟","answer":"تقرر الجملة رفع الحرج عن الطلاق قبل الدخول، سواء سُمّي المهر أم لم يسمّ. وجاء الشرط بـ«إن» للإيماء إلى أن وقوع هذا الطلاق غير مستحب إلا عند الضرورة، لما فيه من كسر القلوب؛ فصُوّر في صورة الأمر النادر المشكوك في حصوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص685، تحت عنوان «سر التعبير بـ﴿إن﴾ الشرطية»","url":""}]},{"id":"s2-1210","number":1210,"surah":2,"verses":[236],"references":[{"surah":2,"verses":[236]}],"verseLabel":"البقرة: 236","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَتِّعُوهُنَّ عَلَى الْمُوسِعِ قَدَرُهُ وَعَلَى الْمُقْتِرِ قَدَرُهُ﴾؟","answer":"ساوى في أصل المواساة وراعى تفاوت القدرة في مقدارها؛ فكرر البناء لتظهر مسؤولية الغني والفقير معًا من غير إجحاف بأحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص687، تحت «دلالة الأمر في الآية الكريمة للوجوب»","url":""}]},{"id":"s2-1211","number":1211,"surah":2,"verses":[236],"references":[{"surah":2,"verses":[236]}],"verseLabel":"البقرة: 236","question":"لماذا وصف المتاع بأنه ﴿حَقًّا عَلَى الْمُحْسِنِينَ﴾؟","answer":"جعله حقًا مؤكدًا ثم نسب أداءه إلى الإحسان، لأن المؤمن لا يقف عند براءة الذمة بل يجبر خاطر من فارقها قبل اكتمال الزواج.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص689، تحت «علة التذييل بلفظ المحسنين»","url":""}]},{"id":"s2-1212","number":1212,"surah":2,"verses":[237],"references":[{"surah":2,"verses":[237]}],"verseLabel":"البقرة: 237","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن طلقتموهن﴾ بـ﴿إن﴾ لا ﴿إذا﴾؟","answer":"لأن الطلاق قبل المسيس فرضٌ طارئ غير مرغوب ولا متيقن، فناسبته أداة الاحتمال لا أداة المتوقع الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص694، تحت «سر العدول عن التعبير «وإن» دون (إذا)»","url":""}]},{"id":"s2-1213","number":1213,"surah":2,"verses":[237],"references":[{"surah":2,"verses":[237]}],"verseLabel":"البقرة: 237","question":"لماذا أوجب نصف المهر إذا وقع الطلاق قبل المسيس بعد فرضه؟","answer":"لأن العقد والفرض أنشآ حقًا، وعدم الدخول خفف الكمال إلى النصف؛ فجمع الحكم بين احترام الالتزام ومراعاة أن الزواج لم يكتمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص694، تحت «علة عدم التصريح بوجوب دفع نصف المهر»","url":""}]},{"id":"s2-1214","number":1214,"surah":2,"verses":[237],"references":[{"surah":2,"verses":[237]}],"verseLabel":"البقرة: 237","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَّا أَنْ يَعْفُونَ أَوْ يَعْفُوَ الَّذِي بِيَدِهِ عُقْدَةُ النِّكَاحِ﴾؟","answer":"فتح للطرفين باب تجاوز الحد المالي بالفضل: للمرأة ترك نصفها، ولمن بيده العقد إتمام المهر؛ فالعفو هنا تحرير للعلاقة من الحساب المجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص695، تحت «مرجع الضمير في قوله تعالى: «أو يعفو الذي بيده عقدة النكاح»»","url":""}]},{"id":"s2-1215","number":1215,"surah":2,"verses":[237],"references":[{"surah":2,"verses":[237]}],"verseLabel":"البقرة: 237","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوَى﴾؟","answer":"لأن العفو عند الخصومة دليل قدرة النفس على كبح الشح والانتقام، فجعله طريقًا أقرب إلى التقوى لا مجرد تنازل اجتماعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص697، تحت «الحكمة من التنازل عن الحقوق في هذه الحالة»","url":""}]},{"id":"s2-1216","number":1216,"surah":2,"verses":[237],"references":[{"surah":2,"verses":[237]}],"verseLabel":"البقرة: 237","question":"لماذا ختم أحكام المهر بقوله: ﴿وَلَا تَنْسَوُا الْفَضْلَ بَيْنَكُمْ﴾؟","answer":"حتى لا تمحو لحظة الفراق ما كان من مودة وإحسان؛ فالحقوق تحد الأدنى، والفضل يحفظ الإنسانية بعد انقطاع العقد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص698، تحت «فائدة عطف التذييل على التذييل»","url":""}]},{"id":"s2-1217","number":1217,"surah":2,"verses":[238],"references":[{"surah":2,"verses":[238]}],"verseLabel":"البقرة: 238","question":"ما سرّ التعبير في قوله تعالى: ﴿حافظوا على الصلوات والصلاة الوسطى﴾ فخص صلاة بعد جمع الصلوات؟","answer":"عطف الخاص على العام لمزيد العناية بصلاة تتعرض للتفويت أو تتوسط الصلوات، مع بقاء المحافظة شاملة للجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص709، تحت «علة جمع الصلوات في الأول، وإفراد الصلاة في الثاني»","url":""}]},{"id":"s2-1218","number":1218,"surah":2,"verses":[238],"references":[{"surah":2,"verses":[238]}],"verseLabel":"البقرة: 238","question":"لماذا اختار الصلاة من بين العبادات في وسط أحكام الأسرة؟","answer":"لأنها تجدد التقوى التي تضبط الطلاق والحقوق عند الغضب، وتعيد القلب من نزاع العلاقات إلى الوقوف بين يدي الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص708، تحت «نكتة اختيار الصلاة دون غيرها من العبادات»","url":""}]},{"id":"s2-1219","number":1219,"surah":2,"verses":[238],"references":[{"surah":2,"verses":[238]}],"verseLabel":"البقرة: 238","question":"ما سرّ التعبير في قوله تعالى: ﴿وَقُومُوا لِلَّهِ قَانِتِينَ﴾؟","answer":"لم يكتف بأداء الصلاة، بل طلب قيامًا خالصًا لله مصحوبًا بالخضوع والسكينة؛ فاللام تصفي الجهة و﴿قانتين﴾ تصف هيئة الظاهر والباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص711، تحت «وجه تقديم لفظ الجلالة المجرور على لفظ القنوت»","url":""}]},{"id":"s2-1220","number":1220,"surah":2,"verses":[239],"references":[{"surah":2,"verses":[239]}],"verseLabel":"البقرة: 239","question":"ما سرّ التعبير في قوله تعالى في حال الخوف ﴿فرجالًا أو ركبانا﴾ ثم أمر بالذكر بعد الأمن؟","answer":"خفف الهيئة ولم يسقط الصلاة في الخطر، ثم أعادها إلى كمالها مع شكر نعمة الأمن؛ فجمع دوام العبادة ومرونة صورتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص718، تحت «لفظ الذكر بين التخصيص بالصلاة، وبين الإعمام بغيره»","url":""}]},{"id":"s2-1221","number":1221,"surah":2,"verses":[239],"references":[{"surah":2,"verses":[239]}],"verseLabel":"البقرة: 239","question":"لماذا رخص في الخوف: ﴿فَرِجَالًا أَوْ رُكْبَانًا﴾؟","answer":"لأن الصلاة لا تسقط بالخطر، لكن هيئتها تتكيف معه؛ فذكر حالتي المشي والركوب ليشمل ما تسمح به القدرة. وفي الإيجاز جمع بين المحافظة والتيسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص716، تحت «تأكيد المحافظة على الصلاة وذكر الله، حتى في أشد حالات الخوف»","url":""}]},{"id":"s2-1222","number":1222,"surah":2,"verses":[239],"references":[{"surah":2,"verses":[239]}],"verseLabel":"البقرة: 239","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِذَا أَمِنْتُمْ فَاذْكُرُوا اللَّهَ﴾، دون أن يقال «فصلوا»؟","answer":"الذكر أعم وهو روح الصلاة، فيشمل العودة إلى هيئتها الكاملة وشكر نعمة الأمن. واختيار اللفظ يصل عبادة الخوف بعبادة الطمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص718، تحت «لفظ الذكر بين التخصيص بالصلاة، وبين الاهتمام بغيره»","url":""}]},{"id":"s2-1223","number":1223,"surah":2,"verses":[239],"references":[{"surah":2,"verses":[239]}],"verseLabel":"البقرة: 239","question":"لماذا ختم بـ﴿كَمَا عَلَّمَكُمْ مَا لَمْ تَكُونُوا تَعْلَمُونَ﴾؟","answer":"جعل تعليم الصلاة وسائر الشرائع نعمة تستوجب الذكر، فكما أخرجهم من الجهل يشكرونه بالطاعة. والتشبيه يربط مقدار الشكر بعظمة التعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص720، تحت «بلاغة التشبيه في الآية الكريمة»","url":""}]},{"id":"s2-1224","number":1224,"surah":2,"verses":[240],"references":[{"surah":2,"verses":[240]}],"verseLabel":"البقرة: 240","question":"ما سرّ التعبير في قوله تعالى: ﴿متاعًا إلى الحول﴾ بالحول لا السنة؟","answer":"الحول دورة زمنية محسوبة من لحظة الوفاة، وهو الأنسب لمدة حق السكنى والنفقة، لا سنة تقويمية قد بدأ بعضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص732، تحت «سر العدول إلى التعبير «الحول» بدل (السنة)»","url":""}]},{"id":"s2-1225","number":1225,"surah":2,"verses":[240],"references":[{"surah":2,"verses":[240]}],"verseLabel":"البقرة: 240","question":"لماذا جاءت وصية المتوفى لزوجته بـ﴿مَتَاعًا إِلَى الْحَوْلِ غَيْرَ إِخْرَاجٍ﴾؟","answer":"يبين المصدر أن الوصية كانت لتمكين الزوجة من السكنى في منزل زوجها سنة كاملة من وفاته، دون إخراجها، جبرًا لخاطرها مع إبقاء اختيار الخروج لها. ثم يذكر نسخ هذا الحكم بآية العدة، ونسخ الوصية بما فُرض لها من الميراث.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص727–728، تحت عنوان «وصية المتوفى للورثة بنفقة زوجته والتكفل بها حولًا؛ إذا آثرت البقاء في بيت الزوجية»","url":""}]},{"id":"s2-1226","number":1226,"surah":2,"verses":[240],"references":[{"surah":2,"verses":[240]}],"verseLabel":"البقرة: 240","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ﴾؟","answer":"فرق بين إخراجها قسرًا، وهو المنهي عنه، وبين خروجها باختيارها بعد تحقق الحق؛ فرفع الحرج عن الأولياء فيما تستقل به من شأنها المعروف.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص732، تحت «(إن) الشرطية تشير إلى استحباب تنفيذ الزوجات الوصية»","url":""}]},{"id":"s2-1227","number":1227,"surah":2,"verses":[240],"references":[{"surah":2,"verses":[240]}],"verseLabel":"البقرة: 240","question":"لماذا ختم بـ﴿عَزِيزٌ حَكِيمٌ﴾؟","answer":"العزيز يتوعّد من يخالف الحكم، فيمنع إنفاذ الوصية أو يُخرج المرأة؛ والحكيم وضع هذا الحكم في موضعه ومنع مجاوزته، فجمعت الفاصلة قوة الإنفاذ وإحكام التشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص734، تحت عنوان «نكتة الوعيد الشديد في جمل التذييل»","url":""}]},{"id":"s2-1228","number":1228,"surah":2,"verses":[241],"references":[{"surah":2,"verses":[241]}],"verseLabel":"البقرة: 241","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِلْمُطَلَّقَاتِ مَتَاعٌ بِالْمَعْرُوفِ﴾ بعد تفصيل أحوال الطلاق؟","answer":"ختم التفصيل بقاعدة عامة تحفظ جبر خاطر المطلقة بحسب المعروف، فلا تضيع حالة لم يصرح بها. وتقديم ﴿للمطلقات﴾ يثبت الحق لهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص738، تحت «يجب على الزوج متعة الطلاق، وأن يلتزم بالتقوى عند الفراق»","url":""}]},{"id":"s2-1229","number":1229,"surah":2,"verses":[241],"references":[{"surah":2,"verses":[241]}],"verseLabel":"البقرة: 241","question":"ما سرّ التعبير في قوله تعالى: ﴿حَقًّا عَلَى الْمُتَّقِينَ﴾، وفي الآية 236: ﴿عَلَى الْمُحْسِنِينَ﴾؟","answer":"هناك برز الإحسان في جبر من طلقت قبل الدخول، وهنا ختمت منظومة الحدود بالتقوى التي تدفع إلى أداء حق كل مطلقة؛ فاختلف الوصف باختلاف زاوية السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص741، تحت «سر تخصيص الحق بالمتقين»","url":""}]},{"id":"s2-1230","number":1230,"surah":2,"verses":[242],"references":[{"surah":2,"verses":[242]}],"verseLabel":"البقرة: 242","question":"ما سرّ التعبير في قوله تعالى: ﴿كَذَلِكَ يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ﴾ بعد أحكام الأسرة؟","answer":"شبّه البيان الآتي بالبيان المتقدم في تفصيل الأحكام؛ فكما بيّن الله ما سبق يبيّن سائر آياته، وفي ذلك تصوير لدوام البيان وتوجيه إلى الرحمة والعدل والفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص741، تحت «بلاغة التشبيه في الآية الكريمة»","url":""}]},{"id":"s2-1231","number":1231,"surah":2,"verses":[242],"references":[{"surah":2,"verses":[242]}],"verseLabel":"البقرة: 242","question":"لماذا كانت الغاية: ﴿لَعَلَّكُمْ تَعْقِلُونَ﴾؟","answer":"جيء بـ﴿لعل﴾ لإلهاب المخاطبين وتهييجهم إلى التفكر، ولفظ ﴿تعقلون﴾ يتضمن فهم ما فُرض والعمل به؛ فالعاقل يستعمل ما علمه من الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص742، تحت «سر التعبير بجملة الرجاء»","url":""}]},{"id":"s2-1232","number":1232,"surah":2,"verses":[243],"references":[{"surah":2,"verses":[243]}],"verseLabel":"البقرة: 243","question":"ما سرّ التعبير في قوله تعالى عن الخارجين من ديارهم ﴿وهم ألوف حذر الموت﴾ ثم أماتهم الله؟","answer":"جمع كثرتهم وسبب فرارهم ليهدم وهم أن العدد والحيلة يدفعان الأجل؛ جاءهم الموت من الجهة التي هربوا منها ثم أراهم الإحياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص751، تحت «علة إماتة الذين خرجوا ثم إحيائهم»","url":""}]},{"id":"s2-1233","number":1233,"surah":2,"verses":[243],"references":[{"surah":2,"verses":[243]},{"surah":10,"verses":[60]},{"surah":27,"verses":[73]},{"surah":40,"verses":[61]}],"verseLabel":"البقرة: 243، يونس: 60، النمل: 73، غافر: 61","question":"لماذا كرر لفظ ﴿النَّاسِ﴾ في البقرة: ﴿إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَشْكُرُونَ﴾، بينما قال في يونس والنمل: ﴿ولكن أكثرهم﴾ بالضمير؟","answer":"تحويله إلى سؤال وصفي محقق: «أين كرر القرآن لفظ الناس في هذه الخاتمة، وأين أضمره؟» والجواب: «كرر الاسم الظاهر في البقرة: 243 وغافر: 61، وقال ﴿أكثرهم﴾ في يونس: 60 والنمل: 73»؛ ويحذف التعليل البلاغي غير المسند حتى يوجد نص مباشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص418، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-1234","number":1234,"surah":2,"verses":[243],"references":[{"surah":2,"verses":[243]}],"verseLabel":"البقرة: 243","question":"لماذا افتتح قصة الخارجين من ديارهم بـ﴿أَلَمْ تَرَ﴾ مع أن المخاطب لم يشاهدها؟","answer":"نزّل الخبر الموثوق منزلة المشاهد ليستحضر السامع غرابة القصة وعبرتها، والاستفهام يشوقه إلى مشهد ألوف يهربون من الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص748، تحت «بلاغة أسلوب الاستفهام»","url":""}]},{"id":"s2-1235","number":1235,"surah":2,"verses":[243],"references":[{"surah":2,"verses":[243]}],"verseLabel":"البقرة: 243","question":"لماذا ختم القصة بقوله: ﴿وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَشْكُرُونَ﴾؟","answer":"الإحياء والإنذار فضل، لكن أكثر الناس لا يحولون معرفة قدرة الله إلى شكر وطاعة. والاستدراك يكشف التفاوت بين عموم الفضل وقلة الاستجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص754، تحت «الاستدراك للتوبيخ، وتأكيد العموم في قوله: «ولكن أكثر الناس لا يشكرون»»","url":""}]},{"id":"s2-1236","number":1236,"surah":2,"verses":[244],"references":[{"surah":2,"verses":[244]}],"verseLabel":"البقرة: 244","question":"لماذا أعقب قصة الموت والحياة بالأمر ﴿وقاتلوا في سبيل الله﴾؟","answer":"القصة تحرر المؤمن من جبن الفرار: لا يقدم القتال أجلًا ولا يؤخر الهرب موتًا، فبني عليها الأمر بالفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص757، تحت «مناسبة بين الأمر بالقتال المذكور، والتأكيد بأن لا فرار من الموت المقدور»","url":""}]},{"id":"s2-1237","number":1237,"surah":2,"verses":[244],"references":[{"surah":2,"verses":[244]}],"verseLabel":"البقرة: 244","question":"لماذا ختم بـ﴿وَاعْلَمُوا أَنَّ اللَّهَ سَمِيعٌ عَلِيمٌ﴾؟","answer":"خُتم بالأمر بالعلم بأن الله سميع للأقوال وعليم بالبواطن والمقاصد؛ ليكون ذلك تحريضًا على الامتثال، وتحذيرًا من التقصير، ودعوةً إلى محاسبة النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص761، تحت «علة افتتاح جملة التذييل بفعل الأمر «واعلموا»»","url":""}]},{"id":"s2-1238","number":1238,"surah":2,"verses":[245],"references":[{"surah":2,"verses":[245]}],"verseLabel":"البقرة: 245","question":"لماذا سمّى الإنفاق قرضًا لله مع أن الله هو مالك المال؟","answer":"سمّى الإنفاق قرضًا تشريفًا للمنفق واستلطافًا له وضمانًا للوفاء والمضاعفة؛ فكأن ما بذله دين محفوظ عند الله لا يضيع، مع أن الله غني ومالك المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص769، تحت «حكمة احتمال لفظ القرض للحقيقة والمجاز»","url":""}]},{"id":"s2-1239","number":1239,"surah":2,"verses":[245],"references":[{"surah":2,"verses":[245]}],"verseLabel":"البقرة: 245","question":"ما سرّ التعبير في قوله تعالى: ﴿فيضاعفه له أضعافًا كثيرة﴾ ولم يحدد عدد المضاعفة؟","answer":"أبهم مقدار المضاعفة لأن الإبهام أقوى في الترغيب من ذكر حد معين، ويفتح باب الرجاء في فضل الله ومضاعفته الكثيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص770، تحت «نكتة الإبهام في مقدار المضاعفة»","url":""}]},{"id":"s2-1240","number":1240,"surah":2,"verses":[245],"references":[{"surah":2,"verses":[245]},{"surah":57,"verses":[11]}],"verseLabel":"البقرة: 245، الحديد: 11","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿فَيُضَاعِفَهُ لَهُ أَضْعَافًا كَثِيرَةً﴾، وقوله تعالى في الحديد: ﴿فَيُضَاعِفَهُ لَهُ وَلَهُ أَجْرٌ كَرِيمٌ﴾؟","answer":"آية البقرة جاءت في سياق الجهاد والحاجة إلى تحريك النفوس لبذل المال؛ فوجهت النظر إلى الكم، وصرحت بأضعاف كثيرة غير محددة، ثم شرحت السورة صورة المضاعفة في مثل الحبة التي أنبتت سبع سنابل. أما الحديد فذكر المضاعفة بإطلاق، ثم نقل النظر إلى نوع الجزاء وقدره المعنوي فقال ﴿أجر كريم﴾؛ فجمع الوعد بالزيادة مع جلال الأجر وكرامته في سياق الحث العام على الإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص737، تحت «دلالة الاتفاق والاختلاف مع الآية245 من سورة البقرة»","url":""}]},{"id":"s2-1241","number":1241,"surah":2,"verses":[245],"references":[{"surah":2,"verses":[245]}],"verseLabel":"البقرة: 245","question":"لماذا ختم بـ﴿وَاللَّهُ يَقْبِضُ وَيَبْسُطُ وَإِلَيْهِ تُرْجَعُونَ﴾؟","answer":"من يخشى الفقر يعلم أن الرزق قبضًا وبسطًا بيد الله، وأن المال وصاحبه راجعان إليه؛ فالمقابلة تعالج سبب البخل من جذره.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص771، تحت «بيان التعريض في جملة التذييل»","url":""}]},{"id":"s2-1242","number":1242,"surah":2,"verses":[246],"references":[{"surah":2,"verses":[246]}],"verseLabel":"البقرة: 246","question":"ما سرّ قول بني إسرائيل ﴿ابعث لنا ملكًا﴾ لا: أرسل لنا؟","answer":"لأن البعث يلائم حال قوم خارت قواهم وتفرقت كلمتهم؛ ففيه معنى الإثارة والتحريك لإقامة قائد يجمعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص779، تحت «دلالة إيثار التعبير بلفظ «ابعث»، دون لفظ (أرسل)»","url":""}]},{"id":"s2-1243","number":1243,"surah":2,"verses":[246],"references":[{"surah":2,"verses":[246]}],"verseLabel":"البقرة: 246","question":"ما سرّ قول نبيهم ﴿هل عسيتم إن كتب عليكم القتال ألا تقاتلوا﴾ بـ﴿إن﴾؟","answer":"اختبر احتمال فرض ما يطلبونه قبل وقوعه، وكشف أن حماسة القول قد تنهار عند تحول الطلب إلى تكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص781، تحت «دلالة الاستفهام في قوله: «هل عسيتم»»","url":""}]},{"id":"s2-1244","number":1244,"surah":2,"verses":[246],"references":[{"surah":2,"verses":[246]}],"verseLabel":"البقرة: 246","question":"ما دلالة قولهم: ﴿وَقَدْ أُخْرِجْنَا مِنْ دِيَارِنَا وَأَبْنَائِنَا﴾، وجمعهم بين الديار والأبناء؟","answer":"جمعوا خسارة الوطن والأسرة ليقدموا أقوى دوافع القتال، فكأن الضرر أحاط بمكانهم ونسلهم معًا؛ ثم فضح التولي ضعف الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص786، تحت «وجه استقامة عطف الأبناء على الديار في قوله «وقد أخرجنا من ديارنا وأبنائنا»»","url":""}]},{"id":"s2-1245","number":1245,"surah":2,"verses":[246],"references":[{"surah":2,"verses":[246]}],"verseLabel":"البقرة: 246","question":"ما سرّ التعبير في قوله تعالى عن بني إسرائيل حين فُرض عليهم القتال: ﴿تَوَلَّوْا إِلَّا قَلِيلًا مِنْهُمْ﴾، دون أن يقال: «قعدوا»؟","answer":"﴿تولوا﴾ ترسم حركة الانصراف بعد أن كانوا هم الذين طلبوا القتال: كأنهم يديرون ظهورهم وينكصون حين جاء الجد. أما «قعدوا» فقد تصف مجرد ترك الخروج، ولا تحمل الصورة نفسها من الرجوع والتخلي بعد الطلب والوعد. لذلك اختير اللفظ الذي يجسد التناقض بين حماسة القول وفرار الفعل، ويجعل التوبيخ أوقع في نفس القارئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص787، تحت «براعة إيثار التعبير بـ«تولوا» دون غيره من متشابه اللفظ»","url":""}]},{"id":"s2-1246","number":1246,"surah":2,"verses":[246],"references":[{"surah":2,"verses":[246]}],"verseLabel":"البقرة: 246","question":"ما دلالة قولهم: ﴿وَقَدْ أُخْرِجْنَا مِنْ دِيَارِنَا وَأَبْنَائِنَا﴾، ولم يقولوا: «من بيوتنا» أو «مساكننا»؟","answer":"الدار أوسع من البيت والمسكن؛ فهي تشمل الأرض وما عليها من بناء، وقد تطلق على البلدة والوطن كله، أما البيت والمسكن فيلحظان موضع الإقامة خاصة. لذلك صوّرت ﴿ديارنا﴾ أن العدو لم يطردهم من مبانٍ مفردة فحسب، بل اقتلعهم من كامل أرضهم ومجال حياتهم، فكان اللفظ أبلغ في بيان شدة ما يدفعهم ــ في دعواهم ــ إلى القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص784، تحت «سر التعبير بالديار دون غيره من الألفاظ»","url":""}]},{"id":"s2-1247","number":1247,"surah":2,"verses":[246],"references":[{"surah":2,"verses":[246]}],"verseLabel":"البقرة: 246","question":"لماذا عاد أسلوب ﴿أَلَمْ تَرَ﴾ في قصة الملأ من بني إسرائيل؟","answer":"أعيد الأسلوب لتأكيد التحذير والتعريض بالتوبيخ، واستحضار قصة قوم طلبوا القتال ثم تقاعس أكثرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص778، تحت «دلالة الاستفهام في قوله تعالى: «ألم تر إلى الملإ»»","url":""}]},{"id":"s2-1248","number":1248,"surah":2,"verses":[246],"references":[{"surah":2,"verses":[246]}],"verseLabel":"البقرة: 246","question":"لماذا قالوا: ﴿ابْعَثْ لَنَا مَلِكًا﴾، دون «أرسل لنا ملكًا»؟","answer":"لأن البعث يتضمن الإثارة والتهييج، وهو أنسب بحال قوم ضعفت قوتهم وتفرق شملهم، فاحتاجوا إلى ملك يجمعهم ويوقظ عزيمتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص779–780، تحت «دلالة إيثار التعبير بلفظ ﴿ابعث﴾، دون لفظ (أرسل)»","url":""}]},{"id":"s2-1249","number":1249,"surah":2,"verses":[246],"references":[{"surah":2,"verses":[246]}],"verseLabel":"البقرة: 246","question":"لماذا ختم بقوله: ﴿وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ﴾ بعد تولي أكثرهم؟","answer":"خُتم بالعلم بالظالمين وعيدًا لمن قعد عن القتال بعد أن سأل فرضه، وكشفًا لتناقض قوله وفعله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص787، تحت «دلالة التذييل في قوله تعالى: «والله عليم بالظالمين»»","url":""}]},{"id":"s2-1250","number":1250,"surah":2,"verses":[247],"references":[{"surah":2,"verses":[247]}],"verseLabel":"البقرة: 247","question":"لماذا اعترضوا على ملك طالوت بفقره، فجاء الجواب بزيادة العلم والجسم لا المال؟","answer":"قلب معيار القيادة من النسب والثراء إلى علم يحسن التدبير وجسم يقدر على التنفيذ، وقدم العلم لأنه قائد القوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص795، تحت «علة الإجابة بذكر العلم والجسم، دون التعرض للمال»","url":""}]},{"id":"s2-1251","number":1251,"surah":2,"verses":[247],"references":[{"surah":2,"verses":[247]}],"verseLabel":"البقرة: 247","question":"ما سرّ قول نبيهم: ﴿إِنَّ اللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا﴾، ولم يقل: «أرسل لكم طالوت»؟","answer":"مادة ﴿بعث﴾ تتضمن الإثارة والتحريك والإخراج بعد خمول، بخلاف الإرسال الذي يغلب فيه معنى الانطلاق برفق وسهولة. وكان بنو إسرائيل قد ذلوا وتفرقت جماعتهم واستباح العدو أرضهم؛ فاحتاجوا إلى قائد يثير فيهم العزم وينفض عنهم غبار الهوان، لا إلى مجرد شخص يُرسَل إليهم. لذلك جسّد ﴿بعث﴾ الوظيفة المطلوبة من طالوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص794، تحت «سر إيثار لفظ «بعث» على لفظ «أرسل»»","url":""}]},{"id":"s2-1252","number":1252,"surah":2,"verses":[247],"references":[{"surah":2,"verses":[247]}],"verseLabel":"البقرة: 247","question":"لماذا قدّم الله العلم على قوة الجسم في وصف طالوت: ﴿وَزَادَهُ بَسْطَةً فِي الْعِلْمِ وَالْجِسْمِ﴾، مع أن قيادة الحرب تبدو أحوج إلى القوة البدنية؟","answer":"قُدّم العلم لأنه أساس سياسة الرعية وتدبير الحرب، ثم جاءت قوة الجسم أداةً للتنفيذ؛ فالقوة لا تستغني عن علم يوجهها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص795، تحت «سر تقديم العلم على الجسم»","url":""}]},{"id":"s2-1253","number":1253,"surah":2,"verses":[247],"references":[{"surah":2,"verses":[247]}],"verseLabel":"البقرة: 247","question":"اعترض بنو إسرائيل بأن طالوت ﴿لَمْ يُؤْتَ سَعَةً مِنَ الْمَالِ﴾؛ فلماذا لم يرد نبيهم بذكر ماله، وإنما قال: ﴿وَزَادَهُ بَسْطَةً فِي الْعِلْمِ وَالْجِسْمِ﴾؟","answer":"تجاهل الجواب معيارهم؛ لأن الغنى الشخصي ليس شرطًا لصلاح الحاكم. المال الذي تقوم به المملكة تجلبه الرعية ويكون في بيت مالها، أما ما لا يُستغنى عنه في القائد فهو علم يحسن به التدبير وقوة يقدر بها على التنفيذ والنصر. فكان الرد تصحيحًا لمقياسهم نفسه: أهلية القيادة لا تُشترى بالثروة، بل تقوم على الكفاءة التي اختاره الله لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص795، تحت «علة الإجابة بذكر العلم والجسم، دون التعرض للمال»","url":""}]},{"id":"s2-1254","number":1254,"surah":2,"verses":[247],"references":[{"surah":2,"verses":[247]}],"verseLabel":"البقرة: 247","question":"ما سرّ قول نبيهم: ﴿إِنَّ اللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا﴾؟","answer":"قدم اسم الله وأكد الخبر بـ﴿إن﴾ و﴿قد﴾ ليقرر أن الاختيار إلهي لا اقتراح بشري، وأن الملك بعث لمصلحتهم ولو خالف أهواءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص793، تحت «بديع توكيد الخبر بحشد المؤكدات»","url":""}]},{"id":"s2-1255","number":1255,"surah":2,"verses":[247],"references":[{"surah":2,"verses":[247]}],"verseLabel":"البقرة: 247","question":"لماذا اعترضوا بقولهم: ﴿أَنَّى يَكُونُ لَهُ الْمُلْكُ عَلَيْنَا﴾؟","answer":"الاستفهام بـ﴿أنى﴾ للاستبعاد والتعجب والتمرد على اختيار الله؛ إذ زعموا أنهم أحق بالملك، واعترضوا بفقر طالوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص794، تحت «نكتة اعتراض الأشراف بالاستفهام»","url":""}]},{"id":"s2-1256","number":1256,"surah":2,"verses":[247],"references":[{"surah":2,"verses":[247]}],"verseLabel":"البقرة: 247","question":"لماذا جعلوا معيار الملك: ﴿وَنَحْنُ أَحَقُّ بِالْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِنَ الْمَالِ﴾؟","answer":"بَنَوا اعتراضهم على اعتقاد أن الملك يستحق بشرف النسب وسعة المال؛ فزعموا أنهم أحق به لأن طالوت ليس من سلالة الملوك، واعترضوا بفقره وعدم امتلاكه الثروة التي تؤهله في نظرهم للملك.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص794، تحت عنوان «نكتة اعتراض الأشراف بالاستفهام»","url":""}]},{"id":"s2-1257","number":1257,"surah":2,"verses":[247],"references":[{"surah":2,"verses":[247]}],"verseLabel":"البقرة: 247","question":"لماذا أُكّد الجواب في قوله تعالى: ﴿إن الله اصطفاه عليكم وزاده بسطة في العلم والجسم﴾؟","answer":"لشدة إنكار بني إسرائيل اختيار طالوت ملكًا عليهم؛ فأكد نبيهم الخبر، وأتبعه بما يقوي إثباته من ذكر الزيادة والبسطة في العلم والجسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص795، تحت عنوان «توكيد الخبر؛ لأن المخاطب شديد الإنكار في قوله تعالى: ﴿إن الله اصطفاه عليكم﴾»","url":""}]},{"id":"s2-1258","number":1258,"surah":2,"verses":[247],"references":[{"surah":2,"verses":[247]}],"verseLabel":"البقرة: 247","question":"لماذا ختم بـ﴿وَاللَّهُ وَاسِعٌ عَلِيمٌ﴾؟","answer":"ملكه واسع يعطيه من يشاء ولا تحصره مقاييس الناس، وعلمه يضعه عند الأقدر لا الأغنى. الاسمان يجيبان اعتراضهم على الاختيار والرزق معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص796–797، تحت «وجه تقرير الحكم بجملة التذييل»","url":""}]},{"id":"s2-1259","number":1259,"surah":2,"verses":[248],"references":[{"surah":2,"verses":[248]}],"verseLabel":"البقرة: 248","question":"لماذا كانت علامة مُلك طالوت رجوع التابوت؟","answer":"لأن بني إسرائيل طلبوا من نبيهم حجة على أن الله اصطفى طالوت وملّكه عليهم، فجُعل إتيان التابوت علامةً على ذلك، وأُكد الخبر لأهميته ومراعاة حالهم في الإنكار والجدال.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص14، تحت عنوان «بلاغة تأكيد الخبر بإن، واسمية الجملة»","url":""}]},{"id":"s2-1260","number":1260,"surah":2,"verses":[248],"references":[{"surah":2,"verses":[248]}],"verseLabel":"البقرة: 248","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يأتيكم التابوت﴾ بالإتيان لا المجيء؟","answer":"عبّر بالإتيان لأنه مجيء سهل يسير لا مشقة فيه، فناسب مقام بيان سهولة إحضار التابوت بقدرة الله، بخلاف المجيء الذي تلحظ فيه المشقة والصعوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص13، تحت «سر التعبير بالإتيان دون المجيء»","url":""}]},{"id":"s2-1261","number":1261,"surah":2,"verses":[248],"references":[{"surah":2,"verses":[248]}],"verseLabel":"البقرة: 248","question":"ما سرّ التعبير في قوله تعالى: ﴿إن كنتم مؤمنين﴾ بـ﴿إن﴾ مع مطالبتهم بالآية؟","answer":"تعريض باختبار حقيقة إيمانهم: إن كانوا مصدقين بالله ونبيهم فهذه الآية كافية، وإلا فالمشكلة في العناد لا الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص17، تحت «سر التعبير بإن الشرطية دون إذا»","url":""}]},{"id":"s2-1262","number":1262,"surah":2,"verses":[248],"references":[{"surah":2,"verses":[248]}],"verseLabel":"البقرة: 248","question":"ما سرّ التعبير في قوله تعالى عن التابوت: ﴿فِيهِ سَكِينَةٌ مِنْ رَبِّكُمْ﴾، دون أن يقال: «من الله»؟","answer":"لفظ ﴿الرب﴾ يبرز معنى التدبير والرعاية والقيام بمصالح المربوب، وإضافته إليهم في ﴿ربكم﴾ تشعرهم بأن الذي اختار طالوت هو نفسه المتولي لأمرهم والمصلح لشأنهم. فناسب مقامَ اضطرابهم واعتراضهم أن يذكَّروا بربوبية الله الخاصة لهم؛ لتطمئن قلوبهم إلى اختياره وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص15، تحت «إيثار لفظ الرب، وقصدية إضافته إلى ضمير المخاطبين»","url":""}]},{"id":"s2-1263","number":1263,"surah":2,"verses":[248],"references":[{"surah":2,"verses":[248]}],"verseLabel":"البقرة: 248","question":"ما سرّ التعبير في قوله تعالى: ﴿فِيهِ سَكِينَةٌ مِنْ رَبِّكُمْ وَبَقِيَّةٌ مِمَّا تَرَكَ آلُ مُوسَى وَآلُ هَارُونَ﴾؟","answer":"جمع أثرًا معنويًا هو السكينة وآثارًا مادية من ميراث النبوة؛ ليخاطب القلب والحس معًا، وأضاف السكينة إلى ربهم ليجعل الطمأنينة عطاءً منه لا خاصية في الصندوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص15، تحت «وجه المجاز في لفظ السكينة»","url":""}]},{"id":"s2-1264","number":1264,"surah":2,"verses":[248],"references":[{"surah":2,"verses":[248]}],"verseLabel":"البقرة: 248","question":"ما سرّ التعبير في قوله تعالى: ﴿تَحْمِلُهُ الْمَلَائِكَةُ﴾؟","answer":"لأنهم طلبوا آية محسوسة على صدق اختيار الله لطالوت، فجاءهم التابوت بما فيه من سكينة وبقية من آثار موسى وهارون، تحمله الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص16، تحت «وجه الاستئناف في جملة «تحمله الملائكة»»","url":""}]},{"id":"s2-1265","number":1265,"surah":2,"verses":[249],"references":[{"surah":2,"verses":[249]}],"verseLabel":"البقرة: 249","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما فصل طالوت بالجنود﴾ لا: خرج بالجيش؟","answer":"لأن ﴿فصل﴾ لا تدل على مجرد الخروج، بل على القطع والبعد والمفارقة وترك الحال السابقة؛ فصورت انتقال الجيش من مقامه إلى مرحلة القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص28، تحت «سر التعبير بلفظ الجنود»","url":""}]},{"id":"s2-1266","number":1266,"surah":2,"verses":[249],"references":[{"surah":2,"verses":[249]}],"verseLabel":"البقرة: 249","question":"لماذا كان اختبار الجيش بنهر في طريق المعركة؟","answer":"كشف قدرتهم على ضبط شهوة عاجلة تحت العطش؛ فمن عجز عن أمر ماء يسير كان أبعد عن الثبات أمام العدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص29، تحت «معنى الابتلاء والمقصد منه»","url":""}]},{"id":"s2-1267","number":1267,"surah":2,"verses":[249],"references":[{"surah":2,"verses":[249]}],"verseLabel":"البقرة: 249","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن لم يطعمه فإنه مني﴾، دون أن يقال: ومن لم يشربه؟","answer":"الطعم أعم من الشرب ويشعر بأدنى ذوق، فشدد في الاختبار: من لم يذقه إلا الغرفة المأذونة فهو من صفوة الجيش.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص30، تحت «فائدة استعمال لفظ «يطعمه» دون غيره من الألفاظ»","url":""}]},{"id":"s2-1268","number":1268,"surah":2,"verses":[249],"references":[{"surah":2,"verses":[249]}],"verseLabel":"البقرة: 249","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما جاوزه هو والذين آمنوا معه﴾ بصيغة جاوز لا جاز؟","answer":"اختيرت صيغة ﴿جاوز﴾ لما فيها من مبالغة في تحمل مشقة العبور والوصول إلى موضع المواجهة، بخلاف ﴿جاز﴾ التي تدل على مجرد الانتقال دون دلالة المشقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص33، تحت «سر التعبير بصيغة (جاوز) دون (جاز)»","url":""}]},{"id":"s2-1269","number":1269,"surah":2,"verses":[249],"references":[{"surah":2,"verses":[249]}],"verseLabel":"البقرة: 249","question":"لماذا عبّر عن يقينهم بالنصر بقوله ﴿الذين يظنون أنهم ملاقو الله﴾؟","answer":"الظن هنا يقين راجح يحكم السلوك، واستحضار لقاء الله هو الذي صغر في أعينهم فرق العدد وأطلق رجاء النصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص35، تحت «سر التعبير بالظن على معنى العلم واليقين»","url":""}]},{"id":"s2-1270","number":1270,"surah":2,"verses":[249],"references":[{"surah":2,"verses":[249]}],"verseLabel":"البقرة: 249","question":"ما دلالة قول المؤمنين: ﴿كَمْ مِنْ فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً﴾، ولم يقولوا: «انتصرت على فئة كثيرة»؟","answer":"﴿غلبت﴾ تكسر التوقع مباشرة؛ لأن المألوف أن تغلب الكثرةُ القلةَ، فتقرر أن الغلبة لا تتبع العدد بذاته بل أسبابًا مادية ومعنوية يتصدرها الإيمان والتأييد الإلهي. أما «انتصرت» فقد توهم أن النصر جاءهم من غير مباشرة أسباب المقاومة؛ فلفظ الغلبة يجمع العمل والمواجهة والنتيجة غير المتوقعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص36، تحت «الجناس والمقابلة، ودورهما في أداء المعنى الدقيق»","url":""}]},{"id":"s2-1271","number":1271,"surah":2,"verses":[249],"references":[{"surah":2,"verses":[249]}],"verseLabel":"البقرة: 249","question":"لماذا استثنى ﴿مَنِ اغْتَرَفَ غُرْفَةً بِيَدِهِ﴾؟","answer":"أباح قدر الضرورة الذي يعين على المسير ومنع الاسترسال في الشهوة؛ وتصغير الفعل إلى غرفة باليد يرسم حدًا محسوسًا بين الانضباط والانقياد للعطش.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص32، تحت «أثر معنى الشرب في تحديد نوع الاستثناء»","url":""}]},{"id":"s2-1272","number":1272,"surah":2,"verses":[249],"references":[{"surah":2,"verses":[249]}],"verseLabel":"البقرة: 249","question":"ما دلالة قول القلة: ﴿كَمْ مِنْ فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً بِإِذْنِ اللَّهِ﴾؟","answer":"قابلوا حساب العدد بسنّة تتكرر: النصر ليس نتاج الكثرة وحدها. و﴿كم﴾ الخبرية تستحضر شواهد كثيرة، بينما ﴿بإذن الله﴾ تمنع الثقة بالنفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص38، تحت «فائدة القيد «بإذن الله»»","url":""}]},{"id":"s2-1273","number":1273,"surah":2,"verses":[250],"references":[{"surah":2,"verses":[250]}],"verseLabel":"البقرة: 250","question":"ما دلالة قول المؤمنين ﴿أفرغ علينا صبرًا﴾ فصوّر الصبر ماءً يُفرغ؟","answer":"طلبوا صبرًا غامرًا ينصب عليهم حتى يملأ القلب والجوارح، لا جرعة محدودة من الشجاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص43، تحت «بلاغة الاستعارة في الآية»","url":""}]},{"id":"s2-1274","number":1274,"surah":2,"verses":[250],"references":[{"surah":2,"verses":[250]}],"verseLabel":"البقرة: 250","question":"لماذا عبّر عن دعائهم بـ﴿قالوا﴾ لا: دعوا؟","answer":"عبّر بـ﴿قالوا﴾ لأنها تدل على رفع الصوت بالدعاء وصدوره من الجميع مرة واحدة مجتمعين، بخلاف ﴿دعوا﴾ التي قد تكون سرًا أو علانية ومن فرد أو جماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص42، تحت «نكتة التعبير بلفظ «قالوا» دون دعوا»","url":""}]},{"id":"s2-1275","number":1275,"surah":2,"verses":[250],"references":[{"surah":2,"verses":[250]}],"verseLabel":"البقرة: 250","question":"لماذا رتبوا الدعاء: الصبر، ثم ثبات الأقدام، ثم النصر؟","answer":"بدأوا بالقوة الباطنة، ثم أثرها الجسدي في الميدان، ثم الثمرة الخارجية؛ فالنصر في تصورهم نتيجة إعداد القلب والعمل، لا أمنية منفصلة عن الأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص43، تحت «سر الترتيب البليغ في دعاء المؤمنين»","url":""}]},{"id":"s2-1276","number":1276,"surah":2,"verses":[251],"references":[{"surah":2,"verses":[251]}],"verseLabel":"البقرة: 251","question":"ما سرّ التعبير في قوله تعالى: ﴿ولولا دفع الله الناس بعضهم ببعض لفسدت الأرض﴾ لا: لفسد الكافرون؟","answer":"استبداد المعتدي يفسد نظام الأرض ودينها وعمرانها، والدفع يحمي الناس جميعًا لا طائفة واحدة؛ لذلك اتسعت النتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص51، تحت «دلالة التعبير بلفظ الناس في قوله تعالى: «ولولا دفع الله الناس»»","url":""}]},{"id":"s2-1277","number":1277,"surah":2,"verses":[251],"references":[{"surah":2,"verses":[251]}],"verseLabel":"البقرة: 251","question":"لماذا ختم بقوله ﴿ولكن الله ذو فضل على العالمين﴾ لا المؤمنين؟","answer":"سنة الدفع تحفظ العالم من استيلاء الفساد، فينتفع بها مؤمن وكافر، وإن قام المؤمنون بوظيفة المقاومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص51، تحت «بلاغة عطف جملة الفاصلة القرآنية»","url":""}]},{"id":"s2-1278","number":1278,"surah":2,"verses":[251],"references":[{"surah":2,"verses":[251]}],"verseLabel":"البقرة: 251","question":"ما سرّ التعبير في قوله تعالى عن داود: ﴿وَآتَاهُ اللَّهُ الْمُلْكَ وَالْحِكْمَةَ﴾ فقدم الملك على الحكمة؟","answer":"رتب السياق النعمتين بحسب انتقال داود في مراتب الفضل: من الملك، وهو شريف، إلى الحكمة والنبوة، وهي أشرف. كما أن الملك كان محور القصة منذ طلب بني إسرائيل ملكًا واعتراضهم على طالوت، فناسب تقديم ما تعلقت به عنايتهم، ثم الارتقاء إلى النعمة الأعلى التي تضبط الملك وتمنعه من الطغيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص49، تحت «سر تقديم الملك على الحكمة»","url":""}]},{"id":"s2-1279","number":1279,"surah":2,"verses":[251],"references":[{"surah":2,"verses":[251]}],"verseLabel":"البقرة: 251","question":"ما سرّ التعبير في قوله تعالى: ﴿فَهَزَمُوهُمْ بِإِذْنِ اللَّهِ﴾ قبل ذكر قتل داود جالوت؟","answer":"قُدِّم خبر هزيمة الجيش بإذن الله لبيان أن النصر تحقق للجماعة بتأييده، ثم ذُكر قتل داود جالوت لإبراز دوره الفردي وما أعد له من ملك ونبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص47، تحت «معنى الفاء في قوله تعالى «فهزموهم»»","url":""}]},{"id":"s2-1280","number":1280,"surah":2,"verses":[251],"references":[{"surah":2,"verses":[251]}],"verseLabel":"البقرة: 251","question":"لماذا جمع لداود بين ﴿الْمُلْكَ وَالْحِكْمَةَ﴾؟","answer":"الملك يمنحه سلطة التنفيذ والحكمة تمنحه العلم الذي يهدي القوة؛ فاجتماعهما صورة القيادة الكاملة، بعد أن أثبتت المعركة شجاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص49، تحت «نكتة قرن الملك بالحكمة»","url":""}]},{"id":"s2-1281","number":1281,"surah":2,"verses":[252],"references":[{"surah":2,"verses":[252]}],"verseLabel":"البقرة: 252","question":"ما سرّ التعبير في قوله تعالى: ﴿تلك آيات الله﴾ باسم الإشارة للبعيد لا ﴿هذه﴾؟","answer":"استعمل ﴿تلك﴾ لأن الإشارة إلى القصص الماضية المذكورة، وقد انقضت وصارت في حكم الغائب، فناسبها اسم الإشارة للبعيد لا ﴿هذه﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص54، تحت «إيثار التعبير باسم الإشارة «تلك» دون (هذه)»","url":""}]},{"id":"s2-1282","number":1282,"surah":2,"verses":[252],"references":[{"surah":2,"verses":[252]}],"verseLabel":"البقرة: 252","question":"ما سرّ التعبير في قوله تعالى: ﴿تِلْكَ آيَاتُ اللَّهِ نَتْلُوهَا عَلَيْكَ بِالْحَقِّ﴾ بعد القصة؟","answer":"أشير إلى القصص الماضية بـ﴿تلك﴾ لأنها صارت في حكم الغائب، وأسندت التلاوة إلى الله وقيدت بالحق لتقرير صدقها ودلالتها على نبوة محمد ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص56، تحت «فائدة تقييد التلاوة بقيد «بالحق»»","url":""}]},{"id":"s2-1283","number":1283,"surah":2,"verses":[252],"references":[{"surah":2,"verses":[252]}],"verseLabel":"البقرة: 252","question":"لماذا ختم بـ﴿وَإِنَّكَ لَمِنَ الْمُرْسَلِينَ﴾؟","answer":"خُتمت الجملة بتوكيدات ﴿إن﴾ واللام و﴿من﴾ لتثبيت رسالة النبي ﷺ؛ إذ لا يعلم هذه الأخبار الغيبية من غير وحي، وللتنويه بأنه من جماعة المرسلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص56، تحت «بلاغة التأكيد في قوله: «وإنك لمن المرسلين» بأكثر من مؤكد»","url":""}]},{"id":"s2-1284","number":1284,"surah":2,"verses":[253],"references":[{"surah":2,"verses":[253]}],"verseLabel":"البقرة: 253","question":"ما سر التعبير بـ﴿فَضَّلْنَا بَعْضَهُمْ عَلَى بَعْضٍ﴾ بدل «اصطفينا بعضهم»؟","answer":"لأن الرسل مشتركون في اصطفائهم للرسالة، والتفضيل يبين مزية نسبية لبعضهم على بعض في خصائص زائدة، لا اختصاص بعضهم وحده بأصل الاصطفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص65، تحت «دقة اختيار لفظي (فضلنا) و(بعض)»","url":""}]},{"id":"s2-1285","number":1285,"surah":2,"verses":[253],"references":[{"surah":2,"verses":[253]}],"verseLabel":"البقرة: 253","question":"ما سرّ التعبير في قوله تعالى: ﴿ورفع بعضهم درجات﴾ لا منازل؟","answer":"الدرجات توحي بمراتب متصاعدة متعددة بعضها فوق بعض، فناسبت تفاوت الفضائل الإلهية أكثر من مكان إقامة ثابت.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص68، تحت «اتساق اختيار لفظ «ورفع» مع لفظ «درجات»»","url":""}]},{"id":"s2-1286","number":1286,"surah":2,"verses":[253],"references":[{"surah":2,"verses":[253]}],"verseLabel":"البقرة: 253","question":"ما سرّ التعبير بقوله تعالى: ﴿مِنْهُمْ مَنْ كَلَّمَ اللَّهُ﴾ دون التصريح باسم موسى؟","answer":"أبرز المنقبة نفسها وجعلها قسمًا مميزًا من أقسام التفضيل، مع شهرة صاحبها؛ فالحذف يوجه النظر إلى عطاء الله لا إلى مجرد الاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص69، تحت «بلاغة إبهام المكلم والمرفوع درجات»","url":""}]},{"id":"s2-1287","number":1287,"surah":2,"verses":[253],"references":[{"surah":2,"verses":[253]}],"verseLabel":"البقرة: 253","question":"لماذا خص عيسى بالبينات والتأييد بروح القدس؟","answer":"ذُكر عيسى باسمه وخُص بالبينات وروح القدس ردًا على إفراط أهل الكتاب وتفريطهم؛ فقرر القرآن فضله وآياته من غير غلو، مع أن غيره من الرسل أوتي البينات والتأييد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص70، تحت «بلاغة الالتفات والانتقال من الإبهام إلى التعيين»","url":""}]},{"id":"s2-1288","number":1288,"surah":2,"verses":[253],"references":[{"surah":2,"verses":[253]}],"verseLabel":"البقرة: 253","question":"لماذا تكرر: ﴿وَلَوْ شَاءَ اللَّهُ مَا اقْتَتَلُوا﴾؟","answer":"الأول يقرر إمكان منع الاقتتال بعد مجيء البينات، والثاني يعيد الحقيقة بعد بيان اختلافهم ليقطع توهم أن اختلافهم أفلت من المشيئة؛ والتكرار يحيط السبب والنتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص74، تحت «بلاغة تكرار جملة المشيئة»","url":""}]},{"id":"s2-1289","number":1289,"surah":2,"verses":[254],"references":[{"surah":2,"verses":[254]}],"verseLabel":"البقرة: 254","question":"لماذا ذُكر الإنفاق قبل يوم ﴿لا بيع فيه ولا خلة ولا شفاعة﴾؟","answer":"للحث على المسارعة إلى الإنفاق والتحذير من التسويف؛ فيوم القيامة وقت تنتهي إليه الأعمال ويتعذر فيه الاستدراك، فينبغي البذل قبل مجيئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص80، تحت عنوان «علة تعلق الجار الثاني بالأمر»","url":""}]},{"id":"s2-1290","number":1290,"surah":2,"verses":[254],"references":[{"surah":2,"verses":[254]}],"verseLabel":"البقرة: 254","question":"لماذا ناداهم بوصف الإيمان قبل الأمر بالإنفاق؟","answer":"استدعى ما في الإيمان من تصديق ووعد ليحرك البذل، فالنداء يذكرهم أن الاستجابة ليست ضريبة غريبة بل ثمرة هويتهم التي اختاروها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص79، تحت «بلاغة النداء في مطلع الآية»","url":""}]},{"id":"s2-1291","number":1291,"surah":2,"verses":[254],"references":[{"surah":2,"verses":[254]}],"verseLabel":"البقرة: 254","question":"ما سرّ التعبير في قوله تعالى: ﴿مِمَّا رَزَقْنَاكُمْ﴾؟","answer":"لم يطلب كل المال، وذكّر أن المبذول بعض رزق وهبه الله أصلًا؛ فـ﴿من﴾ للتبعيض والإضافة إلى الرزق تعالجان الشح وشعور الملك المطلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص80، تحت «فائدة نون العظمة وكاف الخطاب»","url":""}]},{"id":"s2-1292","number":1292,"surah":2,"verses":[254],"references":[{"surah":2,"verses":[254]}],"verseLabel":"البقرة: 254","question":"لماذا وصف اليوم بأنه لا بيع فيه ولا خلة ولا شفاعة؟","answer":"أغلق أبواب النجاة التي يركن إليها الإنسان في الدنيا: شراء الخلاص، وصداقة تنصر، وواسطة بغير إذن؛ ليجعل زمن العمل الآن قبل يوم الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص82، تحت «بلاغة الكناية في انتفاء البيع والخلة والشفاعة»","url":""}]},{"id":"s2-1293","number":1293,"surah":2,"verses":[255],"references":[{"surah":2,"verses":[255]}],"verseLabel":"البقرة: 255","question":"لماذا افتُتحت آية الكرسي بـ﴿الله لا إله إلا هو﴾؟","answer":"بدأت بالاسم الجامع وقصر العبادة فيه، ثم جاءت صفات الحياة والقيومية والملك والعلم والقدرة براهين على هذا التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص90، تحت «بلاغة الإخبار بجملة: «لا إله إلا هو» في القرآن الكريم»","url":""}]},{"id":"s2-1294","number":1294,"surah":2,"verses":[255],"references":[{"surah":2,"verses":[255]}],"verseLabel":"البقرة: 255","question":"لماذا جمع بين ﴿الحي القيوم﴾ تحديدًا؟","answer":"الحي كامل في ذاته، والقيوم قائم بنفسه مقيم لغيره؛ فاجتمع كمال الوجود وكمال تدبير كل موجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص91، تحت «دلالة اقتران اسم الحي بالقيوم»","url":""}]},{"id":"s2-1295","number":1295,"surah":2,"verses":[255],"references":[{"surah":2,"verses":[255]}],"verseLabel":"البقرة: 255","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تأخذه سنة ولا نوم﴾ فقدم السِّنة على النوم؟","answer":"قدم السِّنة لأنها الحالة الأخف أثرًا في التدبير، ثم النوم الأثقل الذي يعطل القدرة على التدبير؛ فنفى الحالين متدرجًا من الأدنى إلى الأعلى، من غير أن يلزم كون السِّنة مقدمة لكل نوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص93، تحت «نكتة تقديم السنة على النعاس»","url":""}]},{"id":"s2-1296","number":1296,"surah":2,"verses":[255,284],"references":[{"surah":2,"verses":[255,284]},{"surah":10,"verses":[66]}],"verseLabel":"البقرة: 255؛ البقرة: 284؛ يونس: 66","question":"ما دلالة اختيار ﴿ما﴾ دون ﴿من﴾ في قوله تعالى: ﴿له ما في السماوات وما في الأرض﴾؟","answer":"تفيد «ما» عموم الموجودات، واختيرت مع دخول العقلاء لأن غالب المخلوقات غير عاقلة، فأجري الغالب مجرى الكل. كما نُسبت الموجودات إلى الله من حيث كونها مخلوقة مملوكة له.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص96، تحت عنوان «سر تكرار (ما) وإيثارها دون (من)»","url":""}]},{"id":"s2-1524","number":1524,"surah":2,"verses":[255,284],"references":[{"surah":2,"verses":[255,284]},{"surah":10,"verses":[66]}],"verseLabel":"البقرة: 255؛ البقرة: 284؛ يونس: 66","question":"لماذا عُبّر بـ﴿من﴾ في قوله تعالى في يونس: ﴿ألا إن لله من في السماوات ومن في الأرض﴾؟","answer":"خُص العقلاء بالذكر؛ لأنهم أشرف المخلوقات، فإذا كانوا مملوكين لله لا يصلح أحد منهم للربوبية، كان غيرهم أولى بذلك. ففي التعبير تنبيه بالأعلى على الأدنى وإبطال لاتخاذ الشركاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص688–689، تحت عنوان «دلالة التعبير بـ﴿من﴾»","url":""}]},{"id":"s2-1297","number":1297,"surah":2,"verses":[255],"references":[{"surah":2,"verses":[255]}],"verseLabel":"البقرة: 255","question":"ما سرّ التعبير في قوله تعالى: ﴿وسع كرسيه السماوات والأرض﴾، دون أن يقال: ملكه أو علمه؟","answer":"لأن الكرسي مخلوق عظيم وسع السماوات والأرض، وذكره يصور عظمة الله وكبرياءه، كما يشير لفظه إلى التمكن والعظمة والعلم والملك؛ فلا يختزل في واحد منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص102، تحت «بلاغة المجاز في عبارة «وسع كرسيه»»","url":""}]},{"id":"s2-1298","number":1298,"surah":2,"verses":[255],"references":[{"surah":2,"verses":[255]}],"verseLabel":"البقرة: 255","question":"لماذا ثنّى الضمير في ﴿ولا يؤوده حفظهما﴾؟","answer":"يعود إلى السماوات والأرض المذكورتين، فجمع حفظ العالم العلوي والسفلي في ضميرين وأثبت أنه لا يثقله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص103، تحت «علة تثنية الضمير في «حفظهما»»","url":""}]},{"id":"s2-1299","number":1299,"surah":2,"verses":[255],"references":[{"surah":2,"verses":[255]}],"verseLabel":"البقرة: 255","question":"لماذا ختمت آية الكرسي بـ﴿العلي العظيم﴾؟","answer":"بعد شمول الملك والعلم والحفظ ختم بعلوه عن كل نقص وعظمة لا يقاس بها شيء، فتلخصت صفات الآية في الاسمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص104، تحت «بلاغة الفاصلة»","url":""}]},{"id":"s2-1300","number":1300,"surah":2,"verses":[255],"references":[{"surah":2,"verses":[255]}],"verseLabel":"البقرة: 255","question":"ما سرّ التعبير في قوله تعالى في آية الكرسي: ﴿مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ﴾ بصيغة السؤال، دون أن يقال مباشرة: «لا يشفع عنده أحد إلا بإذنه»؟","answer":"الاستفهام هنا يتضمن النفي والإنكار، لكنه أبلغ من النفي المباشر؛ لأنه يستدعي من السامع أن يبحث عن الجواب ثم يقر بنفسه أنه لا أحد يملك الشفاعة استقلالًا. وبعد تقرير ملك الله للسماوات والأرض جاءت الصيغة لتبطل اعتقاد من يتوهم شفيعًا يفرض إرادته على الله؛ فلا تقع شفاعة إلا بعد إذنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص97، تحت «بديع الابتداء بالنفي على صيغة الاستفهام»","url":""}]},{"id":"s2-1301","number":1301,"surah":2,"verses":[255],"references":[{"surah":2,"verses":[255]},{"surah":20,"verses":[110]}],"verseLabel":"البقرة: 255؛ طه: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ﴾؟","answer":"التعبير بما بين الأيدي وما خلفها كناية عن إحاطة علم الله بسائر أحوال المخلوقات من جميع الجهات؛ فلا يغيب عنه شيء. وذِكر الجهتين يصور شمول هذا العلم وعمومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص99، تحت عنوان «بلاغة الكناية في الجملة»","url":""}]},{"id":"s2-1302","number":1302,"surah":2,"verses":[256],"references":[{"surah":2,"verses":[256]}],"verseLabel":"البقرة: 256","question":"ما سرّ التعبير في قوله تعالى: ﴿لا إكراه في الدين﴾، دون أن يقال: في الإسلام؟","answer":"الدين أعم فيشمل أصل الاعتقاد الذي لا يصنعه الإكراه، ويقرر قاعدة العلاقة بين الإيمان القلبي والاختيار بعد وضوح الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص110، تحت «سر إيثار لفظ «الدين» على لفظ (الإسلام)»","url":""}]},{"id":"s2-1303","number":1303,"surah":2,"verses":[256],"references":[{"surah":2,"verses":[256]}],"verseLabel":"البقرة: 256","question":"ما سرّ التعبير في قوله تعالى: ﴿قد تبين الرشد من الغي﴾ قبل ذكر الكفر بالطاغوت والإيمان بالله؟","answer":"قرر وضوح الطريقين أولًا ثم بنى عليه الاختيار العملي: رفض الطاغوت والإيمان بالله؛ فالموقف ثمرة البيان لا قسر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص110، تحت «بلاغة التوكيد والتعليل في جملة تبين الرشد»","url":""}]},{"id":"s2-1304","number":1304,"surah":2,"verses":[256],"references":[{"surah":2,"verses":[256]}],"verseLabel":"البقرة: 256","question":"ما سرّ التعبير في قوله تعالى: ﴿فقد استمسك بالعروة الوثقى﴾ فصوّر الإيمان بعروة؟","answer":"شبه المؤمن بمن قبض على أقوى مقبض ينقذه من السقوط، فجمع فعل الاستمساك وأمان الوسيلة التي لا تنفصم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص113، تحت «بلاغة الاستعارة التمثيلية»","url":""}]},{"id":"s2-1305","number":1305,"surah":2,"verses":[256],"references":[{"surah":2,"verses":[256]}],"verseLabel":"البقرة: 256","question":"ما دلالة النفي بـ«لا» النافية للجنس في قوله تعالى: ﴿لا إكراه في الدين﴾؟","answer":"يفيد شمول النهي جميع أنواع الإكراه وأشكاله، مادية ومعنوية ونفسية وأسرية واجتماعية؛ فجيء بنفي الجنس لقصد العموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص109، تحت عنوان «براعة الاستهلال بالنفي»","url":""}]},{"id":"s2-1525","number":1525,"surah":2,"verses":[256],"references":[{"surah":2,"verses":[256]}],"verseLabel":"البقرة: 256","question":"ما سر اختيار لفظ ﴿الإكراه﴾ في قوله تعالى: ﴿لا إكراه في الدين﴾؟","answer":"الإكراه حمل الإنسان قسرًا على ما يكرهه، فقد يفعل ما أُكره عليه ظاهرًا وهو غير راض به في باطنه، والدين المطلوب دين خالص. وجاء اللفظ مصدرًا مجردًا من الزمن لاستغراق وجوه الإكراه واحتمالاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص109، تحت عنوان «قصدية اختيار كلمة الإكراه لفظًا، وصيغة»","url":""}]},{"id":"s2-1306","number":1306,"surah":2,"verses":[256],"references":[{"surah":2,"verses":[256]}],"verseLabel":"البقرة: 256","question":"ما سرّ التعبير في قوله تعالى: ﴿قَدْ تَبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ﴾؟","answer":"علل نفي الإكراه بوضوح الطريقين، واختار ﴿تبين﴾ لتصوير انفصالهما بعد قيام الدليل؛ فالمطلوب اختيار واع لا استجابة قسرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص110، تحت «بلاغة التوكيد والتعليل في جملة تبين الرشد»","url":""}]},{"id":"s2-1307","number":1307,"surah":2,"verses":[256],"references":[{"surah":2,"verses":[256]}],"verseLabel":"البقرة: 256","question":"ما سرّ تقديم الكفر بالطاغوت على الإيمان بالله؟","answer":"لأن التوحيد يتضمن تخليًا عن كل معبود وسلطان باطل قبل التحلي بالإيمان؛ فنفى الزيف ثم أثبت الحق، كما في كلمة التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص112، تحت «بلاغة تقديم لفظ الكفر على الإيمان»","url":""}]},{"id":"s2-1308","number":1308,"surah":2,"verses":[257],"references":[{"surah":2,"verses":[257]}],"verseLabel":"البقرة: 257","question":"لماذا أفرد النور وجمع الظلمات في ﴿يخرجهم من الظلمات إلى النور﴾؟","answer":"الحق واحد متسق، أما الباطل فطرق متشعبة من جهل وشهوة وشبهة؛ فالإفراد والجمع يصوران وحدة الهدى وتفرق الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص125، تحت «سر جمع الظلمات وإفراد النور»","url":""}]},{"id":"s2-1309","number":1309,"surah":2,"verses":[257],"references":[{"surah":2,"verses":[257]}],"verseLabel":"البقرة: 257","question":"ما سرّ التعبير في قوله تعالى: ﴿النور﴾ لا الضياء؟","answer":"لأن النور يستعمل في المعنويات والمحسوسات، فناسب الهداية التي تكشف الحق للقلب، بخلاف الضياء الذي يستعمل في المحسوسات؛ وبذلك يمنع حمل التعبير على الإشراق المادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص123، تحت «نكتة التعبير بالنور دون الضياء»","url":""}]},{"id":"s2-1310","number":1310,"surah":2,"verses":[257],"references":[{"surah":2,"verses":[257]}],"verseLabel":"البقرة: 257","question":"ما سرّ التعبير للمؤمنين بقوله تعالى: ﴿يُخْرِجُهُمْ مِنَ الظُّلُمَاتِ إِلَى النُّورِ﴾ مع أنهم مؤمنون؟","answer":"لأن المضارع يدل على تجدد ولاية الله ورعايته للمؤمنين؛ فيزيدهم كشفًا للشبهة ومضاعفةً للهداية، ويستمر إخراجهم إلى نور الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص128، تحت «لفظ (النور) بين الاستعارة التصريحية، ووجوه أساليب بلاغية»","url":""}]},{"id":"s2-1311","number":1311,"surah":2,"verses":[257],"references":[{"surah":2,"verses":[257]}],"verseLabel":"البقرة: 257","question":"ما سرّ التعبير في قوله تعالى في الكافرين: ﴿أَوْلِيَاؤُهُمُ الطَّاغُوتُ﴾ مع إفراد لفظ الطاغوت؟","answer":"الطاغوت اسم جنس يجمع رؤوس الباطل، فصح الإخبار به عن أولياء متعددين؛ ووحدة الاسم تكشف أن تنوعهم يرجع إلى أصل واحد هو تجاوز حد العبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص127، تحت «علة إفراد الطاغوت وجمع الأولياء»","url":""}]},{"id":"s2-1312","number":1312,"surah":2,"verses":[257],"references":[{"surah":2,"verses":[257]}],"verseLabel":"البقرة: 257","question":"لماذا ختم الكافرين بـ﴿هُمْ فِيهَا خَالِدُونَ﴾؟","answer":"خُتم وصفهم بإثبات ملازمتهم النار واختصاصهم بها ودوامهم فيها، في مقابل استمرار ولاية الله للمؤمنين وإخراجهم إلى النور.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص132، تحت «بلاغة التوكيد في الفاصلة»","url":""}]},{"id":"s2-1313","number":1313,"surah":2,"verses":[258],"references":[{"surah":2,"verses":[258]}],"verseLabel":"البقرة: 258","question":"ما سرّ التعبير في قوله تعالى: ﴿ألم تر إلى الذي حاج إبراهيم﴾ لا: جادل إبراهيم؟","answer":"المحاجة مفاعلة بالحجة والبرهان، فتصف مقامًا ادعى فيه الخصم الدليل ورد عليه إبراهيم بدليل قاطع، لا جدلًا لفظيًا فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص139، تحت «براعة التعبير بالمحاجة دون المجادلة»","url":""}]},{"id":"s2-1314","number":1314,"surah":2,"verses":[258],"references":[{"surah":2,"verses":[258]}],"verseLabel":"البقرة: 258","question":"ما سرّ التعبير في قوله تعالى: ﴿أن آتاه الله الملك﴾ فجعل النعمة سببًا لطغيانه؟","answer":"حمله الملك على الغرور بدل الشكر، فصارت النعمة في اختياره سبب المحاجة؛ والتعبير يفضح انقلاب العطاء إلى حجة على المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص141، تحت «بلاغة التهكم»","url":""}]},{"id":"s2-1315","number":1315,"surah":2,"verses":[258],"references":[{"surah":2,"verses":[258]}],"verseLabel":"البقرة: 258","question":"لماذا انتقل إبراهيم من حجة الإحياء والإماتة إلى حجة الشمس؟","answer":"لما لبّس الملك بادعاء معنى شكلي للإحياء والإماتة نقله إبراهيم إلى آية كونية لا يستطيع تقليدها أو تحريف معناها، فبهت.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص144، تحت «بلاغة الفاء الفصيحة في الحجاج القرآني»","url":""}]},{"id":"s2-1316","number":1316,"surah":2,"verses":[258],"references":[{"surah":2,"verses":[258]}],"verseLabel":"البقرة: 258","question":"ما سرّ التعبير في قوله تعالى: ﴿فَبُهِتَ الَّذِي كَفَرَ﴾ ولم يذكر جوابًا له؟","answer":"لأن الحجة أسقطت قدرته على الكلام، فكان صمته هو الجواب. ووصفه بالذي كفر يربط البهت بموقفه من الحق لا باسمه أو ملكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص142، تحت «فائدة الإخبار بالاسم الموصول»","url":""}]},{"id":"s2-1317","number":1317,"surah":2,"verses":[259],"references":[{"surah":2,"verses":[259]}],"verseLabel":"البقرة: 259","question":"ما أثر تنكير القرية في قوله: ﴿أَوْ كَالَّذِي مَرَّ عَلَى قَرْيَةٍ﴾؟","answer":"يوسع مجال الاعتبار ولا يحصر دلالة القصة في بلدة بعينها؛ فالمقصود مشهد القرية الخاوية وإظهار قدرة الله على الإحياء، لا تحقيق اسم الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص154، تحت «دلالة الإبهام في تنكير لفظ القرية»","url":""}]},{"id":"s2-1318","number":1318,"surah":2,"verses":[259],"references":[{"surah":2,"verses":[259]}],"verseLabel":"البقرة: 259","question":"لماذا سأل ﴿أنى يحيي هذه الله بعد موتها﴾ بـ﴿أنى﴾ لا كيف أو متى؟","answer":"اختيرت ﴿أنى﴾ لأنها تستوعب معاني: كيف، ومتى، وحيث؛ فتجمع السؤال عن كيفية الإحياء وزمانه ومكانه في لفظ واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص157، تحت «معنى الاستفهام في «أنى»»","url":""}]},{"id":"s2-1319","number":1319,"surah":2,"verses":[259],"references":[{"surah":2,"verses":[259]}],"verseLabel":"البقرة: 259","question":"ما سرّ التعبير في قوله تعالى: ﴿مائة عام﴾ لا مائة سنة؟","answer":"اختير ﴿عام﴾ لأنه يلائم الزمن الطيب القابل للإحياء والنماء بعد الموت، بخلاف ﴿سنة﴾ التي يكثر استعمالها في الشدة والحرمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص159، تحت «نكتة التعبير بالعام دون السنة»","url":""}]},{"id":"s2-1320","number":1320,"surah":2,"verses":[259],"references":[{"surah":2,"verses":[259]}],"verseLabel":"البقرة: 259","question":"لماذا حفظ الله طعامه وشرابه وأراه بِلَى حماره؟","answer":"جمع بجوار بعض قدرة الحفظ من التغير وقدرة الإماتة ثم التركيب والإحياء، ليعلم أن الله لا تحكمه سنة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص159، تحت «نكتة التعبير بالعام دون السنة»","url":""}]},{"id":"s2-1321","number":1321,"surah":2,"verses":[259],"references":[{"surah":2,"verses":[259]}],"verseLabel":"البقرة: 259","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْ كَالَّذِي مَرَّ عَلَى قَرْيَةٍ﴾، دون أن يقال: «دخل قرية» أو «جاء إلى قرية»؟","answer":"﴿مرّ﴾ يدل على اجتياز سريع من غير قصد الإقامة؛ فالرجل اتخذ القرية طريقًا، ثم فاجأه الموت حيث لم يحتسب وبقي مائة عام. وفي اللفظ لمحة وعظية توافق القصة: الإنسان نفسه مارّ في الدنيا لا مقيم فيها، وقد يأتيه الموت في أثناء مروره؛ فجمعت الكلمة حركة الحدث وعبرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص154، تحت «سر إيثار الفعل «مر» في قوله تعالى: «أو كالذي مر على قرية»»","url":""}]},{"id":"s2-1322","number":1322,"surah":2,"verses":[259],"references":[{"surah":2,"verses":[259]}],"verseLabel":"البقرة: 259","question":"لماذا وصف القرية بأنها ﴿خَاوِيَةٌ عَلَى عُرُوشِهَا﴾؟","answer":"صورة تجعل السقوف ساقطة ثم الجدران خاوية فوقها، فتبلغ بالخراب منتهاه؛ ولهذا يشتد سؤال: كيف يحيي هذه الله بعد موتها؟","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص155، تحت «دقة تصوير تراتبية مشهد الخراب»","url":""}]},{"id":"s2-1323","number":1323,"surah":2,"verses":[259],"references":[{"surah":2,"verses":[259]}],"verseLabel":"البقرة: 259","question":"لماذا سأله الله: ﴿كَمْ لَبِثْتَ﴾ بعد أن أماته مئة عام؟","answer":"السؤال توطئة لتعريفه بحقيقة المدة وإظهار قصور علمه؛ إذ ظن أنه لبث يومًا أو بعض يوم، ثم تبين له طول المدة، فازداد معرفة بقدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص160، تحت «الاستئناف البياني في المحاورات القرآنية»","url":""}]},{"id":"s2-1324","number":1324,"surah":2,"verses":[259],"references":[{"surah":2,"verses":[259]}],"verseLabel":"البقرة: 259","question":"لماذا جمع له بين طعام لم يتغير وحمار صار عظامًا ثم أحياه؟","answer":"وضع بجوار بعض صورتين متعاكستين تحت القدرة نفسها: حفظ بلا تغير، وإماتة ثم تركيب وإحياء؛ ليرى أن الله لا تحكمه سنة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص167، تحت «سر التعبير بالنظر وتكراره»","url":""}]},{"id":"s2-1325","number":1325,"surah":2,"verses":[260],"references":[{"surah":2,"verses":[260]}],"verseLabel":"البقرة: 260","question":"ما سرّ دعاء إبراهيم باسم الربوبية في قوله: ﴿رَبِّ أَرِنِي كَيْفَ تُحْيِي الْمَوْتَى﴾؟","answer":"طلب تربية قلبه بالانتقال من علم الخبر إلى مشاهدة الكيفية، فناسب اسم الرب الذي يزيد عبده علمًا وطمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص176، تحت «سر اختيار عنوان الربوبية دون الألوهية»","url":""}]},{"id":"s2-1326","number":1326,"surah":2,"verses":[260],"references":[{"surah":2,"verses":[260]}],"verseLabel":"البقرة: 260","question":"ما سرّ التعبير في قوله تعالى له ﴿أولم تؤمن﴾ مع علمه بإيمانه؟","answer":"ليظهر جوابه للأمة ويفصل بين طلب الطمأنينة والشك في القدرة؛ فالسؤال تعليمي تقريري لا استعلام عن مجهول.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص179، تحت «توجيه معنى الاستعجاز في جملة الاستفهام»","url":""}]},{"id":"s2-1327","number":1327,"surah":2,"verses":[260],"references":[{"surah":2,"verses":[260]}],"verseLabel":"البقرة: 260","question":"لماذا أجاب إبراهيم ﴿بلى ولكن ليطمئن قلبي﴾؟ أكان في قلبه شك؟","answer":"أثبت الإيمان أولًا، ثم طلب سكون القلب بمشاهدة ما علمه يقينًا؛ فالمعرفة درجات، والعيان يزيد الطمأنينة دون أن يسبقه كفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص180، تحت «دقة اختيار لفظ الطمأنينة»","url":""}]},{"id":"s2-1328","number":1328,"surah":2,"verses":[260],"references":[{"surah":2,"verses":[260]}],"verseLabel":"البقرة: 260","question":"لماذا اختيرت أربعة من الطير في تجربة الإحياء؟","answer":"اختيرت أربعة لتكون من أنواع مختلفة، وتوزع على الجهات الأربع؛ فيظهر أن الإحياء لا يختص بنوع من الطير ولا بجهة من الجهات.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص182، تحت «دلالة ﴿من﴾ التبعيضية»","url":""}]},{"id":"s2-1329","number":1329,"surah":2,"verses":[260],"references":[{"surah":2,"verses":[260]}],"verseLabel":"البقرة: 260","question":"لماذا سأل إبراهيم: ﴿رَبِّ أَرِنِي كَيْفَ تُحْيِي الْمَوْتَى﴾ مع إيمانه؟","answer":"لم يطلب أصل التصديق بل مشاهدة الكيفية لينتقل من علم الخبر إلى طمأنينة العيان؛ ولذلك أجاب عن سؤال الإيمان بالإثبات ثم علل بطلب طمأنينة القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص178، تحت «أثر البلاغة القرآنية في السنة النبوية»","url":""}]},{"id":"s2-1330","number":1330,"surah":2,"verses":[260],"references":[{"surah":2,"verses":[260]}],"verseLabel":"البقرة: 260","question":"ما سرّ توجيهه بقوله تعالى: ﴿فَخُذْ أَرْبَعَةً مِنَ الطَّيْرِ فَصُرْهُنَّ إِلَيْكَ﴾؟","answer":"جعله يباشر التجربة بيده ويرتبط بالطيور قبل تفريقها، ليكون اجتماع أجزائها وعودتها إليه أبلغ في المشاهدة وأبعد عن الاشتباه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص185، تحت «فائدة ضم الطير إلى نفسه»","url":""}]},{"id":"s2-1331","number":1331,"surah":2,"verses":[260],"references":[{"surah":2,"verses":[260]}],"verseLabel":"البقرة: 260","question":"لماذا جعل على كل جبل جزءًا ثم أمره أن يدعوها؟","answer":"بالغ في تفريق الأجزاء ثم جمعها بمجرد النداء، ليظهر أن تباعد المادة لا يعجز القدرة وأن الإحياء استجابة سريعة لأمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص186، تحت «وجه تعدد الجبال»","url":""}]},{"id":"s2-1332","number":1332,"surah":2,"verses":[260],"references":[{"surah":2,"verses":[260]}],"verseLabel":"البقرة: 260","question":"لماذا ختم بـ﴿وَاعْلَمْ أَنَّ اللَّهَ عَزِيزٌ حَكِيمٌ﴾؟","answer":"العزيز لا يعجزه جمع المتفرق ولا يمانع، والحكيم المتقن للإحياء والتعليم؛ فالفاصلة تناسب القدرة وكيفية الإتقان.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص187، تحت «مناسبة الفاصلة لسياق الآية»","url":""}]},{"id":"s2-1333","number":1333,"surah":2,"verses":[261],"references":[{"surah":2,"verses":[261]}],"verseLabel":"البقرة: 261","question":"لماذا شبّه النفقة بحبة أنبتت سبع سنابل في كل سنبلة مائة حبة؟","answer":"حول المضاعفة إلى مشهد زرع حي: حبة واحدة تصير سبعمئة، ليشعر المنفق أن ما يخرج من يده لا يفنى بل ينمو.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص199، تحت «سر تحديد عدد السنابل بسبع»","url":""}]},{"id":"s2-1334","number":1334,"surah":2,"verses":[261],"references":[{"surah":2,"verses":[261]}],"verseLabel":"البقرة: 261","question":"لماذا جمع ﴿أموالهم﴾ ولم يقل: مالهم؟","answer":"جمع ﴿أموالهم﴾ ليدل على أنهم ينفقون من أنواع أموالهم جميعًا، ولا يختارون نوعًا دون نوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص196، تحت «علة جمع المال دون إفراده»","url":""}]},{"id":"s2-1335","number":1335,"surah":2,"verses":[261],"references":[{"surah":2,"verses":[261]}],"verseLabel":"البقرة: 261","question":"ما سرّ التعبير في قوله تعالى: ﴿والله يضاعف لمن يشاء﴾ ولم يقيد المضاعفة بعشرة أمثال؟","answer":"المثل يذكر سبعمئة ثم يفتح الفضل لما وراءها بحسب الإخلاص والحاجة؛ فسعة الله لا يحصرها حد أدنى للجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص202، تحت «سر إطلاق المضاعفة دون تقييدها بعشر أمثالها»","url":""}]},{"id":"s2-1336","number":1336,"surah":2,"verses":[261],"references":[{"surah":2,"verses":[261]},{"surah":6,"verses":[160]}],"verseLabel":"البقرة: 261، الأنعام: 160","question":"لماذا جعل جزاء الحسنة في الأنعام عشر أمثالها، بينما بلغ جزاء النفقة في البقرة سبعمائة ضعف؟","answer":"آية الأنعام قاعدة عامة في مطلق الحسنات، فذكرت الحد العام المضمون للحسنة وهو عشر أمثالها. أما آية البقرة فخاصة بالإنفاق في سبيل الله، وهو من أعظم القربات وأشدها نفعًا وتضحية، فمثلت مضاعفته الخاصة بسبع سنابل في كل سنبلة مائة حبة، مع بقاء باب الزيادة مفتوحًا بقوله: ﴿والله يضاعف لمن يشاء﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص621، تحت «مضاعفة الحسنات بين العشر والسبعمئة»","url":""}]},{"id":"s2-1337","number":1337,"surah":2,"verses":[261],"references":[{"surah":2,"verses":[261]},{"surah":12,"verses":[43]}],"verseLabel":"البقرة: 261، يوسف: 43","question":"ما سرّ اختلاف التعبير بين قوله تعالى في مثل النفقة: ﴿أَنْبَتَتْ سَبْعَ سَنَابِلَ﴾ بجمع الكثرة، وقوله تعالى في رؤيا ملك مصر: ﴿وَسَبْعَ سُنْبُلَاتٍ خُضْرٍ﴾ بجمع القلة؟","answer":"مقام البقرة مبني على التكثير والمضاعفة؛ فالحبة تنتهي إلى سبعمائة ضعف، ثم يفتح قوله ﴿والله يضاعف لمن يشاء﴾ باب الزيادة، فناسب جمع الكثرة ﴿سنابل﴾. أما يوسف فتحكي رؤيا محددة لسبع سنبلات، وما دون العشرة قليل، فناسب جمع القلة، كما شاكل قوله قبلها ﴿سبع بقرات﴾. فاختلاف الجمع يتبع مقصد التكثير أو نقل العدد المشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص199، تحت «سر التعبير بجمع الكثرة لا القلة»","url":""}]},{"id":"s2-1338","number":1338,"surah":2,"verses":[261],"references":[{"surah":2,"verses":[261]}],"verseLabel":"البقرة: 261","question":"ما سرّ التعبير في قوله تعالى: ﴿مَثَلُ الَّذِينَ يُنْفِقُونَ أَمْوَالَهُمْ﴾ ثم شبّه بالحبة لا بالأشخاص؟","answer":"في التركيب إيجاز؛ فالمشبه هو حال نفقتهم أو ثوابها، وحذف المضاف يجعل المنفق ونفقته داخلين في صورة الزرع المثمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص195، تحت «بلاغة الاحتباك في التشبيه»","url":""}]},{"id":"s2-1339","number":1339,"surah":2,"verses":[261],"references":[{"surah":2,"verses":[261]}],"verseLabel":"البقرة: 261","question":"لماذا ختم بـ﴿وَاللَّهُ وَاسِعٌ عَلِيمٌ﴾؟","answer":"واسع الفضل فلا تقف المضاعفة عند العدد المذكور، وعليم بالنية ومحل النفقة؛ فالكثرة ليست آلية بل فضل موزون بعلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص203، تحت «براعة الفاصلة القرآنية»","url":""}]},{"id":"s2-1340","number":1340,"surah":2,"verses":[262],"references":[{"surah":2,"verses":[262]}],"verseLabel":"البقرة: 262","question":"لماذا جمع بين المنّ والأذى بعد الصدقة؟ وما الفرق بينهما؟","answer":"المن قول صريح يذكّر المعطى بالعطاء، والأذى أعم، فيشمل القول والفعل والإشارة التي تؤذيه؛ فجمع الخاص والعام لاستيعاب صور الأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص214، تحت «نكتة اقتران (المن) بـ(الأذى)»","url":""}]},{"id":"s2-1341","number":1341,"surah":2,"verses":[262,274],"references":[{"surah":2,"verses":[262,274]}],"verseLabel":"البقرة: 262 و274","question":"ما سرّ التعبير في قوله تعالى في الآية 262: ﴿لَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ﴾ بلا فاء، ثم قال في الآية 274: ﴿فَلَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ﴾ بالفاء؟","answer":"آية 262 ليست في صورة شرط وجزاء، بل في بيان من يستحق الأجر: المنفق لله الذي لا يتبع إنفاقه منًّا ولا أذى؛ فكان ترتب الأجر عليه بيّنًا ولم يحتج إلى فاء السببية. أما آية 274 فعممت أوقات الإنفاق وأحواله: ليلًا ونهارًا، سرًّا وعلانية؛ فدخلت الفاء لتقرر أن الإنفاق متى وُجد وعلى أي حال كان فهو سبب للأجر، وتحض المنفق على ألا ينتظر وقتًا أو حالًا أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص217، تحت «بيان المتشابه اللفظي»","url":""}]},{"id":"s2-1342","number":1342,"surah":2,"verses":[262],"references":[{"surah":2,"verses":[262]}],"verseLabel":"البقرة: 262","question":"لماذا اشترط بعد الإنفاق ألا يتبعه ﴿مَنًّا وَلَا أَذًى﴾؟","answer":"اشترط خلو ما بعد الإنفاق من المن والأذى لأن قبول الصدقة مرهون بصيانتها منهما في الحال والاستقبال.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص211، تحت «فائدة أسلوب الشرط بحرف التراخي الرتبي»","url":""}]},{"id":"s2-1343","number":1343,"surah":2,"verses":[262],"references":[{"surah":2,"verses":[262]}],"verseLabel":"البقرة: 262","question":"ما سرّ التعبير في قوله تعالى: ﴿ثُمَّ لَا يُتْبِعُونَ﴾ لا «ولا يتبعون»؟","answer":"﴿ثم﴾ تستوعب الزمن المتراخي؛ فالمطلوب ألا يظهر المن بعد أيام أو سنين، لا أن يخلو مجلس العطاء منه فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص214، تحت «السر في تكرار «لا»»","url":""}]},{"id":"s2-1344","number":1344,"surah":2,"verses":[262],"references":[{"surah":2,"verses":[262]},{"surah":10,"verses":[62]}],"verseLabel":"البقرة: 262؛ يونس: 62","question":"كيف يجمع قوله تعالى: ﴿لا خوف عليهم ولا هم يحزنون﴾ أمن المستقبل والماضي؟","answer":"الخوف متعلق بما يُستقبل، والحزن متعلق بما مضى؛ فجمع نفيهما يحيط بما يكدّر النفس من توقع المكروه ومن تجدد الحزن على الماضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص220، تحت عنوان «سر التعبير بالاسم الظاهر عن الخوف وبالمضارع عن الحزن»","url":""}]},{"id":"s2-1526","number":1526,"surah":2,"verses":[262],"references":[{"surah":2,"verses":[262]},{"surah":10,"verses":[62]}],"verseLabel":"البقرة: 262؛ يونس: 62","question":"ما دلالة تقديم ﴿هم﴾ في قوله تعالى في يونس: ﴿ولا هم يحزنون﴾؟","answer":"قُدّم المسند إليه على الخبر الفعلي لتقوية الحكم، وفي التقديم دلالة على الحصر؛ فالمعنى في سياق الثناء على أولياء الله أنهم سالمون من الحزن المنفي هنا، خلافًا لمن ثبت له ذلك الحزن.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص651–652، تحت عنوان «نكتة تقديم المسند إليه»","url":""}]},{"id":"s2-1345","number":1345,"surah":2,"verses":[263],"references":[{"surah":2,"verses":[263]}],"verseLabel":"البقرة: 263","question":"ما سرّ التعبير في قوله تعالى: ﴿قول معروف ومغفرة خير من صدقة يتبعها أذى﴾؟","answer":"الكلمة الطيبة والعفو يحفظان كرامة المحتاج، أما المال المصحوب بالإهانة فيسد حاجة ويصنع جرحًا؛ فكان الإحسان المعنوي الخالص خيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص222، تحت «أثر المفاضلة في استنباط المعاني»","url":""}]},{"id":"s2-1346","number":1346,"surah":2,"verses":[263],"references":[{"surah":2,"verses":[263]}],"verseLabel":"البقرة: 263","question":"ما سرّ التعبير في قوله تعالى: ﴿لا خوف عليهم﴾، دون أن يقال: لا يخافون؟","answer":"الجملة الاسمية أرسخ، وتنفي جنس الخوف الواقع عليهم لا مجرد فعل يصدر منهم في لحظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص220، تحت «سر التعبير بالاسم الظاهر عن الخوف وبالمضارع عن الحزن»","url":""}]},{"id":"s2-1347","number":1347,"surah":2,"verses":[263],"references":[{"surah":2,"verses":[263]}],"verseLabel":"البقرة: 263","question":"لماذا نكّر ﴿قَوْلٌ﴾ و﴿مَغْفِرَةٌ﴾ و﴿صَدَقَةٌ﴾؟","answer":"ليعم أقل كلمة معروفة وأدنى عفو، ويقرر أنهما مع قلتهما خير من أي صدقة خالطها الأذى؛ فالعبرة بالنوع والصفاء لا بالحجم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص222، تحت «فائدة تنكير القول»","url":""}]},{"id":"s2-1348","number":1348,"surah":2,"verses":[263],"references":[{"surah":2,"verses":[263]}],"verseLabel":"البقرة: 263","question":"لماذا ختم بـ﴿وَاللَّهُ غَنِيٌّ حَلِيمٌ﴾؟","answer":"الله غني عن الصدقات؛ فلا يحتاج الفقراء إلى احتمال المن والأذى، وحليم لا يعاجل أصحاب المن والأذى بالعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص223، تحت «بلاغة الفاصلة»","url":""}]},{"id":"s2-1349","number":1349,"surah":2,"verses":[264],"references":[{"surah":2,"verses":[264]}],"verseLabel":"البقرة: 264","question":"لماذا شبّه المرائي بصفوان عليه تراب فأصابه وابل؟","answer":"يبدو التراب تربة صالحة كما يبدو الرياء عملًا صالحًا، ثم يكشف الوابل صخرة لا تمسك شيئًا؛ فيسقط القناع ويبطل الأجر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص235، تحت «وجه الشبه في المرائي»","url":""}]},{"id":"s2-1350","number":1350,"surah":2,"verses":[264],"references":[{"surah":2,"verses":[264]}],"verseLabel":"البقرة: 264","question":"لماذا اختار ﴿صفوان﴾ لا حجرًا أملس؟","answer":"صفوان لفظ يدل بذاته على الصخرة الملساء الصلبة، فيكثف الصورة ويستحضر سطحًا لا ينبت ولا يحتفظ بالتراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص236، تحت «استحضار الأمل في قوله: «صفوان عليه تراب»»","url":""}]},{"id":"s2-1351","number":1351,"surah":2,"verses":[264],"references":[{"surah":2,"verses":[264]}],"verseLabel":"البقرة: 264","question":"لماذا ذكر طبقة ﴿تراب﴾ فوق الصخرة؟","answer":"لأن الطبقة تخدع الناظر بصورة خصوبة مؤقتة، مثل ظاهر الصدقة الذي يغطي قلبًا قاسيًا حتى يكشفه الابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص236، تحت «استحضار الأصل في قوله: «صفوان عليه تراب»»","url":""}]},{"id":"s2-1352","number":1352,"surah":2,"verses":[264],"references":[{"surah":2,"verses":[264]}],"verseLabel":"البقرة: 264","question":"لماذا اختار الوابل لا المطر أو الغيث؟","answer":"الوابل مطر غزير شديد يزيل التراب بسرعة، فناسب لحظة الاختبار التي تكشف أصل العمل وتستأصله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص237، تحت «إيثار لفظ «وابل» على بقية مرادفاته»","url":""}]},{"id":"s2-1353","number":1353,"surah":2,"verses":[264],"references":[{"surah":2,"verses":[264]}],"verseLabel":"البقرة: 264","question":"ما سرّ التعبير في قوله تعالى: ﴿فَتَرَكَهُ صَلْدًا﴾؟","answer":"الفاء تصور سرعة انكشاف الحقيقة، و﴿صلدًا﴾ يرسم سطحًا أملس لا أثر فيه لما كان عليه؛ فلا يبقى للمرائي من نفقته ما ينتفع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص238، تحت «دقة التعبير في قوله تعالى: «فتركه صلدًا»»","url":""}]},{"id":"s2-1354","number":1354,"surah":2,"verses":[264],"references":[{"surah":2,"verses":[264]}],"verseLabel":"البقرة: 264","question":"لماذا ختم بـ﴿وَاللَّهُ لَا يَهْدِي الْقَوْمَ الْكَافِرِينَ﴾؟","answer":"لأن الرياء والمن يكشفان تعلق القلب بنظر الناس وإنكار ميزان الآخرة؛ والخاتمة تحذر من مسار يشبه الكفر في إبطال الصلة بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص240، تحت «وجه التعريض في الفاصلة»","url":""}]},{"id":"s2-1355","number":1355,"surah":2,"verses":[265],"references":[{"surah":2,"verses":[265]}],"verseLabel":"البقرة: 265","question":"ما سرّ التعبير في قوله تعالى عن الجنة ﴿آتت أكلها ضعفين﴾ لا: ثمارها؟","answer":"الأكل هو الثمر من حيث الانتفاع والتناول، فيبرز وفرة العائد الحقيقي لا مجرد منظر الثمرة على الشجر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص250، تحت «سر التعبير عن الثمر بـ(الأكل)»","url":""}]},{"id":"s2-1356","number":1356,"surah":2,"verses":[265],"references":[{"surah":2,"verses":[265]}],"verseLabel":"البقرة: 265","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن لم يصبها وابل فطل﴾ بـ﴿إن﴾ لا ﴿إذا﴾؟","answer":"عدم الوابل احتمال عارض، ومع ذلك يكفي الطل لخصوبة الجنة؛ فالأداة تخدم معنى أنها تثمر في الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص251، تحت «فائدة مجيء «إن» دون «إذا» في قوله «فإن لم يصبها وابل فطل»»","url":""}]},{"id":"s2-1357","number":1357,"surah":2,"verses":[265],"references":[{"surah":2,"verses":[265]}],"verseLabel":"البقرة: 265","question":"لماذا شبّه المخلصين بجنة بربوة؟","answer":"الجنة أرض خصبة والربوة أبعد عن الركود وأحسن تعرضًا للماء والهواء؛ فصورت نفسًا طيبة وعملًا ثابتًا يثمر في أحسن موضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص249، تحت «توجيه تخصيص الربوة بالذكر»","url":""}]},{"id":"s2-1358","number":1358,"surah":2,"verses":[265],"references":[{"surah":2,"verses":[265]}],"verseLabel":"البقرة: 265","question":"ما دلالة ذكر الوابل والطل في مثل جنة المنفقين ابتغاء مرضاة الله؟","answer":"يفيد المثل أن نفقاتهم زاكية لا تضيع بحال وإن تفاوتت بحسب أحوالها؛ فالجنة تؤتي الخير مع المطر الكثير أو القليل، بخلاف الصفوان الذي يتركه الوابل صلدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص251–252، تحت «فائدة مجيء «إن» دون «إذا» في قوله: ﴿فإن لم يصبها وابل فطل﴾؛ جمال التقابل بين المثلين»","url":""}]},{"id":"s2-1359","number":1359,"surah":2,"verses":[265],"references":[{"surah":2,"verses":[265]}],"verseLabel":"البقرة: 265","question":"لماذا ختم بـ﴿وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ﴾؟","answer":"يرى هيئة العطاء ونيته الخفية كما يرى اختلاف الأرضين تحت المطر؛ فلا يستوي عملان تشابه ظاهرهما واختلف منبتهما الداخلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص252، تحت «أثر الفاصلة في المثل «والله بما تعملون بصير»»","url":""}]},{"id":"s2-1360","number":1360,"surah":2,"verses":[266],"references":[{"surah":2,"verses":[266]}],"verseLabel":"البقرة: 266","question":"لماذا خُص النخيل بالشجر، وذُكرت الأعناب بالثمر؟","answer":"ذُكرت شجرة النخيل لأن شجرتها وثمرتها متساويان في عظم النفع، وذُكرت ثمرة الأعناب لأن تعلق العرب بها كان بثمرها أكلًا وشربًا وقوتًا، فكان ذلك أثبت في الصورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص261، تحت «تخصيص شجرة النخيل بالذكر دون ثمرها، وثمرة الأعناب دون شجرها»","url":""}]},{"id":"s2-1361","number":1361,"surah":2,"verses":[266],"references":[{"surah":2,"verses":[266]}],"verseLabel":"البقرة: 266","question":"لماذا جُمع لفظ ﴿أعناب﴾ في مثل الجنة في البقرة: 266؟","answer":"المراد تعدد أصناف العنب، فيدل الجمع على كثرتها وأن الجنة غنية واسعة، وهو مناسب لمقصود المثل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص262، تحت عنوان «إيثار صيغة الجمع للأعناب»","url":""}]},{"id":"s2-1527","number":1527,"surah":2,"verses":[266],"references":[{"surah":2,"verses":[266]}],"verseLabel":"البقرة: 266","question":"ما دلالة جمع ﴿الأنهار﴾ في مثل الجنة في البقرة: 266؟","answer":"يصور الجمع سعة الجنة وامتدادها وعظم أشجارها وقدمها؛ فجريان الأنهار تحتها يدل على ما بلغته من العناية والعراقة، بخلاف الشجيرات الصغيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص262–263، تحت عنوان «دلالة جمع الأنهار دون إفرادها»","url":""}]},{"id":"s2-1528","number":1528,"surah":2,"verses":[266],"references":[{"surah":2,"verses":[266]}],"verseLabel":"البقرة: 266","question":"لماذا جُمع لفظ ﴿الثمرات﴾ مع وجود ﴿كل﴾ في قوله تعالى: ﴿له فيها من كل الثمرات﴾؟","answer":"لأن المراد لا يقتصر على عموم أنواع الثمر، بل يشمل أصناف كل نوع، كأصناف الرمان وغيره؛ فجمع الثمرات يدل على تنوع الأنواع والأصناف معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص263–264، تحت عنوان «فائدة جمع الثمرات دون إفرادها»","url":""}]},{"id":"s2-1362","number":1362,"surah":2,"verses":[266],"references":[{"surah":2,"verses":[266]}],"verseLabel":"البقرة: 266","question":"لماذا كان صاحب الجنة كبيرًا وله ذرية ضعفاء حين أصابها الإعصار؟","answer":"جمع أشد الحاجة مع انعدام القدرة على التعويض؛ فالكبر والذرية الضعيفة يجعلان ضياع الجنة صورة للعمل المحبط يوم لا يمكن استدراكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص265، تحت «بلاغة الاحتراس في قوله: «وله ذرية ضعفاء»»","url":""}]},{"id":"s2-1363","number":1363,"surah":2,"verses":[266],"references":[{"surah":2,"verses":[266]}],"verseLabel":"البقرة: 266","question":"لماذا ختم المثل بـ﴿لعلكم تتفكرون﴾ لا تذكرون؟","answer":"المطلوب تحليل الصورة وإسقاطها على مصير العمل، لا مجرد استرجاع معلومة؛ فالتفكر يعبر من الجنة المحترقة إلى مراجعة النية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص267، تحت «إيثار التفكر على مرادفاته في الفاصلة»","url":""}]},{"id":"s2-1364","number":1364,"surah":2,"verses":[266],"references":[{"surah":2,"verses":[266]}],"verseLabel":"البقرة: 266","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَهُ ذُرِّيَّةٌ ضُعَفَاءُ﴾، دون أن يقال: «وله أولاد ضعفاء»؟","answer":"لفظ ﴿الذرية﴾ ينظر إلى الأولاد بوصفهم امتدادًا يتكاثر منه النسل، لا مجرد أبناء حاضرين؛ ولذلك يوحي بمستقبل الأسرة كله المعلّق بهذه الجنة. فإذا احترقت وهو كبير وله ذرية عاجزة، لم يفقد قوت يومه وحده، بل ضاع المورد الذي كان يرجو أن يحفظ به بقاء نسله وتكاثره؛ فصار مشهد الخسارة أعمق من لفظ «الأولاد».","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص264، تحت «علة إيثار لفظ الذرية»","url":""}]},{"id":"s2-1365","number":1365,"surah":2,"verses":[266],"references":[{"surah":2,"verses":[266]}],"verseLabel":"البقرة: 266","question":"ما سرّ التعبير في قوله تعالى: ﴿إِعْصَارٌ فِيهِ نَارٌ﴾؟","answer":"جمع قوة الريح وإحراق النار ليصور سرعة الاستئصال وشموله؛ فالعمل الذي ظنه صاحبه جنة قد يزيله الرياء في لحظة الحاجة القصوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص265، تحت «تصوير اجتماع الإعصار بالنار منكرين»","url":""}]},{"id":"s2-1366","number":1366,"surah":2,"verses":[267],"references":[{"surah":2,"verses":[267]}],"verseLabel":"البقرة: 267","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تيمموا الخبيث منه تنفقون﴾، دون أن يقال: لا تنفقوا الخبيث؟","answer":"قدم تعمد القصد إلى الرديء ليذم اختيارَه قبل فعل الإنفاق؛ فالمشكلة أن ينتقي الإنسان لنفسه الحسن ولغيره الخبيث.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص274، تحت «دقة التعبير بالتيمم دون مرادفاته»","url":""}]},{"id":"s2-1367","number":1367,"surah":2,"verses":[267],"references":[{"surah":2,"verses":[267]}],"verseLabel":"البقرة: 267","question":"ما سرّ التعبير في قوله تعالى: ﴿ولستم بآخذيه إلا أن تغمضوا فيه﴾؟","answer":"احتج عليهم بميزان نفوسهم: لا تعطوا ما لا تقبلونه لأنفسكم إلا مع التغاضي عن عيبه؛ وهو اختبار عدل قريب لا يحتاج تنظيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص277، تحت «بلاغة القياس التمثيلي»","url":""}]},{"id":"s2-1368","number":1368,"surah":2,"verses":[267],"references":[{"surah":2,"verses":[267]}],"verseLabel":"البقرة: 267","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْفِقُوا مِنْ طَيِّبَاتِ مَا كَسَبْتُمْ﴾؟","answer":"ربط جودة الصدقة بجودة مصدرها ومحلها؛ فالمال المكتسب حلالًا والجيد المحبوب أليق أن يقدم لله، و﴿من﴾ تبقي للإنسان حاجته ولا تطلب الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص272، تحت «اتساق التعبير بين مفردة الإنفاق والطيب»","url":""}]},{"id":"s2-1369","number":1369,"surah":2,"verses":[268],"references":[{"surah":2,"verses":[268]}],"verseLabel":"البقرة: 268","question":"لماذا قابل وعد الشيطان بالفقر بوعد الله بالمغفرة والفضل؟","answer":"الشيطان يخوفهم بخسارة المال ويقودهم إلى البخل، والله يعد بإزالة الذنب وزيادة الخير؛ فمغفرة الماضي وفضل المستقبل يقابلان خوف النقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص285، تحت «نكتة مقابلة الفقر بالمغفرة والفضل»","url":""}]},{"id":"s2-1370","number":1370,"surah":2,"verses":[268],"references":[{"surah":2,"verses":[268]}],"verseLabel":"البقرة: 268","question":"لماذا قدّم الله المغفرة على الفضل في قوله: ﴿وَاللَّهُ يَعِدُكُمْ مَغْفِرَةً مِنْهُ وَفَضْلًا﴾؟","answer":"لأن تطهير النفس من الذنب مقدم على تحصيل الزيادة؛ فالمؤمن أحوج أولًا إلى المغفرة التي تزيل أثر المعصية، ثم يكون أهلًا لوعد الفضل في الدنيا والآخرة. وجاء الترتيب على قاعدة التخلية قبل التحلية: إزالة المانع قبل تحصيل الكمال، كما أنه يقابل وعد الشيطان بالفقر بوعد أوسع يجمع ستر الذنب وزيادة الرزق والثواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص285، تحت «تقديم المغفرة على الفضل»","url":""}]},{"id":"s2-1371","number":1371,"surah":2,"verses":[268],"references":[{"surah":2,"verses":[268]}],"verseLabel":"البقرة: 268","question":"ما سرّ التعبير في قوله تعالى: ﴿الشَّيْطَانُ يَعِدُكُمُ الْفَقْرَ﴾ وسمى التخويف وعدًا؟","answer":"سُمّي التخويف وعدًا لأنه إخبار بحصول أمر مستقبل، واستُعمل في الشر مجازًا ومشاكلةً لمقابلة وعد الله الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص281، تحت «سر التعبير بالوعد دون التخويف»","url":""}]},{"id":"s2-1372","number":1372,"surah":2,"verses":[268],"references":[{"surah":2,"verses":[268]}],"verseLabel":"البقرة: 268","question":"لماذا قرن الشيطان الفقر بالأمر بالفحشاء؟","answer":"الخوف من النقص يدفع إلى البخل والرديء والمن وسائر القبائح؛ فبيّن أن الوسوسة الاقتصادية ليست محايدة بل باب لسلوك فاحش.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص283، تحت «استعمال مفردة الفحشاء دون البخل»","url":""}]},{"id":"s2-1373","number":1373,"surah":2,"verses":[268],"references":[{"surah":2,"verses":[268]}],"verseLabel":"البقرة: 268","question":"لماذا ختم بـ﴿وَاللَّهُ وَاسِعٌ عَلِيمٌ﴾؟","answer":"واسع الفضل فيقدر أن يخلف المنفق، وعليم بحاجته ونيته؛ فالفاصلة تواجه خوف الفقر بسعة لا عشوائية فيها بل علم ورعاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص286، تحت «بيان دلالة التوهين والترغيب في الفاصلة»","url":""}]},{"id":"s2-1374","number":1374,"surah":2,"verses":[269],"references":[{"surah":2,"verses":[269]}],"verseLabel":"البقرة: 269","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يذكر إلا أولو الألباب﴾ لا يتفكر أو يعقل؟","answer":"التذكر استحضار المعاني الصحيحة وتنزيلها على مستجدات الحياة، وهو الأنسب بالحكمة، ولا ينتفع به على وجه الاعتبار إلا أولو الألباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص291، تحت «علة إيثار لفظ التذكر دون التفكر أو التعقل»","url":""}]},{"id":"s2-1375","number":1375,"surah":2,"verses":[269],"references":[{"surah":2,"verses":[269]}],"verseLabel":"البقرة: 269","question":"ما سرّ التعبير في قوله تعالى: ﴿يُؤْتِي الْحِكْمَةَ مَنْ يَشَاءُ﴾ بعد الحديث عن الإنفاق؟","answer":"لأن حسن الموازنة بين المال والعاقبة، وتمييز وعد الله من وسوسة الشيطان، ثمرة حكمة؛ فالسياق يوسعها من معرفة الحكم إلى وضعه في موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص288، تحت «بلاغة الفصل بجملة الاعتراض والتذييل»","url":""}]},{"id":"s2-1376","number":1376,"surah":2,"verses":[269],"references":[{"surah":2,"verses":[269]}],"verseLabel":"البقرة: 269","question":"لماذا وصف الحكمة بأنها ﴿خَيْرًا كَثِيرًا﴾؟","answer":"نُكّر الخير ووصف بالكثرة لأنه يشمل أنواع الخير المعنوي، من العقل الراجح والقول الصائب والقرار المتين والفعل الصالح، ويشير كذلك إلى الخير المادي والمال والنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص291، تحت «إيثار لفظ الخير على مرادفاته ووصفه بالكثير»","url":""}]},{"id":"s2-1377","number":1377,"surah":2,"verses":[270],"references":[{"surah":2,"verses":[270]}],"verseLabel":"البقرة: 270","question":"لماذا وحّد الضمير في ﴿فإن الله يعلمه﴾ مع ذكر النفقة والنذر؟","answer":"أُفرد الضمير لأن العطف جاء بـ﴿أو﴾ فرد الضمير إلى الآخر من المذكورين، وقيل: هو عائد إلى ﴿ما﴾ في قوله ﴿وما أنفقتم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص297، تحت «نكتة توحيد الضمير في قوله «يعلمه» دون تثنيته»","url":""}]},{"id":"s2-1378","number":1378,"surah":2,"verses":[270],"references":[{"surah":2,"verses":[270]}],"verseLabel":"البقرة: 270","question":"لماذا جمع بين ﴿مَا أَنْفَقْتُمْ مِنْ نَفَقَةٍ﴾ و﴿نَذَرْتُمْ مِنْ نَذْرٍ﴾؟","answer":"أُدمج النذر مع الإنفاق في تذييل أحكام النفقة للحث على الإنفاق والوفاء بالنذر، وبيان أن الله يعلم ما أنفق العبد وما ألزمه نفسه، سواء تعلق النذر بالمال أم بالأفعال.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص295–296، تحت «بلاغة التذييل في قوله تعالى: ﴿وما أنفقتم من نفقة﴾»","url":""}]},{"id":"s2-1379","number":1379,"surah":2,"verses":[270],"references":[{"surah":2,"verses":[270]}],"verseLabel":"البقرة: 270","question":"لماذا كرر ﴿مِنْ﴾ مع النفقة والنذر؟","answer":"﴿من﴾ بيانية في الموضعين، وتنكير ﴿نفقة﴾ و﴿نذر﴾ في سياق الشرط يؤكد استغراق جميع أنواع النفقات والمنذورات ويمنع تخصيص العموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص296، تحت «الغرض من دخول (من) البيانية على النكرة»","url":""}]},{"id":"s2-1380","number":1380,"surah":2,"verses":[270],"references":[{"surah":2,"verses":[270]},{"surah":5,"verses":[72]}],"verseLabel":"البقرة: 270؛ المائدة: 72","question":"ما مناسبة الوعيد بقوله تعالى: ﴿وما للظالمين من أنصار﴾ بعد ذكر النفقة والنذر في البقرة؟","answer":"قوبل الوعد المفهوم من علم الله بالنفقة والنذر بوعيد من يضعهما في غير موضعهما، كالرياء والمن والأذى والإنفاق الباطل والنذر في المعصية. ونفي الأنصار كناية عن انتفاء النصر والغوث عن هؤلاء الظالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص298، تحت عنوان «فائدة الاستئناف في قوله تعالى: ﴿وما للظالمين من أنصار﴾»","url":""}]},{"id":"s2-1529","number":1529,"surah":2,"verses":[270],"references":[{"surah":2,"verses":[270]},{"surah":5,"verses":[72]}],"verseLabel":"البقرة: 270؛ المائدة: 72","question":"ما دلالة ﴿من﴾ في قوله تعالى في المائدة: ﴿وما للظالمين من أنصار﴾؟","answer":"تؤكد استغراق النفي وتنص على نفي أي نصير؛ فالنكرة في سياق النفي ظاهرة في العموم، ودخول «من» يجعل الدلالة عليه صريحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص445، تحت عنوان «دلالة حرف الجر ﴿من﴾ في قوله: ﴿وما للظالمين من أنصار﴾»","url":""}]},{"id":"s2-1530","number":1530,"surah":2,"verses":[270],"references":[{"surah":2,"verses":[270]},{"surah":5,"verses":[72]}],"verseLabel":"البقرة: 270؛ المائدة: 72","question":"لماذا جاء ﴿أنصار﴾ جمعًا في قوله تعالى في المائدة: ﴿وما للظالمين من أنصار﴾؟","answer":"المفرد النكرة يفيد العموم في سياق النفي أصلًا، فزاد الجمع تنبيهًا على شدة ظلمهم وعظم كفرهم، وأن اجتماع من يتوهمون نصرته لهم لا ينفعهم عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص446، تحت عنوان «نكتة التعبير بالأنصار جمعًا في قوله: ﴿وما للظالمين من أنصار﴾»","url":""}]},{"id":"s2-1381","number":1381,"surah":2,"verses":[271],"references":[{"surah":2,"verses":[271]}],"verseLabel":"البقرة: 271","question":"ما سرّ وصف إبداء الصدقات بقوله تعالى: ﴿فَنِعِمَّا هِيَ﴾، ثم تفضيل إخفائها؟","answer":"الإعلان حسن إذا أظهر الشعيرة وشجع الخير، والإخفاء للفقراء أفضل غالبًا للإخلاص وصون الكرامة؛ ففاضل بحسب المصلحة ولم يذم الأصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص304، تحت «بلاغة تقديم الإبداء على الإخفاء»","url":""}]},{"id":"s2-1382","number":1382,"surah":2,"verses":[271],"references":[{"surah":2,"verses":[271]}],"verseLabel":"البقرة: 271","question":"لماذا قيد الإخفاء بقوله: ﴿وَتُؤْتُوهَا الْفُقَرَاءَ﴾؟","answer":"لأن صدقة التطوع على الفقير هي الأشد تعرضًا للرياء وكسر الخاطر، فإخفاؤها أصون للمنفق والآخذ؛ أما إعلان بعض الواجبات فقد يحقق مصلحة أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص306، تحت «نكتة عطف إيتاء الفقراء على الإخفاء»","url":""}]},{"id":"s2-1383","number":1383,"surah":2,"verses":[271],"references":[{"surah":2,"verses":[271]}],"verseLabel":"البقرة: 271","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيُكَفِّرُ عَنْكُمْ مِنْ سَيِّئَاتِكُمْ﴾؟","answer":"﴿من﴾ للتبعيض؛ فيكفّر الله بعض السيئات لا كلها، وأُبهم هذا البعض حتى لا يغتر العبد بمعرفة ما يكفَّر فيجترئ على ارتكابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص307–308، تحت «تنوع دلالات الحذف والإيجاز»","url":""}]},{"id":"s2-1384","number":1384,"surah":2,"verses":[272],"references":[{"surah":2,"verses":[272]}],"verseLabel":"البقرة: 272","question":"ما مناسبة توجيه الخطاب إلى النبي ﷺ بقوله تعالى: ﴿لَيْسَ عَلَيْكَ هُدَاهُمْ﴾ وسط أحكام الصدقة؟","answer":"جاء وسط أحكام الصدقة تسلية للنبي ﷺ بعد تكرر الحث وعدم امتثال بعض الناس؛ فهداية التوفيق ليست عليه، وإنما عليه البلاغ والبيان والإرشاد، والهداية بيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص314، تحت «بلاغة الاستئناف التعريضي»","url":""}]},{"id":"s2-1385","number":1385,"surah":2,"verses":[272],"references":[{"surah":2,"verses":[272]}],"verseLabel":"البقرة: 272","question":"لماذا كرر ﴿وما تنفقوا من خير﴾ بصيغ متقاربة؟","answer":"ثبت من جهات متعددة أن نفع النفقة يعود للمنفق، وأن الإخلاص شرط، وأن الجزاء كامل؛ فكل تكرار يبني قيدًا لا يعيد الكلام فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص319، تحت «فائدة تكرار فعل الإنفاق في سياق واحد»","url":""}]},{"id":"s2-1386","number":1386,"surah":2,"verses":[272],"references":[{"surah":2,"verses":[272]}],"verseLabel":"البقرة: 272","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا تُنْفِقُوا مِنْ خَيْرٍ فَلِأَنْفُسِكُمْ﴾؟","answer":"مع أن المال يصل إلى الآخذ، فإن نفعه الأخروي يعود إلى المنفق؛ فلا يمنّ على من أعطاه ولا يؤذه بما هو في الحقيقة منفعة له.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص318، تحت «بلاغة قوله تعالى: «وما تنفقوا من خير»»","url":""}]},{"id":"s2-1387","number":1387,"surah":2,"verses":[272],"references":[{"surah":2,"verses":[272]}],"verseLabel":"البقرة: 272","question":"لماذا قيد الإنفاق بقوله: ﴿إِلَّا ابْتِغَاءَ وَجْهِ اللَّهِ﴾؟","answer":"قُيّد الإنفاق بابتغاء وجه الله ليكون خالصًا من الرياء وصوابًا على الوجه المأمور به، وذُكر الوجه للتعظيم ونفي الشركة في القصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص318، تحت «بلاغة قوله: «وما تنفقون إلا ابتغاء وجه الله»»","url":""}]},{"id":"s2-1388","number":1388,"surah":2,"verses":[273],"references":[{"surah":2,"verses":[273]}],"verseLabel":"البقرة: 273","question":"لماذا وصف الفقراء بأن الجاهل يحسبهم أغنياء من التعفف؟","answer":"عفتهم تستر حاجتهم حتى يخطئ من لا يتفقدهم، فدعت الآية إلى البحث خلف المظهر بدل انتظار سؤال يجرح المحتاج.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص327، تحت «براعة ترتيب الجمل بعضها على إثر بعض»","url":""}]},{"id":"s2-1389","number":1389,"surah":2,"verses":[273],"references":[{"surah":2,"verses":[273]}],"verseLabel":"البقرة: 273","question":"ما سرّ التعبير في قوله تعالى: ﴿تعرفهم بسيماهم﴾ ثم قال ﴿لا يسألون الناس إلحافًا﴾؟","answer":"﴿تعرفهم بسيماهم﴾ يجيب عن كيفية معرفة المتعففين بعلاماتهم الخفية، ثم جاء ﴿لا يسألون الناس إلحافًا﴾ للمبالغة في نفي سؤالهم وتأكيد تعففهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص329، تحت «بلاغة اجتماع التصريح والتعريض في سياق واحد»","url":""}]},{"id":"s2-1390","number":1390,"surah":2,"verses":[273],"references":[{"surah":2,"verses":[273]}],"verseLabel":"البقرة: 273","question":"لماذا وصف الفقراء بأنهم ﴿أُحْصِرُوا فِي سَبِيلِ اللَّهِ﴾؟","answer":"وُصفوا بالإحصار لأنه حبس مع تضييق منعهم من السفر والتجارة والتصرف في معايشهم، وخصه كثير من المفسرين بالمجاهدين الذين حاصرهم العدو؛ فبيّنت الآية سبب عجزهم عن طلب الرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص325، تحت «سر استعمال مفردة الحصر دون الحبس»","url":""}]},{"id":"s2-1391","number":1391,"surah":2,"verses":[274],"references":[{"surah":2,"verses":[274]}],"verseLabel":"البقرة: 274","question":"لماذا جمع قوله تعالى: ﴿بِاللَّيْلِ وَالنَّهَارِ سِرًّا وَعَلَانِيَةً﴾ أوقات الإنفاق وأحواله؟","answer":"جمع الليل والنهار لاستغراق جميع الأوقات، والسر والعلانية لاستغراق جميع الأحوال؛ فهم يبادرون إلى سد الحاجة ولا يتعللون بوقت أو حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص333، تحت «فائدة الكلام المستأنف»","url":""}]},{"id":"s2-1392","number":1392,"surah":2,"verses":[274],"references":[{"surah":2,"verses":[274]}],"verseLabel":"البقرة: 274","question":"ما سرّ تقديم الليل على النهار والسر على العلانية؟","answer":"قدم ما هو أليق بالإخفاء وأبعد عن الرياء، مع عدم إلغاء الإعلان النافع؛ فالترتيب يلمح إلى منزلة الإخلاص في باب الصدقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص333–334، تحت «فائدة الكلام المستأنف»","url":""}]},{"id":"s2-1393","number":1393,"surah":2,"verses":[274],"references":[{"surah":2,"verses":[274]}],"verseLabel":"البقرة: 274","question":"ما سر نفي الخوف بالاسم والحزن بالفعل في ختام آية الإنفاق: ﴿لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ﴾؟","answer":"علل المصدر ذلك بأن الخوف يتعلق بالمستقبل المتعدد الاحتمالات، فجاء نفيه بالاسم للدلالة على العموم، أما الحزن فمتعلقه الماضي المحصور، فجاء نفيه بالفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص336، تحت «نكتة نفي الحزن بالفعل، والخوف بالاسم»","url":""}]},{"id":"s2-1394","number":1394,"surah":2,"verses":[275],"references":[{"surah":2,"verses":[275]}],"verseLabel":"البقرة: 275","question":"لماذا شبّه آكل الربا بمن يتخبطه الشيطان من المس؟","answer":"صوّر المرابي في الدنيا مضطربًا يستفزه الطمع، وفي الآخرة قائمًا كالمصروع يتخبط ولا يمشي سويًا؛ فجمع التشنيع بسوء حاله في الدنيا والوعيد عند البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص343، تحت «روعة التصوير في التشبيه التمثيلي لآكل الربا بالممسوس»","url":""}]},{"id":"s2-1395","number":1395,"surah":2,"verses":[275],"references":[{"surah":2,"verses":[275]}],"verseLabel":"البقرة: 275","question":"ما دلالة قولهم: ﴿إِنَّمَا الْبَيْعُ مِثْلُ الرِّبَا﴾ دون أن يجعلوا الربا هو المشبَّه بالبيع؟","answer":"جعلوا الربا أصلًا يقيسون عليه البيع مبالغة في قلب الفطرة، كأن الزيادة الربوية هي المعيار والمعاملة المشروعة فرعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص345، تحت «دلالة التشبيه المقلوب في قوله تعالى: «قالوا إنما البيع مثل الربا»»","url":""}]},{"id":"s2-1396","number":1396,"surah":2,"verses":[275],"references":[{"surah":2,"verses":[275]}],"verseLabel":"البقرة: 275","question":"لماذا رد على قولهم ﴿إِنَّمَا الْبَيْعُ مِثْلُ الرِّبَا﴾ بقوله: ﴿وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا﴾؟","answer":"لم يدخل في قياسهم المقلوب، بل أعاد الفصل إلى حكم الله الذي يعلم الفرق بين تبادل المنافع وزيادة الدين المستغلة؛ فالتشابه الشكلي لا يلغي اختلاف الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص346، تحت «بلاغة الاستئناف في قوله تعالى: «وأحل الله البيع وحرم الربا»»","url":""}]},{"id":"s2-1397","number":1397,"surah":2,"verses":[275],"references":[{"surah":2,"verses":[275]}],"verseLabel":"البقرة: 275","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَهُ مَا سَلَفَ وَأَمْرُهُ إِلَى اللَّهِ﴾ لمن انتهى؟","answer":"من انتهى فله ما مضى قبل التحريم، وأمر جزائه على انتهائه موكول إلى الله؛ وهو وعد له يقابله وعيد من عاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص348، تحت «دلالة عود الضمير على ما تقدم في قوله تعالى: «وأمره إلى الله»»","url":""}]},{"id":"s2-1398","number":1398,"surah":2,"verses":[276],"references":[{"surah":2,"verses":[276]}],"verseLabel":"البقرة: 276","question":"كيف يُفهم قوله تعالى: ﴿يَمْحَقُ اللَّهُ الرِّبَا وَيُرْبِي الصَّدَقَاتِ﴾ مع أن الربا يزيد في الظاهر والصدقة تنقص؟","answer":"لأن الربا في الظاهر زيادة وفي الحقيقة نقصان ومحق للبركة، والصدقة في الظاهر تنقيص للمال وفي حقيقتها زيادة وبركة ونماء وأجر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص354، تحت «فائدة الفصل والاستطراد في قوله: «يمحق الله الربا ويربي الصدقات»»","url":""}]},{"id":"s2-1399","number":1399,"surah":2,"verses":[276,283],"references":[{"surah":2,"verses":[276,283]}],"verseLabel":"البقرة: 276 و283","question":"ما سرّ التعبير في قوله تعالى عن آكل الربا: ﴿كُلَّ كَفَّارٍ أَثِيمٍ﴾، وقال عن كاتم الشهادة: ﴿فَإِنَّهُ آثِمٌ قَلْبُهُ﴾؛ لماذا ﴿أثيم﴾ هنا و﴿آثم﴾ هناك؟","answer":"﴿أثيم﴾ صيغة أشد من ﴿آثم﴾؛ فهي تدل على التمادي في الإثم والإقامة عليه والإصرار بلا مبالاة، ولذلك جاءت في الربا والكفر ونحوهما من الجرائم العامة الشديدة التي يتأذى بها المجتمع. أما ﴿آثم﴾ فتعني فاعل الإثم، وجاءت في كتمان الشهادة الذي يتعلق أثره المباشر غالبًا بالأفراد. فاختلاف الصيغتين يرسم تفاوت الجريمة ورسوخ صاحبها فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص441، تحت «توجيه المتشابه اللفظي في الصفة»","url":""}]},{"id":"s2-1400","number":1400,"surah":2,"verses":[276],"references":[{"surah":2,"verses":[276]}],"verseLabel":"البقرة: 276","question":"لماذا اختار ﴿يُرْبِي الصَّدَقَاتِ﴾ من المادة نفسها التي اشتق منها الربا؟","answer":"ليبين أن النماء الحقيقي في العطاء المشروع لا في الزيادة المحرمة؛ فالتقارب اللفظي يضاعف المفارقة بين اسم الربا وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص355، تحت «بديع التجنيس بين الاسم والفعل»","url":""}]},{"id":"s2-1401","number":1401,"surah":2,"verses":[276],"references":[{"surah":2,"verses":[276]}],"verseLabel":"البقرة: 276","question":"لماذا ختم بـ﴿وَاللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ﴾؟","answer":"جاءت الجملة اعتراضًا لتحذير المرابين بنفي محبة الله عنهم، وجيء بصيغتي المبالغة ﴿كفّار﴾ و﴿أثيم﴾ لتغليظ أمر الربا والتنبيه إلى عظم الكفر والإثم في استحلاله وتسويته بالبيع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص356، تحت «سر التعبير بصيغة فعال وفعيل في قوله «كفار أثيم»»","url":""}]},{"id":"s2-1402","number":1402,"surah":2,"verses":[277],"references":[{"surah":2,"verses":[277]}],"verseLabel":"البقرة: 277","question":"لماذا أعاد صفات الإيمان والصلاة والزكاة بين آيات الربا؟","answer":"ذُكرت حال المؤمنين في مقابلة حال المرابين، لأن الإيمان والصلاة والزكاة أسباب لاجتناب الربا، ولأن الصلاة تنهى عن الفحشاء والمنكر والزكاة إحسان يناقض ظلم الربا؛ وفي ذلك تسلية وترغيب بعد الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص360، تحت «توجيه الخصوص بالذكر في قوله: «وأقاموا الصلاة وآتوا الزكاة»»","url":""}]},{"id":"s2-1403","number":1403,"surah":2,"verses":[277],"references":[{"surah":2,"verses":[277]}],"verseLabel":"البقرة: 277","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ﴾ بعد ﴿عَمِلُوا الصَّالِحَاتِ﴾؟","answer":"خُصت الصلاة والزكاة بالذكر بعد اندراجهما في الصالحات تنبيهًا على فضلهما؛ فالصلاة أعظم الأعمال البدنية والزكاة أفضل الأعمال المالية، وهما أصل الانتهاء عن الربا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص360، تحت «توجيه المخصوص بالذكر في قوله: «وأقاموا الصلاة وآتوا الزكاة»»","url":""}]},{"id":"s2-1404","number":1404,"surah":2,"verses":[277],"references":[{"surah":2,"verses":[277]}],"verseLabel":"البقرة: 277","question":"ما سرّ التعبير في قوله تعالى: ﴿أَجْرُهُمْ عِنْدَ رَبِّهِمْ﴾؟","answer":"ذُكرت العندية لرفعة المؤمنين وتعظيمهم، وأضاف الرب إلى ضميرهم مزيد لطف وتشريف؛ فثوابهم محض فضل من ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص362، تحت «بلاغة التعبير في قوله: «عند ربهم»»","url":""}]},{"id":"s2-1405","number":1405,"surah":2,"verses":[278,279],"references":[{"surah":2,"verses":[278,279]}],"verseLabel":"البقرة: 278–279","question":"لماذا سمّى الإصرار على الربا حربًا من الله ورسوله؟","answer":"سُمّي الإصرار حربًا، ونُكّرت ﴿حرب﴾ للتهويل والتعظيم، وأضيفت إلى الله ورسوله غاية في التهديد والتحذير من تعاطي الربا وعدم الانتهاء عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص367، تحت «تنكير لفظ «حرب» في قوله تعالى «فأذنوا بحرب» للتعظيم والتهديد»","url":""}]},{"id":"s2-1406","number":1406,"surah":2,"verses":[278],"references":[{"surah":2,"verses":[278]}],"verseLabel":"البقرة: 278","question":"لماذا افتتح تحريم ما بقي من الربا بقوله: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ﴾؟","answer":"جعل ترك الربا اختبارًا مباشرًا لصدق الإيمان والتقوى؛ فالنداء يستنهض الهوية قبل أمر يمس مصلحة مالية راسخة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص365، تحت «سر النداء لأهل الإيمان بأم أدوات النداء «يا»»","url":""}]},{"id":"s2-1407","number":1407,"surah":2,"verses":[278],"references":[{"surah":2,"verses":[278]}],"verseLabel":"البقرة: 278","question":"ما دلالة اختيار ﴿وَذَرُوا﴾ في الأمر بترك ما بقي من الربا؟","answer":"يفرق المصدر بين «يدع» الذي قد يدل على الترك مع الاهتمام بالشيء، و«يذر» الذي يدل على التخلي عنه وإهماله وعدم الاعتداد به؛ فيناسب الأمر بطرح الربا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص370، تحت «الفروق المعجمية: (يذر) و(يدع)»","url":""}]},{"id":"s2-1408","number":1408,"surah":2,"verses":[278],"references":[{"surah":2,"verses":[278]}],"verseLabel":"البقرة: 278","question":"لماذا ختم الشرط بقوله: ﴿إِنْ كُنْتُمْ مُؤْمِنِينَ﴾؟","answer":"ليس المراد الشك في خطابهم، بل إلهاب ضميرهم: إن كان الإيمان هو الحقيقة الحاكمة فليظهر أثره عند تعارض الأمر مع الربح.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص366، تحت «نكتة خطاب المؤمنين بالإيمان واشتراطه فيهم في فاصلتها»","url":""}]},{"id":"s2-1409","number":1409,"surah":2,"verses":[279],"references":[{"surah":2,"verses":[279]}],"verseLabel":"البقرة: 279","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ وَرَسُولِهِ﴾؟","answer":"جعل الإصرار على الربا مواجهة لنظام العدل الإلهي كله، فاختار الحرب لتصوير جسامة الجريمة وآثارها التي تسحق الضعفاء والمجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص368، تحت «نكتة العدول عن الإضافة إلى استعمال حرف الجر»","url":""}]},{"id":"s2-1410","number":1410,"surah":2,"verses":[279],"references":[{"surah":2,"verses":[279]}],"verseLabel":"البقرة: 279","question":"ما سرّ التعبير للتائبين بقوله تعالى: ﴿فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ﴾؟","answer":"حفظ أصل المال كما منع الزيادة، فالتوبة لا تعني ظلم الدائن بإسقاط حقه ولا ظلم المدين بالربا؛ وهذا يفسره قوله بعدها: لا تظلمون ولا تظلمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص370، تحت عنوان «بديع الجناس التام في قوله تعالى: ﴿لا تظلمون ولا تظلمون﴾»","url":""}]},{"id":"s2-1411","number":1411,"surah":2,"verses":[279],"references":[{"surah":2,"verses":[279]}],"verseLabel":"البقرة: 279","question":"لماذا جاء: ﴿لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ﴾ بالبناءين المختلفين؟","answer":"جمع منع الظلم الصادر منهم بأخذ الزيادة، ومنع الظلم الواقع عليهم بنقص رأس المال؛ فالتوازن اللفظي يلخص عدالة الحكم للطرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص370، تحت «بديع الجناس التام في قوله تعالى: «لا تظلمون ولا تظلمون»»","url":""}]},{"id":"s2-1412","number":1412,"surah":2,"verses":[280],"references":[{"surah":2,"verses":[280]}],"verseLabel":"البقرة: 280","question":"ما سرّ التعبير في قوله تعالى: ﴿فنظرة إلى ميسرة﴾ بالمصدر لا: فأنظروه؟","answer":"جاء المصدر المرفوع جوابًا للشرط بتقدير: فعليكم نظرة أو فتجب نظرة؛ فلفظه خبر ومعناه الأمر، وهو صيغة طلب تؤكد إنظار المعسر إلى الميسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص373، تحت «دلالة إيجاز الحذف في قوله تعالى: ﴿فنظرة إلى ميسرة﴾»","url":""}]},{"id":"s2-1413","number":1413,"surah":2,"verses":[280],"references":[{"surah":2,"verses":[280]}],"verseLabel":"البقرة: 280","question":"ما سرّ التعبير في قوله تعالى: ﴿وأن تصدقوا خير لكم﴾ فسمّى إسقاط الدين صدقة؟","answer":"لأن الدائن يهب حقًا ثابتًا للمعسر، فكان إسقاط بعضه أو كله عطاءً حقيقيًا يتقرب به إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص373، تحت «قيمة التعبير عن إسقاط الدين بالصدقة»","url":""}]},{"id":"s2-1414","number":1414,"surah":2,"verses":[280],"references":[{"surah":2,"verses":[280]}],"verseLabel":"البقرة: 280","question":"ما دلالة عطف ﴿وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ﴾ على تقرير استحقاق رؤوس الأموال؟","answer":"لما كان ظاهر استحقاق رؤوس الأموال استرجاعها معجلة، ذكرت حالة المدين المعسر لاستثنائها من التعجيل، وأكد الشرط إمهاله حتى يجد سعة؛ مراعاة لحاله ودفعًا للمشقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص372–373، تحت «دلالة العطف بالجملة الشرطية في قوله: ﴿وإن كان ذو عسرة فنظرة﴾»","url":""}]},{"id":"s2-1415","number":1415,"surah":2,"verses":[280],"references":[{"surah":2,"verses":[280]}],"verseLabel":"البقرة: 280","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَنْ تَصَدَّقُوا خَيْرٌ لَكُمْ﴾ بعد وجوب الإنظار؟","answer":"نقل الدائن من حد العدل إلى فضل إسقاط بعض الدين أو كله، وسماه صدقة ليعيد تعريف الخسارة الظاهرة مكسبًا أخرويًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص373، تحت «قيمة التعبير عن إسقاط الدين بالصدقة»","url":""}]},{"id":"s2-1416","number":1416,"surah":2,"verses":[281],"references":[{"surah":2,"verses":[281]}],"verseLabel":"البقرة: 281","question":"لماذا ختمت أحكام الأموال بقوله ﴿واتقوا يومًا ترجعون فيه إلى الله﴾؟","answer":"خُتمت أحكام الإنفاق والربا والإحسان إلى المعسرين بالموعظة بالرجوع إلى الله ليجتمع الترغيب والترهيب، ويُحمل الناس على امتثال الأوامر والنواهي وأداء الحقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص378، تحت «بلاغة المجاز المرسل في قوله تعالى: ﴿واتقوا يومًا﴾»","url":""}]},{"id":"s2-1417","number":1417,"surah":2,"verses":[281],"references":[{"surah":2,"verses":[281]}],"verseLabel":"البقرة: 281","question":"ما سرّ التعبير في قوله تعالى: ﴿تُرْجَعُونَ فِيهِ إِلَى اللَّهِ﴾ مع أن الخلق إليه دائمًا؟","answer":"الرجوع هنا رجوع إلى الحساب والجزاء؛ أي تصيرون إلى الله أو تُردّون إليه ليحاسبكم على أعمالكم، ولذلك خُص يوم القيامة بهذا الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص379، تحت «توجيه القراءات القرآنية»","url":""}]},{"id":"s2-1418","number":1418,"surah":2,"verses":[281],"references":[{"surah":2,"verses":[281]}],"verseLabel":"البقرة: 281","question":"ما سرّ التعبير في قوله تعالى: ﴿ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَا كَسَبَتْ﴾؟","answer":"﴿توفى﴾ تدل على إعطاء الجزاء كاملًا، و﴿كل نفس﴾ تمنع الاستثناء، ثم نفى الظلم ليجمع تمام الحساب وعدله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص379، تحت «فائدة التعميم في قوله تعالى: «كل نفس ما كسبت»»","url":""}]},{"id":"s2-1419","number":1419,"surah":2,"verses":[282],"references":[{"surah":2,"verses":[282]}],"verseLabel":"البقرة: 282","question":"ما فائدة تنكير ﴿بِدَيْنٍ﴾ في آية المداينة؟","answer":"جاءت النكرة في سياق الشرط لإفادة العموم، فيشمل لفظ الدين القليل والكثير والصغير والكبير، وما كان من سلم أو بيع؛ فلا يختص الأمر بنوع معين أو مقدار كبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص391، تحت «فائدة التنكير في قوله: ﴿بدين﴾»","url":""}]},{"id":"s2-1420","number":1420,"surah":2,"verses":[282],"references":[{"surah":2,"verses":[282]}],"verseLabel":"البقرة: 282","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يبخس منه شيئًا﴾ لا: ولا ينقص؟","answer":"البخس نقص مع ظلم وازدراء للحق، فهو يكشف القصد الأخلاقي المحرم لا مجرد خطأ حسابي في المقدار.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص405، تحت «سر الاستعارة بلفظ البخس في قوله: ﴿ولا يبخس منه شيئًا﴾»","url":""}]},{"id":"s2-1421","number":1421,"surah":2,"verses":[282],"references":[{"surah":2,"verses":[282]}],"verseLabel":"البقرة: 282","question":"لماذا نكّر ﴿كاتب﴾ في ﴿وليكتب بينكم كاتب بالعدل﴾؟","answer":"أفاد تنكير ﴿كاتب﴾ العموم والتأكيد على الكتابة؛ أي يستكتب أي كاتب تتحقق به الكفاية، من غير تعيين شخص أو اسم أو قرابة، بشرط أن يكتب بالعدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص398–399، تحت «فائدة تنكير لفظ: ﴿كاتب﴾»","url":""}]},{"id":"s2-1422","number":1422,"surah":2,"verses":[282],"references":[{"surah":2,"verses":[282]}],"verseLabel":"البقرة: 282","question":"ما سرّ التعبير في قوله تعالى: ﴿فليكتب﴾ بالفاء بعد الأمر بإملاء المدين؟","answer":"الفاء تجعل الكتابة نتيجة فورية للإملاء الصحيح، فتربط قول صاحب الحق بما يثبته الكاتب بلا فجوة تعرضه للتغيير.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص402، تحت «فائدة التفريع بالفاء في قوله «فليكتب»»","url":""}]},{"id":"s2-1423","number":1423,"surah":2,"verses":[282],"references":[{"surah":2,"verses":[282]}],"verseLabel":"البقرة: 282","question":"لماذا جُعلت شهادة امرأتين مكان رجل واحد في هذا السياق؟","answer":"جُعلت المرأتان لتقوم إحداهما بتذكير الأخرى إذا نسيت جزءًا من الشهادة، حتى يتحصل من مجموع شهادتيهما شهادة واحدة كاملة مستقيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص417، تحت «الثانية: أثر ارتباط الشهادة بالقوامة»","url":""}]},{"id":"s2-1424","number":1424,"surah":2,"verses":[282],"references":[{"surah":2,"verses":[282]}],"verseLabel":"البقرة: 282","question":"ما سرّ التعبير في قوله تعالى: ﴿أن تضل إحداهما فتذكر إحداهما الأخرى﴾ وكرر ﴿إحداهما﴾؟","answer":"ليبقي الاحتمال متبادلًا؛ لا يعين واحدة للنسيان وأخرى للتذكير، فقد تكون كل منهما معينة لصاحبتها بحسب الواقعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص410، تحت «سر إظهار ما ظاهره الإضمار في قوله تعالى: «فتذكر إحداهما الأخرى»»","url":""}]},{"id":"s2-1425","number":1425,"surah":2,"verses":[282],"references":[{"surah":2,"verses":[282]}],"verseLabel":"البقرة: 282","question":"لماذا نفى الجناح بـ﴿فليس عليكم جناح﴾ لا: فلا جناح؟","answer":"جيء بنفي الجناح بـ﴿ليس﴾ دون ﴿لا﴾ لأن رفع الحرج في ترك كتابة التجارة الحاضرة قد لا يكون مستقرًا في نفوسهم بعد الأمر العام بالكتابة، فكان النفي بـ﴿ليس﴾ أكمل في التنزيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص421، تحت «وجه النفي بـ(ليس) دون (لا) في قوله تعالى «فليس عليكم جناح ألا تكتبوها»»","url":""}]},{"id":"s2-1426","number":1426,"surah":2,"verses":[282],"references":[{"surah":2,"verses":[282]}],"verseLabel":"البقرة: 282","question":"ما سرّ التعبير في قوله تعالى: ﴿إِذَا تَدَايَنْتُمْ﴾، دون أن يقال: «إذا استدنتم» أو «أدنتم»؟","answer":"صيغة ﴿تداينتم﴾ تشمل طرفي المعاملة معًا: الدائن الذي يعطي، والمدين الذي يأخذ؛ فكلاهما داخل في حفظ العقد وكتابته. أما «استدنتم» فتتجه إلى المدينين وحدهم، و«أدنتم» إلى الدائنين. فاختيرت صيغة المشاركة لتجعل صيانة الحق مسؤولية مشتركة، لا عبئًا على أحد الطرفين فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص389، تحت «فائدة إيثار صيغة المفاعلة في لفظ «تداينتم»»","url":""}]},{"id":"s2-1427","number":1427,"surah":2,"verses":[282],"references":[{"surah":2,"verses":[282]}],"verseLabel":"البقرة: 282","question":"ما سرّ التعبير في قوله تعالى: ﴿إِذَا تَدَايَنْتُمْ بِدَيْنٍ﴾؛ أليس ذكر ﴿بِدَيْنٍ﴾ زائدًا لأن التداين يدل عليه؟","answer":"ذُكر ﴿بدين﴾ بعد ﴿تداينتم﴾ للتأكيد بأن الدين هو الباعث على الكتابة، ولإزالة احتمال المجاز أو الاشتراك، وليعود إليه الضمير في ﴿فاكتبوه﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص390، تحت «النكات البيانية المستنبطة من ذكر قيد «بدين» بعد قوله «تداينتم»»","url":""}]},{"id":"s2-1428","number":1428,"surah":2,"verses":[282],"references":[{"surah":2,"verses":[282]}],"verseLabel":"البقرة: 282","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَسْأَمُوا أَنْ تَكْتُبُوهُ صَغِيرًا أَوْ كَبِيرًا﴾ فقدم الدين الصغير على الكبير؟","answer":"لأن مظنة التهاون بالكتابة تقع في الدين الصغير أكثر؛ فقد يقول صاحبه: هذا مبلغ قليل لا يحتاج إلى توثيق. فقدم الصغير لدفع هذا الوهم من بدايته، ثم عطف عليه الكبير لاستيعاب الجميع. والتقديم هنا لا يتبع حجم المال، بل يتجه أولًا إلى الموضع الأشد حاجةً إلى التنبيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص414، تحت «وجه التقديم والتأخير في قوله: «صغيرًا أو كبيرًا»»","url":""}]},{"id":"s2-1429","number":1429,"surah":2,"verses":[282],"references":[{"surah":2,"verses":[282]}],"verseLabel":"البقرة: 282","question":"لماذا كلف المدين بالإملاء: ﴿وَلْيُمْلِلِ الَّذِي عَلَيْهِ الْحَقُّ﴾؟","answer":"لأنه المقر بما في ذمته، فإملاؤه أقوى في الحجة وأبعد عن زيادة الدائن، ثم أحاطه بالأمر بالتقوى والنهي عن بخس شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص403، تحت «فائدة أمر المدين بالإملال في قوله تعالى: «وليملل الذي عليه الحق»»","url":""}]},{"id":"s2-1430","number":1430,"surah":2,"verses":[282],"references":[{"surah":2,"verses":[282]}],"verseLabel":"البقرة: 282","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا يَأْبَ كَاتِبٌ أَنْ يَكْتُبَ كَمَا عَلَّمَهُ اللَّهُ﴾؟","answer":"جعل المعرفة بالكتابة نعمة يقابلها خدمة العدل، فلا يحتكرها صاحبها عند حاجة الناس. و﴿كما علمه الله﴾ تربط المهارة بالشكر والأمانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص400–401، تحت «تردد الكاف بين معنى التشبيه والتعليل في قوله تعالى: ﴿كما علمه الله﴾»","url":""}]},{"id":"s2-1431","number":1431,"surah":2,"verses":[283],"references":[{"surah":2,"verses":[283]}],"verseLabel":"البقرة: 283","question":"لماذا انتقل من الكتابة في الحضر إلى ﴿وإن كنتم على سفر﴾؟","answer":"السفر مظنة فقد الكاتب وأدوات التوثيق، فانتقل إلى بديل محسوس هو الرهن المقبوض، لتبقى الحقوق محفوظة مع تغير الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص432، تحت «فائدة الوصل بين الجمل»","url":""}]},{"id":"s2-1432","number":1432,"surah":2,"verses":[283],"references":[{"surah":2,"verses":[283]}],"verseLabel":"البقرة: 283","question":"لماذا عطف السفر بالواو لا بالفاء؟","answer":"لأنه حالة أخرى موازية لأحكام الدين وليست نتيجة زمنية حتمية لما قبلها؛ فالواو تجمع الأحوال بلا تعقيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص432، تحت «فائدة الوصل بين الجمل»","url":""}]},{"id":"s2-1433","number":1433,"surah":2,"verses":[283],"references":[{"surah":2,"verses":[283]}],"verseLabel":"البقرة: 283","question":"لماذا ذكر فقد الكاتب ولم يذكر فقد الشاهد؟","answer":"خُص الكاتب بالذكر لأن فقده وفقد أدوات الكتابة هو الشائع في السفر، بخلاف الشهود فقد يتوافرون؛ وللتنبيه إلى أن كتابة الدين أصل حتى في السفر، فيبحث عن كاتب، فإن عُدم فالرهن المقبوض.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص434، تحت «توجيه الخصوص بالذكر»","url":""}]},{"id":"s2-1434","number":1434,"surah":2,"verses":[283],"references":[{"surah":2,"verses":[283]}],"verseLabel":"البقرة: 283","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تكتموا الشهادة... فإنه آثم قلبه﴾ فنسب الإثم إلى القلب؟","answer":"لأن الكتمان قرار باطن متعمد قبل أن يكون صمت اللسان، ولأن فساد موضع الأمانة هو أصل الجريمة وإن خفيت عن الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص440، تحت «وجه إسناد الإثم إلى القلب»","url":""}]},{"id":"s2-1435","number":1435,"surah":2,"verses":[283],"references":[{"surah":2,"verses":[283]}],"verseLabel":"البقرة: 283","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ كُنْتُمْ عَلَى سَفَرٍ وَلَمْ تَجِدُوا كَاتِبًا فَرِهَانٌ مَقْبُوضَةٌ﴾؟","answer":"لما تعذر التوثيق بالكتابة انتقل إلى توثيق محسوس يناسب السفر، واشتراط القبض يجعل الرهن ضمانًا فعليًا لا وعدًا لفظيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص436، تحت «سر وصف الرهان بالمقبوضة»","url":""}]},{"id":"s2-1436","number":1436,"surah":2,"verses":[283],"references":[{"surah":2,"verses":[283]}],"verseLabel":"البقرة: 283","question":"لماذا انتقل من الوثائق إلى قوله: ﴿فَإِنْ أَمِنَ بَعْضُكُمْ بَعْضًا﴾؟","answer":"اعترف بأن الثقة قد تغني عن الرهن، لكنه لم يتركها بلا وازع؛ نقل الضمان من اليد إلى أمانة القلب وتقوى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص436، تحت «نكتة استعمال «إن» دون «إذا»»","url":""}]},{"id":"s2-1438","number":1438,"surah":2,"verses":[284],"references":[{"surah":2,"verses":[284]}],"verseLabel":"البقرة: 284","question":"ما دلالة الكناية بالإخفاء في قوله تعالى: ﴿وَإِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ﴾؟","answer":"الإخفاء كناية عن عدم الإظهار للناس؛ فالإبداء والإخفاء وصفان بالنسبة إلى المخلوقين، وهما سواء بالنسبة إلى علم الله الذي لا يخفى عليه شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص450، تحت «سر استعمال الكناية في الألفاظ»","url":""}]},{"id":"s2-1439","number":1439,"surah":2,"verses":[284],"references":[{"surah":2,"verses":[284]},{"surah":5,"verses":[40]},{"surah":29,"verses":[21]}],"verseLabel":"البقرة: 284، العنكبوت: 21، المائدة: 40","question":"لماذا قدَّم في البقرة المغفرة: ﴿فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ﴾، بينما قدَّم العذاب في العنكبوت والمائدة؟","answer":"جاءت خاتمة البقرة في خطاب المؤمنين الذين أعلنوا السمع والطاعة وطلبوا المغفرة، فناسب مقام الرجاء والرحمة أن تتقدم المغفرة. أما العنكبوت ففي إنذار منكري البعث وقوم إبراهيم، والمائدة بعد أحكام الحرابة والسرقة؛ فناسب مقام الزجر والتهديد أن يتقدم العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص223، تحت «توجيه المتشابه اللفظي في التقديم والتأخير»","url":""}]},{"id":"s2-1440","number":1440,"surah":2,"verses":[284],"references":[{"surah":2,"verses":[284]}],"verseLabel":"البقرة: 284","question":"ما سرّ التعبير في قوله تعالى: ﴿لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ﴾ بعد أحكام الأموال؟","answer":"بعد بيان أحكام الدين وأداء الحقوق، ذُكّر بأن ملك السماوات والأرض كله لله، وأن ما يملكه العبد مآله إليه؛ ثم مهّد هذا العموم لإحاطة علمه بما يظهره الناس وما يخفونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص449، تحت «دلالة العطف بين الجملتين»","url":""}]},{"id":"s2-1441","number":1441,"surah":2,"verses":[284],"references":[{"surah":2,"verses":[284]}],"verseLabel":"البقرة: 284","question":"لماذا يحاسب الله على ما في الأنفس، مع أن الخاطر قد لا يملكه الإنسان؟","answer":"المحاسبة على ما استقر في النفس من نية وعزم، ولا تدخل فيها الوساوس وأحاديث النفس التي لا عقد ولا عزيمة فيها؛ فالتكليف بحسب الوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص447، تحت «شرح المفردات: ﴿أو تخفوه﴾»","url":""}]},{"id":"s2-1442","number":1442,"surah":2,"verses":[284],"references":[{"surah":2,"verses":[284]}],"verseLabel":"البقرة: 284","question":"لماذا ختم بـ﴿وَاللَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾ بعد المغفرة والعذاب؟","answer":"لأن تنفيذ الحساب والمغفرة والعقوبة جميعًا فرع القدرة الشاملة، فلا يعجزه باطن خفي ولا كثرة الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص451، تحت «فن تشابه الأطراف»","url":""}]},{"id":"s2-1443","number":1443,"surah":2,"verses":[285],"references":[{"surah":2,"verses":[285]}],"verseLabel":"البقرة: 285","question":"ما سرّ التعبير في قوله تعالى: ﴿آمن الرسول﴾ بالماضي لا يؤمن؟","answer":"الماضي يحقق ثبوت الإيمان واستقراره كحقيقة منجزة عند نزول الوحي، لا حالة منتظرة أو متقلبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص461، تحت «سر التعبير بصيغة الماضي دون المضارع»","url":""}]},{"id":"s2-1444","number":1444,"surah":2,"verses":[285],"references":[{"surah":2,"verses":[285]}],"verseLabel":"البقرة: 285","question":"لماذا أفرد الرسول أولًا ثم جمع المؤمنين في ﴿والمؤمنون كل آمن﴾؟","answer":"قدم أول متلق ومصدق ثم ألحق به الجماعة، لتظهر وحدة العقيدة مع تميز موقع الرسول في تلقي التنزيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص457، تحت «بيان مظاهر تعظيم النبي وخصوصية إيمانه»","url":""}]},{"id":"s2-1445","number":1445,"surah":2,"verses":[285],"references":[{"surah":2,"verses":[285]}],"verseLabel":"البقرة: 285","question":"ما دلالة قول المؤمنين: ﴿سَمِعْنَا وَأَطَعْنَا﴾ بهذا الترتيب، ثم طلب المغفرة بعدهما؟","answer":"قُدّم السمع لأن تلقي التكليف وقبوله طريقه السمع، والطاعة أثره. وقدّموهما على طلب المغفرة تقديمًا للوسيلة على المطلوب، رجاء الإجابة والقبول.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص462، تحت عنوان «نكتة تقديم السمع على الطاعة؛ وتقديمهما على طلب المغفرة»","url":""}]},{"id":"s2-1446","number":1446,"surah":2,"verses":[285],"references":[{"surah":2,"verses":[285]}],"verseLabel":"البقرة: 285","question":"لماذا ختموا بـ﴿غفرانك ربنا وإليك المصير﴾ بعد الإيمان والطاعة؟","answer":"قدموا السماع والطاعة وسيلةً بين يدي سؤال المغفرة، ثم أتبعوا ذلك بذكر المصير إلى الله للحساب والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص462، تحت «دلالة التذييل في قوله «وإليك المصير»»","url":""}]},{"id":"s2-1448","number":1448,"surah":2,"verses":[285],"references":[{"surah":2,"verses":[285]}],"verseLabel":"البقرة: 285","question":"ما سرّ التعبير في قوله تعالى: ﴿كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ﴾؟","answer":"﴿كل﴾ تجمع الرسول والمؤمنين وتفصل عقيدة كل فرد، ثم ترتب أصول الغيب والوحي وحملته في نسق واحد متكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص459، تحت «ترتيب مبادئ الإيمان وأصوله»","url":""}]},{"id":"s2-1449","number":1449,"surah":2,"verses":[285],"references":[{"surah":2,"verses":[285]}],"verseLabel":"البقرة: 285","question":"ما دلالة قولهم: ﴿لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ﴾ بعد ذكر تفضيل بعض الرسل؟","answer":"لا نفرق في أصل التصديق والقبول، وإن تفاوتت منازلهم التي فضلهم الله بها؛ فالتفضيل الإلهي لا يبرر إيمانًا ببعض وكفرًا ببعض.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص460، تحت «وجه ذكر التفريق في شأن الإيمان بالرسل»","url":""}]},{"id":"s2-1450","number":1450,"surah":2,"verses":[286],"references":[{"surah":2,"verses":[286]}],"verseLabel":"البقرة: 286","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يكلف الله نفسًا إلا وسعها﴾ لا طاقتها؟","answer":"الوسع ما يمكن فعله بلا حرج بالغ، أما الطاقة فقد تعني أقصى قدرة مع مشقة؛ فاختير اللفظ الأرفق في خاتمة التكاليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص472، تحت «نكتة احتمال كلمة (وسع) للقدرة والطاقة»","url":""}]},{"id":"s2-1451","number":1451,"surah":2,"verses":[286],"references":[{"surah":2,"verses":[286]}],"verseLabel":"البقرة: 286","question":"ما سرّ التعبير في قوله تعالى في الخير ﴿لها ما كسبت﴾، وفي الشر ﴿عليها ما اكتسبت﴾ بزيادة التاء؟","answer":"الكسب أخف فناسب الخير الموافق للفطرة، والاكتساب ذو زيادة وتكلف فناسب الشر الذي تتحمله النفس؛ كما قابلت اللام النافعة ﴿على﴾ الضارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص473، تحت «بديع المقابلة بين جملة «لها ما كسبت» وجملة «وعليها ما اكتسبت»»","url":""}]},{"id":"s2-1452","number":1452,"surah":2,"verses":[286],"references":[{"surah":2,"verses":[286]}],"verseLabel":"البقرة: 286","question":"لماذا كرر المؤمنون ﴿ربنا﴾ في كل دعاء من ختام السورة؟","answer":"كرروا ﴿ربنا﴾ مع المطالب المتعاطفة لإظهار مزيد الضراعة والتذلل، وتعليم تجديد النداء في كل حال ومطلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص477، تحت «دلالة تكرير النداء بصيغة الجمع «ربنا» في هذه الدعوات»","url":""}]},{"id":"s2-1453","number":1453,"surah":2,"verses":[286],"references":[{"surah":2,"verses":[286]}],"verseLabel":"البقرة: 286","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تؤاخذنا إن نسينا أو أخطأنا﴾ مع أن النسيان والخطأ غير متعمدين؟","answer":"دعاء برفع آثار الخطأ وتبعاته وتعليم دائم للافتقار، وقد استجاب الله برفع المؤاخذة التي لا اختيار فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص475، تحت «سر الدعاء بعدم المؤاخذة على النسيان والخطأ مع كونهما معفوًا عنهما»","url":""}]},{"id":"s2-1454","number":1454,"surah":2,"verses":[286],"references":[{"surah":2,"verses":[286]}],"verseLabel":"البقرة: 286","question":"لماذا شبّه التكاليف الشاقة بـ﴿الإصر﴾ المحمول؟","answer":"الإصر حمل ثقيل يقيد صاحبه، فصورت به العهود والأحكام الشاقة التي حملتها أمم سابقة وطلب المؤمنون تخفيفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص476، تحت «مناسبة المجاز للاستعارة في قوله تعالى «ولا تحمل علينا إصرا»»","url":""}]},{"id":"s2-1455","number":1455,"surah":2,"verses":[286],"references":[{"surah":2,"verses":[286]}],"verseLabel":"البقرة: 286","question":"لماذا تدرج الدعاء: ﴿واعف عنا واغفر لنا وارحمنا﴾؟","answer":"العفو يمحو أثر الذنب، والمغفرة تستره وتقي تبعته، والرحمة تمنح الخير فوق مجرد النجاة؛ فترقى من الإزالة إلى الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص477، تحت «وجه الجمع بين طلب العفو والمغفرة، وتقديمهما على طلب الرحمة»","url":""}]},{"id":"s2-1456","number":1456,"surah":2,"verses":[286],"references":[{"surah":2,"verses":[286]}],"verseLabel":"البقرة: 286","question":"كيف تفرع طلب النصر في قوله: ﴿أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ﴾ على إثبات ولاية الله؟","answer":"لما أقر المؤمنون بأن الله وحده وليهم وناصرهم، فرعوا على ذلك طلب النصر منه؛ فالولي يتولى الحفظ والتأييد، ولا يطلب النصر الحقيقي إلا ممن له القدرة والولاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص479، تحت «سر تفريع الدعاء الأخير بالفاء»","url":""}]},{"id":"s2-1457","number":1457,"surah":2,"verses":[286],"references":[{"surah":2,"verses":[286]},{"surah":65,"verses":[7]}],"verseLabel":"البقرة: 286، الطلاق: 7","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا﴾، وقوله تعالى في الطلاق: ﴿لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا مَا آتَاهَا﴾؟","answer":"جاءت آية البقرة في سياق تخفيف التكليف والمحاسبة عن المؤمنين بعد إقرارهم بالسمع والطاعة وطلبهم المغفرة، فناسب ﴿وسعها﴾. أما آية الطلاق فسبقتها النفقة بحسب السعة وضيق الرزق، فناسب ﴿ما آتاها﴾ ربطًا للتكليف بما أعطى الله الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص420، تحت عنوان «بيان التشابه اللفظي بين عبارتي ﴿وسعها﴾ و﴿ما آتاها﴾»","url":""}]},{"id":"s2-1458","number":1458,"surah":2,"verses":[286],"references":[{"surah":2,"verses":[286]}],"verseLabel":"البقرة: 286","question":"لماذا تكرر النداء ﴿رَبَّنَا﴾ في الدعوات السابقة، ثم لم يتكرر قبل قوله: ﴿وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا﴾؟","answer":"تكرر ﴿ربنا﴾ مع الكتل الدعائية المتعاطفة الأولى لإظهار مزيد الضراعة والتذلل، وتعليم تجديد النداء في كل حال، ثم حُذف قبل الأدعية الأخيرة لاتصالها بما قبلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص478، تحت «سر عدم تكرار النداء بالربوبية في قوله: «واعف عنا واغفر لنا وارحمنا»»","url":""}]},{"id":"s2-1459","number":1459,"surah":2,"verses":[286],"references":[{"surah":2,"verses":[286]}],"verseLabel":"البقرة: 286","question":"لماذا ختم الدعاء بقوله: ﴿فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ﴾، ولم يقل: «فانصرنا على الكافرين»؟","answer":"جاء طلب النصر بعد ﴿أنت مولانا﴾ لأن شأن المولى أن ينصر عبيده، ففرّع الدعاء بالفاء، وخُص القوم الكافرون لأن المطلوب الغلبة على جماعتهم ذات القوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص480، تحت «سر التعبير بالقوم الكافرين دون الاكتفاء بلفظ الكافرين»","url":""}]},{"id":"s2-1460","number":1460,"surah":2,"verses":[286],"references":[{"surah":2,"verses":[286]}],"verseLabel":"البقرة: 286","question":"ما مناسبة ختم السورة بقوله تعالى: ﴿لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا﴾ بعد كثرة الأحكام؟","answer":"جاء الاستئناف بعد حكاية تلقي المؤمنين للأوامر والنواهي ليقرر أن الله لا يحملهم فوق ما يطيقون، وأن دينه مبني على التيسير ورفع المشقة والحرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص472، تحت «دلالة الاستئناف في قوله تعالى: «لا يكلف الله نفسًا إلا وسعها»»","url":""}]},{"id":"s3-1","number":1,"surah":3,"verses":[1],"references":[{"surah":3,"verses":[1]}],"verseLabel":"آل عمران: 1","question":"لماذا افتُتحت سورة آل عمران بـ﴿الم﴾ كما افتتحت البقرة، مع اختلاف موضوع السورتين؟","answer":"تشترك السورة مع البقرة في استهلال السامع بالحروف المقطعة والتنبيه إلى مادة الكتاب المعجز، ثم تفترق عنها بما يلي المطلع: فآل عمران تبادر إلى تقرير التوحيد والقيومية وتنزيل الكتب، وهو مدخل حجاجها مع أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص495–497، تحت «براعة الاستهلال بالحروف المقطعة»","url":""}]},{"id":"s3-2","number":2,"surah":3,"verses":[2],"references":[{"surah":3,"verses":[2]}],"verseLabel":"آل عمران: 2","question":"لماذا جاء بعد الحروف المقطعة مباشرة ﴿الله لا إله إلا هو الحي القيوم﴾؟","answer":"جاء هذا التقرير عقب المطلع ليجعل أصل السورة توحيد الله وكمال حياته وقيوميته؛ ومن كان حيًّا قيومًا هو وحده مصدر الوحي والحاكم في شأن عيسى والكتب المنزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص497–499، تحت «جمال البدء باسم الله الأحسن وبوصفيه الحي القيوم»","url":""}]},{"id":"s3-3","number":3,"surah":3,"verses":[2],"references":[{"surah":3,"verses":[2]}],"verseLabel":"آل عمران: 2","question":"لماذا جُمع الاسمان ﴿الحي القيوم﴾ في افتتاح السورة؟","answer":"﴿الحي﴾ يدل على كمال الذات والحياة التي لا يلحقها نقص، و﴿القيوم﴾ على قيامه بنفسه وإقامته أمر خلقه؛ فاجتماعهما يجمع كمال الذات وكمال التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص497–498، تحت «جمال البدء باسم الله الأحسن وبوصفيه الحي القيوم»","url":""}]},{"id":"s3-4","number":4,"surah":3,"verses":[2],"references":[{"surah":2,"verses":[255]},{"surah":3,"verses":[2]}],"verseLabel":"آل عمران: 2؛ البقرة: 255","question":"لماذا وردت جملة ﴿الله لا إله إلا هو الحي القيوم﴾ في افتتاح آل عمران، بينما جاءت في وسط سورة البقرة في آية الكرسي؟","answer":"في البقرة جاءت ضمن سياق الإخبار العام عن صفات المولى سبحانه وإثبات كماله، أما في آل عمران فجاءت في صدر السورة لتقرير أصل التوحيد والرد على دعاوى النصارى في عيسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص499، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s3-5","number":5,"surah":3,"verses":[3],"references":[{"surah":3,"verses":[3]}],"verseLabel":"آل عمران: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿نزّل عليك الكتاب﴾ بالتشديد، ثم قال ﴿وأنزل التوراة والإنجيل﴾؟","answer":"التنزيل بالتشديد يلائم نزول القرآن منجّمًا متتابعًا، أما الإنزال في التوراة والإنجيل فيلحظ أصل إيتائهما وإنزالهما؛ فاختلاف الصيغة يراعي كيفية التنزيل ومقامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص504–505، تحت «الفرق بين صيغتي نزّل وأنزل»","url":""}]},{"id":"s3-6","number":6,"surah":3,"verses":[3],"references":[{"surah":3,"verses":[3]}],"verseLabel":"آل عمران: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿عليك﴾ في نزول القرآن، دون أن يقال: إليك؟","answer":"عُدّي الإنزال بـ﴿على﴾ للدلالة على نزوله من جهة العلو، ولتشريف الرسول وتكريمه؛ أما ﴿إلى﴾ فتناسب مرحلة التبليغ إلى الأمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص506، تحت «سر التعبير بحرف الاستعلاء دون حرف الغاية»","url":""}]},{"id":"s3-7","number":7,"surah":3,"verses":[3],"references":[{"surah":3,"verses":[3]}],"verseLabel":"آل عمران: 3","question":"لماذا سمّى القرآن هنا ﴿الكتاب﴾ ولم يقل: القرآن؟","answer":"اختير اسم ﴿الكتاب﴾ لما يحمله من دعوة أهل الكتاب إلى الإيمان به، وللإيماء إلى أنه الجامع لأصول الكتب السابقة والمهيمن عليها؛ فهو الكتاب الأحق بهذا الاسم في مقابل التوراة والإنجيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص507–508، تحت «فائدة التعبير بالكتاب دون القرآن»","url":""}]},{"id":"s3-8","number":8,"surah":3,"verses":[3],"references":[{"surah":3,"verses":[3]}],"verseLabel":"آل عمران: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿مصدقًا لما بين يديه﴾، وكيف يكون للكتاب يدان؟","answer":"هذه كناية مأخوذة من وجود الشيء أمام الإنسان وبين يديه؛ أي إن القرآن يوافق ما سبقه من الوحي الحق ويشهد لأصوله، لا أن للكتاب يدين حقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص510–511، تحت «بلاغة التعبير عن الماضي بقوله تعالى: بين يديه»","url":""}]},{"id":"s3-9","number":9,"surah":3,"verses":[3],"references":[{"surah":3,"verses":[3]}],"verseLabel":"آل عمران: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿من قبل﴾ بعد ذكر التوراة والإنجيل، مع أن سبقهما معلوم؟","answer":"ليست ﴿من قبل﴾ متعلقة بمجرد الإنزال المعلوم سبقه، بل تتعلق بكون التوراة والإنجيل هدى للناس من قبل نزول القرآن؛ فتقرر أن الهداية بالكتب أمر معهود سابق، وأن القرآن لم يكن أول كتاب منزل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص515–516، تحت «توجيه التعبير بذكر البديهي من الكلام»","url":""}]},{"id":"s3-10","number":10,"surah":3,"verses":[4],"references":[{"surah":3,"verses":[4]}],"verseLabel":"آل عمران: 4","question":"لماذا سُمّيت الكتب السابقة ﴿هدى للناس﴾، ثم أفرد ﴿الفرقان﴾ بالذكر؟","answer":"أُفرد ﴿الفرقان﴾ لأنه وصف لما يفرق بين الحق والباطل؛ ويشمل جنس الكتب السماوية، وقيل خُص به القرآن تعظيمًا لشأنه لأن فرقانه في الأحكام والتشريعات أشمل من فرقان الكتب السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص518–519، تحت «دلالة لفظ الفرقان في قوله تعالى: وأنزل الفرقان»","url":""}]},{"id":"s3-11","number":11,"surah":3,"verses":[4],"references":[{"surah":3,"verses":[4]}],"verseLabel":"آل عمران: 4","question":"ما سرّ التعبير في قوله تعالى في عقوبة المكذبين ﴿لهم عذاب شديد﴾ لا أليم أو عظيم؟","answer":"وُصف العذاب بالشديد لأن الشدة هنا تشمل كثرته كمًّا وكيفًا ودوامه الأبدي، بما يناسب كفرهم بآيات الله في الكتب السابقة والقرآن والمعجزات؛ بخلاف أوصاف العظيم أو الأليم أو المهين التي يراعى في كل منها وجه آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص521، تحت «نكتة وصف العذاب بالشديد دون غيره من أوصاف العذاب»","url":""}]},{"id":"s3-12","number":12,"surah":3,"verses":[4],"references":[{"surah":3,"verses":[4]}],"verseLabel":"آل عمران: 4","question":"لماذا ختم الآية بـ﴿والله عزيز ذو انتقام﴾؟","answer":"خُتمت الآية بذلك لأن إنزال العذاب يقتضي عزةً وغلبة لا تُقهر، وكونه ﴿ذو انتقام﴾ يدل على أن العقوبة واقعة على ذنب؛ فـ﴿العزيز﴾ يشير إلى تمام القدرة على العقاب، و﴿ذو انتقام﴾ إلى إيقاعه فعلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص521–522، تحت «سر ختم الآية بقوله: والله عزيز ذو انتقام»","url":""}]},{"id":"s3-13","number":13,"surah":3,"verses":[4],"references":[{"surah":3,"verses":[4]}],"verseLabel":"آل عمران: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿ذو انتقام﴾، دون أن يقال: منتقم؟","answer":"التعبير بـ﴿ذُو انْتِقَامٍ﴾ يجعل الانتقام وصفًا ثابتًا متمكنًا ويدل على القدرة عليه؛ وهو أقوى في مقام الوعيد من مجرد الإخبار بالفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص522، تحت «إيثار الوصف بـذو انتقام دون منتقم لأنه أبلغ في الدلالة»","url":""}]},{"id":"s3-14","number":14,"surah":3,"verses":[5],"references":[{"surah":3,"verses":[5]}],"verseLabel":"آل عمران: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يخفى عليه شيء في الأرض ولا في السماء﴾، وقدم الأرض على السماء؟","answer":"قُدمت الأرض للترقي من الأدنى إلى الأعلى، ولأنها موضع نظر المخاطبين وأعمالهم وكسبهم، وفي مقام الوعيد إيماء إلى علم الله بما اقترفوه فيها، ثم عطف الأبعد وهو السماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص527، تحت «سر تقديم الأرض على السماء»","url":""}]},{"id":"s3-15","number":15,"surah":3,"verses":[5],"references":[{"surah":3,"verses":[5]}],"verseLabel":"آل عمران: 5","question":"لماذا نكّر ﴿شيء﴾ في سياق نفي الخفاء؟","answer":"نُكرت ﴿شيء﴾ في سياق النفي لإفادة العموم؛ أي لا يخفى على الله أي شيء كليًا كان أو جزئيًا، وفي ذلك دلالة على كمال علمه وإحاطته.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص524–526، تحت «دلالة التنكير في سياق النفي»","url":""}]},{"id":"s3-16","number":16,"surah":3,"verses":[6],"references":[{"surah":3,"verses":[6]}],"verseLabel":"آل عمران: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿يصوركم في الأرحام كيف يشاء﴾، دون أن يقال: يخلقكم؟","answer":"اختير ﴿يصوركم﴾ لأنه أخص من مطلق الخلق؛ فهو جعل المخلوق على هيئة يتميز بها، مع تنوع الصور والصفات بمشيئة الله، وفي السياق رد على ألوهية عيسى لأنه من المصورين في الرحم، فكان مخلوقًا لا خالقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص528–531، تحت «نكتة التعبير بالتصوير والمراد شيء آخر»","url":""}]},{"id":"s3-18","number":18,"surah":3,"verses":[6],"references":[{"surah":3,"verses":[6]}],"verseLabel":"آل عمران: 6","question":"لماذا ختم آية التصوير بـ﴿لا إله إلا هو العزيز الحكيم﴾؟","answer":"العزة تثبت نفاذ القدرة، والحكمة تثبت أن هذا النفاذ موضوع في موضعه بلا عبث ولا ظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص532–533، تحت «بلاغة التذييل في قوله تعالى: لا إله إلا هو العزيز الحكيم»","url":""}]},{"id":"s3-19","number":19,"surah":3,"verses":[7],"references":[{"surah":3,"verses":[7]}],"verseLabel":"آل عمران: 7","question":"لماذا قسّم آيات الكتاب إلى محكمات ومتشابهات؟","answer":"قُسمت الآيات بحسب دلالتها إلى محكمات واضحات هن أصل الكتاب ومرجعه، ومتشابهات محتملات تُرد إلى المحكم؛ ثم بيّن السياق اختلاف المتلقين، فالزائغ يتبع المتشابه للفتنة، والراسخ يؤمن بالجميع ويرده إلى أصله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص538–544، تحت «توجيه الاستعارة في تسمية المحكم والمتشابه»","url":""}]},{"id":"s3-20","number":20,"surah":3,"verses":[7],"references":[{"surah":3,"verses":[7]}],"verseLabel":"آل عمران: 7","question":"ما سرّ التعبير في قوله تعالى عن المحكمات ﴿هن أم الكتاب﴾ بإفراد ﴿أم﴾؟","answer":"وُصفت المحكمات بأنها ﴿أم الكتاب﴾ لأن «الأم» هي الأصل الجامع الذي يُضم إليه غيره ويُرجع إليه؛ فالمحكمات أصل فهم المتشابه ومرجعه، واللفظ يصور اجتماع الفروع إلى أصلها الجامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص542، تحت «سر إفراد أم دون جمعها في قوله: آيات محكمات هن أم الكتاب»","url":""}]},{"id":"s3-21","number":21,"surah":3,"verses":[7],"references":[{"surah":3,"verses":[7]}],"verseLabel":"آل عمران: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿فأما الذين في قلوبهم زيغ﴾، فجعل الزيغ داخل القلوب؟","answer":"نُسب الزيغ إلى القلوب لأنها موضع القصد والهوى؛ فالمذكور ميل متعمد عن الحق إلى الباطل، ومن هذا الميل الباطن يصدر اتباع المتشابه وترك المحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص544، تحت «سر اختيار مفردة الزيغ دون الميل»","url":""}]},{"id":"s3-22","number":22,"surah":3,"verses":[7],"references":[{"surah":3,"verses":[7]}],"verseLabel":"آل عمران: 7","question":"لماذا قدّم ابتغاء الفتنة على ابتغاء التأويل؟","answer":"لأن إرادة الفتنة هي الدافع أولًا، ثم يُتخذ طلب التأويل وسيلةً لها؛ فرتب النظم الباعث قبل الأداة وكشف فساد القصد قبل فساد المسلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص545–546، تحت «نكتة عطف قوله تعالى: وابتغاء تأويله على ابتغاء الفتنة»","url":""}]},{"id":"s3-23","number":23,"surah":3,"verses":[7],"references":[{"surah":3,"verses":[7]}],"verseLabel":"آل عمران: 7","question":"كيف يوصف القرآن كله بأنه محكم، وكله متشابه، ثم يقال إن منه محكمًا ومتشابهًا؟","answer":"إحكام القرآن كله يعني إتقانه وانتفاء التناقض عنه، وتشابهه كله يعني تصديق بعضه بعضًا وتماثله في الحق والحسن؛ أما التقسيم هنا فبين آيات واضحة الأصل وأخرى تحتمل فتُرد إلى المحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص543، تحت «نكتة وصف القرآن كله بالمحكم والمتشابه وبعضه كذلك».","url":""}]},{"id":"s3-24","number":24,"surah":3,"verses":[7],"references":[{"surah":3,"verses":[7]}],"verseLabel":"آل عمران: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿والراسخون في العلم﴾، دون أن يقال: والعلماء؟","answer":"اختير ﴿الراسخون﴾ استعارةً من رسوخ الشيء الثقيل في الأرض؛ أي الثابتون المتمكنون في العلم الذين لا تضللهم الشبه ويعرفون مواقع التأويل، وهو أبلغ من مجرد وصفهم بالعلماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص548، تحت «بلاغة الاستعارة في قوله: والراسخون في العلم»","url":""}]},{"id":"s3-25","number":25,"surah":3,"verses":[7],"references":[{"surah":3,"verses":[7]}],"verseLabel":"آل عمران: 7","question":"ما دلالة قول الراسخين: ﴿كُلٌّ مِنْ عِنْدِ رَبِّنَا﴾، وعدم اتباعهم المتشابه طلبًا للفتنة؟","answer":"يؤمن الراسخون بالمحكم والمتشابه جميعًا، ويعلمون من المتشابه ما يمكن علمه، ولا يدعون معرفة ما استأثر الله بعلمه كوقت الساعة. فقولهم ﴿كل من عند ربنا﴾ يجمع علمًا فيما أمكن علمه وتسليمًا فيما خفي عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص548، تحت عنوان «فائدة الوصف بالرسوخ»","url":""}]},{"id":"s3-26","number":26,"surah":3,"verses":[7],"references":[{"surah":3,"verses":[7]}],"verseLabel":"آل عمران: 7","question":"ما مناسبة ختم آية المحكم والمتشابه بقوله تعالى: ﴿وما يذكر إلا أولو الألباب﴾؟","answer":"فيه مدح للراسخين في العلم بجودة الذهن وحسن النظر، وإشارة إلى أن تجرد العقل من الشوائب يعين على حسن الفهم؛ فأولو الألباب أصحاب العقول الخالصة، يقفون عند المتشابه ويعملون بالمحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص549–550، تحت عنوان «مناسبة التذييل في قوله: ﴿وما يذكر إلا أولو الألباب﴾»","url":""}]},{"id":"s3-773","number":773,"surah":3,"verses":[7],"references":[{"surah":3,"verses":[7]}],"verseLabel":"آل عمران: 7","question":"ما المراد بالحصر في قوله تعالى: ﴿وما يذكر إلا أولو الألباب﴾؟","answer":"المراد كمال التذكر والانتفاع به؛ فلا يتذكر حق التذكر إلا أولو الألباب، وليس المقصود نفي أصل التذكر عن غيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص550، تحت عنوان «توجيه الحصر في قوله تعالى: ﴿وما يذكر إلا أولو الألباب﴾»","url":""}]},{"id":"s3-27","number":27,"surah":3,"verses":[8],"references":[{"surah":3,"verses":[8]}],"verseLabel":"آل عمران: 8","question":"لماذا دعا الراسخون ﴿ربنا لا تزغ قلوبنا﴾ بعد أن وصف الله أهل الزيغ؟","answer":"لما ذُكر أهل الزيغ والراسخون وظهر الفرق بين الحالين، عُلّم المؤمنون أن يسألوا ربهم ألا يجعلهم من الطائفة المذمومة؛ فالراسخ لا يأمن على قلبه، بل يفتقر إلى حفظ الله بعد الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص553–554، تحت «سر البدء بالدعاء بالحفظ من الزيغ على طلب الهبة».","url":""}]},{"id":"s3-28","number":28,"surah":3,"verses":[8],"references":[{"surah":3,"verses":[8]}],"verseLabel":"آل عمران: 8","question":"ما سرّ قول الراسخين: ﴿لَا تُزِغْ قُلُوبَنَا﴾ دون «لا تجعلنا زائغين»؟","answer":"خصوا القلوب لأن القلب أصل الذات ومبدأ توجيهها؛ فإذا زاغ القلب زاغ الإنسان كله، فنفي الزيغ عنه أبلغ من وصف الشخص إجمالًا بأنه غير زائغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص553، تحت «علة إضافة الزيغ إلى القلوب دون الهداية»","url":""}]},{"id":"s3-29","number":29,"surah":3,"verses":[8],"references":[{"surah":3,"verses":[8]}],"verseLabel":"آل عمران: 8","question":"ما سرّ قولهم: ﴿هَبْ لَنَا﴾ دون «أعطنا»؟","answer":"الهبة عطاء تفضّل لا يقابله عوض ولا استحقاق؛ فاختيرت اعترافًا بأن الثبات والرحمة محض فضل من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص554–555، تحت «فائدة إيثار الدعاء بلفظ الهبة في قوله: وهب لنا من لدنك رحمة»","url":""}]},{"id":"s3-30","number":30,"surah":3,"verses":[8],"references":[{"surah":3,"verses":[8]}],"verseLabel":"آل عمران: 8","question":"ما سرّ قولهم: ﴿مِنْ لَدُنْكَ رَحْمَةً﴾ دون «من عندك»؟","answer":"اختيرت ﴿لدن﴾ لأنها أخص من «عند» وتدل على ابتداء الغاية؛ فكأن الداعين يستوثقون تحقق الرحمة من مبدئها عند الله إلى تمام حصولها لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص555، تحت «إيثار التعبير بقوله: من لدنك دون من عندك»","url":""}]},{"id":"s3-31","number":31,"surah":3,"verses":[8],"references":[{"surah":3,"verses":[8]}],"verseLabel":"آل عمران: 8","question":"لماذا خُتم دعاء الراسخين بقوله تعالى: ﴿إنك أنت الوهاب﴾؟","answer":"جاء الختام تعليلًا لطلبهم ﴿هب لنا﴾؛ فهم يسألون الله الهبة لكونه الوهاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص556، تحت عنوان «ختمت الآية بقوله (إنك أنت الوهاب) لأنه كالتعليل للسابق»","url":""}]},{"id":"s3-774","number":774,"surah":3,"verses":[8],"references":[{"surah":3,"verses":[8]}],"verseLabel":"آل عمران: 8","question":"ما دلالة القصر في قوله تعالى: ﴿إنك أنت الوهاب﴾؟","answer":"يدل على كمال صفة الهبة لله؛ فهبات الخلق قليلة بالنسبة إلى فضله، ولا يعجزه إعطاء شيء. وفي الجملة تأكيد بـ«إن» واسمية الجملة وطريق القصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص556، تحت عنوان «بلاغة القصر في قوله: ﴿إنك أنت الوهاب﴾»","url":""}]},{"id":"s3-775","number":775,"surah":3,"verses":[8],"references":[{"surah":3,"verses":[8]}],"verseLabel":"آل عمران: 8","question":"ما دلالة صيغة المبالغة ﴿الوهاب﴾ في دعاء الراسخين؟","answer":"تشير إلى سعة كرم الله ورحمته وغاية جوده؛ فما يطلبه العبد، وإن عظم في نفسه، يسير بالنسبة إلى كمال عطاء الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص557، تحت عنوان «دلالة صيغة المبالغة في قوله: ﴿إنك أنت الوهاب﴾»","url":""}]},{"id":"s3-32","number":32,"surah":3,"verses":[9],"references":[{"surah":3,"verses":[9]}],"verseLabel":"آل عمران: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿جامع الناس ليوم لا ريب فيه﴾، دون أن يقال: في يوم؟","answer":"اللام متعلقة بغاية الجمع، أي جامع الناس للجزاء والحساب في يوم لا ريب فيه؛ فحذف المضاف لوضوحه، ولم يقل «في يوم» لأن المقصود إبراز غاية الجمع لا مجرد ظرفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص560–561، تحت «دلالة الإيجاز بحذف المضاف في قوله: جامع الناس ليوم»","url":""}]},{"id":"s3-33","number":33,"surah":3,"verses":[9],"references":[{"surah":3,"verses":[9]}],"verseLabel":"آل عمران: 9","question":"لماذا عُلّل الجمع للقيامة بقوله ﴿إن الله لا يخلف الميعاد﴾؟","answer":"الخاتمة تعلل اليقين بما قبلها؛ فالوعد صادر ممن يستحيل في حقه الخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص562، تحت «براعة الفاصلة في قوله: إن الله لا يخلف الميعاد»","url":""}]},{"id":"s3-34","number":34,"surah":3,"verses":[10],"references":[{"surah":3,"verses":[10]}],"verseLabel":"آل عمران: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿لن تغني عنهم أموالهم ولا أولادهم من الله شيئًا﴾ فقدم الأموال؟","answer":"قُدمت الأموال لأنها أبلغ في باب المدافعة والتقرب والافتتان، وهي أقرب ما يفزع إليه الإنسان لدفع الشدائد؛ ثم عطف الأولاد، فإذا لم يغن الأقوى في هذا الباب فما بعده أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص573–574، تحت «سر تقديم الأموال على الأولاد في السياق»","url":""}]},{"id":"s3-35","number":35,"surah":3,"verses":[10],"references":[{"surah":3,"verses":[10]}],"verseLabel":"آل عمران: 10","question":"لماذا شبّه الكافرين بأنهم ﴿وقود النار﴾ لا أصحاب النار فقط؟","answer":"التعبير أبلغ من مجرد دخول النار؛ إذ يصوّرهم مادة تتقد بها النار، جزاءً لمن أوقدوا أسباب الكفر والفتنة في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص577–578، تحت «سر العدول عن حطب النار إلى وقود النار»","url":""}]},{"id":"s3-36","number":36,"surah":3,"verses":[10,116],"references":[{"surah":3,"verses":[10,116]}],"verseLabel":"آل عمران: 10؛ آل عمران: 116","question":"لماذا انتهت الآية 10 بـ﴿وأولئك هم وقود النار﴾، بينما انتهت الآية 116 بعد الصدر نفسه بـ﴿وأولئك أصحاب النار هم فيها خالدون﴾؟","answer":"تدرج السياق في الوعيد: بدأ بذكر شدة العذاب، ثم صورهم وقودًا للنار، ثم صعد التهديد إلى صحبتها والخلود فيها؛ وناسب ﴿وقود النار﴾ حال من يوقدون الفتنة في الدنيا، وناسب ﴿أصحاب النار هم فيها خالدون﴾ تقرير ملازمتهم لها ودوامهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص578–581، تحت «توجيه المتشابه اللفظي».","url":""}]},{"id":"s3-37","number":37,"surah":3,"verses":[11],"references":[{"surah":3,"verses":[11]},{"surah":8,"verses":[52]}],"verseLabel":"آل عمران: 11؛ الأنفال: 52","question":"لماذا شُبّه حالهم بـ﴿دأب آل فرعون والذين من قبلهم﴾؟","answer":"في آل عمران: 11: شبهوا بآل فرعون ومن قبلهم في دأبهم الملازم: الاجتهاد والدوام على التكذيب والكفر، ومن ثم استحقاق العذاب؛ فكما صنع أولئك بآيات الله صنع هؤلاء.\n\nفي الأنفال: 52: شُبهت عادتهم بعادة آل فرعون ومن قبلهم في الكفر والتكذيب، لتقرير سنة واحدة: تمكين يتبعه أخذ بسبب الذنب حين يصر أهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص587، تحت «وجه الشبه وأثره في الكلام».","url":""}]},{"id":"s3-38","number":38,"surah":3,"verses":[11],"references":[{"surah":3,"verses":[11]}],"verseLabel":"آل عمران: 11","question":"ما الصورة التي يبرزها التعبير بالأخذ في قوله تعالى: ﴿فأخذهم الله بذنوبهم﴾؟","answer":"يصور شدة العقوبة بأخذ الأسير الذي لا يستطيع الفكاك من آسره ولا التخلص منه؛ فهو أخذ انتقام في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص590، تحت عنوان «نكتة التعبير بالأخذ في قوله: ﴿فأخذهم الله﴾»","url":""}]},{"id":"s3-776","number":776,"surah":3,"verses":[11],"references":[{"surah":3,"verses":[11]}],"verseLabel":"آل عمران: 11","question":"ما دلالة الباء في قوله تعالى: ﴿فأخذهم الله بذنوبهم﴾؟","answer":"تحتمل السببية، أي أخذهم بسبب ذنوبهم، وتحتمل الملابسة والمصاحبة، أي أخذهم متلبسين بها لم يتوبوا منها؛ وفي الوجهين بيان عدل الله وأنهم استحقوا العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص591، تحت عنوان «دلالة الباء في قوله: ﴿بذنوبهم﴾»","url":""}]},{"id":"s3-39","number":39,"surah":3,"verses":[11],"references":[{"surah":3,"verses":[11]}],"verseLabel":"آل عمران: 11","question":"لماذا ختم بقوله ﴿والله شديد العقاب﴾ بعد ذكر آل فرعون؟","answer":"الخاتمة تحول الخبر إلى وعيد حاضر، وتبين أن الأخذ المذكور أثر من آثار شدة العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص592، تحت «بلاغة تذييل الآية وعلاقته بالسياق»","url":""}]},{"id":"s3-40","number":40,"surah":3,"verses":[11],"references":[{"surah":3,"verses":[11]}],"verseLabel":"آل عمران: 11","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران عن آل فرعون ﴿كذبوا بآياتنا﴾، وقوله تعالى في الأنفال مرة ﴿كفروا بآيات الله﴾ ومرة ﴿كذبوا بآيات ربهم﴾؟","answer":"﴿كذبوا﴾ تصف رد الآيات والرسل بالإنكار، أما ﴿كفروا﴾ فأوسع وتشمل الجحود وما انضم إليه من محاربة؛ ونُوّعت إضافة الآيات إلى ضمير العظمة واسم الجلالة والرب لتغليظ جرمهم: فهي آيات الله وربهم الذي رباهم بنعمه، ومع ذلك كذبوا وكفروا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص330–331، تحت «بلاغة التشابه اللفظي بين آية آل عمران وآيتي الأنفال».","url":""}]},{"id":"s3-41","number":41,"surah":3,"verses":[12],"references":[{"surah":3,"verses":[12]}],"verseLabel":"آل عمران: 12","question":"ما دلالة الإخبار عن الكافرين بصيغة الاستقبال: ﴿سَتُغْلَبُونَ وَتُحْشَرُونَ إِلَى جَهَنَّمَ﴾؟","answer":"أخبر بالغلبة قبل وقوعها وعيدًا وإعجازًا غيبيًا، ودلت السين على قرب تحققها؛ فجمع لهم بين هزيمة الدنيا في ﴿ستغلبون﴾ وعذاب الآخرة في ﴿تحشرون إلى جهنم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص600–601، تحت «دلالة حرف السين في قوله: ﴿ستغلبون﴾».","url":""}]},{"id":"s3-42","number":42,"surah":3,"verses":[12],"references":[{"surah":3,"verses":[12]}],"verseLabel":"آل عمران: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿وبئس المهاد﴾ فوصف جهنم بالمهاد الذي يُوطأ للنوم؟","answer":"سمّى النار مهادًا على سبيل التهكم؛ فالمهاد موضع الراحة، أما هذا المهاد فغاية العذاب، وفي التضاد زيادة تهويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص602–606، تحت «دلالة رأس الآية ﴿وبئس المهاد﴾ على المراد».","url":""}]},{"id":"s3-43","number":43,"surah":3,"verses":[13],"references":[{"surah":3,"verses":[13]}],"verseLabel":"آل عمران: 13","question":"لماذا جعل لقاء الفئتين ﴿آية﴾ للمشاهدين؟","answer":"كان لقاء الفئتين آية ظاهرة لأن الفئة المؤمنة القليلة غلبت الفئة الكافرة الأكثر عددًا وعدة بتأييد الله؛ فصار المشهد برهانًا محسوسًا على صدق وعد غلبة الكافرين ونصر المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص606، تحت «دلالة تنكير لفظ ﴿آية﴾».","url":""}]},{"id":"s3-44","number":44,"surah":3,"verses":[13],"references":[{"surah":3,"verses":[13]}],"verseLabel":"آل عمران: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿فئة تقاتل في سبيل الله وأخرى كافرة﴾، فذكر غاية الأولى ووصف الثانية؟","answer":"في الآية احتباك؛ ذكر للأولى أنها تقاتل في سبيل الله وحذف «مؤمنة» لدلالة ﴿كافرة﴾، وذكر كفر الثانية وحذف أنها تقاتل في سبيل الطاغوت لدلالة مقابله، فاستوفى الوصف بأوجز عبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص607–608، تحت «بلاغة الاحتباك في وصف الفئتين».","url":""}]},{"id":"s3-45","number":45,"surah":3,"verses":[13],"references":[{"surah":3,"verses":[13]}],"verseLabel":"آل عمران: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿يرونهم مثليهم رأي العين﴾؟ ومن الذي رأى مَن؟","answer":"المعتمد في السياق أن المشركين رأوا المسلمين مثلي عدد المشركين، ورؤية ﴿رأي العين﴾ بصرية معاينة لا ظنًا؛ فكان التكثير سببًا لهلعهم وهزيمتهم، مع وجود احتمال تفسيري آخر في مرجع الضمير.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص608–609، تحت «التوفيق بين قوله: ﴿ويقللكم في أعينهم﴾ وقوله: ﴿يرونهم مثليهم﴾».","url":""}]},{"id":"s3-46","number":46,"surah":3,"verses":[13],"references":[{"surah":3,"verses":[13]}],"verseLabel":"آل عمران: 13","question":"لماذا ختم العبرة بـ﴿إن في ذلك لعبرة لأولي الأبصار﴾ لا أولي الألباب؟","answer":"اختير ﴿أولو الأبصار﴾ لأن أحداث بدر شوهدت بالأعين فكان أهل المشاهدة أبلغ اعتبارًا، وللتناسب مع ﴿يرونهم﴾ في الآية، مع إيماء اللفظ إلى البصيرة التي ترى بنور القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص611، تحت «اختيار ﴿الأبصار﴾ بدل (الألباب) من بلاغة الخطاب».","url":""}]},{"id":"s3-47","number":47,"surah":3,"verses":[14],"references":[{"surah":3,"verses":[14]}],"verseLabel":"آل عمران: 14","question":"لماذا بُني الفعل للمجهول في ﴿زُيّن للناس حب الشهوات﴾؟","answer":"بُني ﴿زُيّن﴾ للمجهول لأن جهة التزيين تحتمل خلق الله وإيجاده للميل وتهيئته للانتفاع، وتحتمل وسوسة الشيطان وخديعته في التحصيل المحرم؛ فحذف الفاعل يستوعب الجهتين، مع الإيماء إلى رسوخ هذا الميل في الطبيعة الإنسانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص618–619، تحت «نكتة بناء الفعل ﴿زُيّن﴾ للمفعول».","url":""}]},{"id":"s3-48","number":48,"surah":3,"verses":[14],"references":[{"surah":3,"verses":[14]}],"verseLabel":"آل عمران: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿حب الشهوات﴾ لا الشهوات نفسها؟","answer":"لأن تزيين المشتهيات يفضي إلى حبها، فقيل ﴿حب الشهوات﴾ إيجازًا عن «زينت لهم الشهوات فأحبوها»؛ وفي إطلاق الشهوات على المشتهيات مبالغة في شدة التعلق والحرص عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص620–621، تحت «بلاغة الإيجاز في قوله: ﴿زُيّن للناس حب الشهوات﴾».","url":""}]},{"id":"s3-49","number":49,"surah":3,"verses":[14],"references":[{"surah":3,"verses":[14]}],"verseLabel":"آل عمران: 14","question":"لماذا بدأ تعداد الشهوات بالنساء ثم البنين؟","answer":"قدمت النساء لأن التعلق بهن والالتذاذ بهن أشد، وهو ميل فطري؛ ثم ذكر البنون لأنهم ثمرة ذلك الحب وذريعة إلى الإنجاب والتكثير، فانتقل الترتيب من أصل الميل إلى ثمرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص622–623، تحت «نكتة ترتيب المشتهيات في الآية».","url":""}]},{"id":"s3-50","number":50,"surah":3,"verses":[14],"references":[{"surah":3,"verses":[14]}],"verseLabel":"آل عمران: 14","question":"لماذا ذُكر البنون دون البنات؟","answer":"الآية تصف ما كان محل التفاخر والقوة في عرف المخاطبين، وكان البنون عندهم عنوان العزوة والنصرة؛ فهي تكشف شهوة الواقع ولا تنتقص قدر البنات.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص624، تحت «نكتة الاقتصار على ذكر البنين دون البنات في الآية».","url":""}]},{"id":"s3-51","number":51,"surah":3,"verses":[14],"references":[{"surah":3,"verses":[14]}],"verseLabel":"آل عمران: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿القناطير المقنطرة﴾ فكرر المادة؟","answer":"اشتق الوصف من الاسم للمبالغة، كأنه مال بلغ الغاية في التكثير والتكديس، فيجسّم فتنة الثروة في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص624–625، تحت «براعة الكناية في قوله: ﴿والقناطير المقنطرة﴾».","url":""}]},{"id":"s3-52","number":52,"surah":3,"verses":[14],"references":[{"surah":3,"verses":[14]}],"verseLabel":"آل عمران: 14","question":"لماذا خُص الذهب والفضة والخيل والأنعام والحرث في تعداد المتاع؟","answer":"لأنها جمعت أصول الثروة التي عرفها المخاطبون: النقد، ومظهر القوة والزينة، والحيوان، والأرض المنتجة؛ فاستوعب التعداد وجوه التملك والانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص626–627، تحت «براعة أسلوب التقسيم في تعداد المشتهيات».","url":""}]},{"id":"s3-53","number":53,"surah":3,"verses":[14],"references":[{"surah":3,"verses":[14]}],"verseLabel":"آل عمران: 14","question":"لماذا ختم التعداد بـ﴿ذلك متاع الحياة الدنيا والله عنده حسن المآب﴾؟","answer":"أشار بـ﴿ذلك﴾ إلى المذكورات مع دلالة البعد على تحقير التعلق بها، وقصرها على متاع الحياة الدنيا الزائل، ثم قابلها بقوله ﴿والله عنده حسن المآب﴾ ليصرف النظر إلى المرجع الأبقى عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص627، تحت «سر الاقتصار على وصف هذه المشتهيات بكونها متاع الحياة الدنيا».","url":""}]},{"id":"s3-54","number":54,"surah":3,"verses":[15],"references":[{"surah":3,"verses":[15]}],"verseLabel":"آل عمران: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿قل أؤنبئكم بخير من ذلكم﴾ على صورة سؤال لا تقرير؟","answer":"جاء الاستفهام للتشويق؛ فبعد عرض شهوات الدنيا يوقظ السامع إلى موازنة ينتظر جوابها، فيكون تلقي نعيم الآخرة أشد أثرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص633–634، تحت «دلالة الاستفهام في قوله تعالى: ﴿قل أؤنبئكم بخير من ذلكم﴾».","url":""}]},{"id":"s3-56","number":56,"surah":3,"verses":[15],"references":[{"surah":3,"verses":[15]}],"verseLabel":"آل عمران: 15","question":"لماذا ختم بـ﴿والله بصير بالعباد﴾ لا عليم؟","answer":"اختير ﴿بصير بالعباد﴾ لإظهار إحاطة الله بأحوالهم وأعمالهم الظاهرة، وهو متضمن معنى العلم؛ فيبصر تقواهم ومقدار مشقتهم في العبادة ويجازيهم عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص640–641، تحت «دلالة التذييل في قوله تعالى: ﴿والله بصير بالعباد﴾».","url":""}]},{"id":"s3-57","number":57,"surah":3,"verses":[16],"references":[{"surah":3,"verses":[16]}],"verseLabel":"آل عمران: 16","question":"ما سرّ وصف المتقين بالموصول في قوله تعالى: ﴿الَّذِينَ يَقُولُونَ رَبَّنَا إِنَّنَا آمَنَّا﴾؟","answer":"جاء وصف المتقين بالموصول ﴿الَّذِينَ يَقُولُونَ﴾ ليجعل دعاءهم وإقرارهم بالإيمان صلة كاشفة عن حالهم، ويبين أن رجاء المغفرة والوقاية من النار من صفاتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص645، تحت «سر التعبير بالاسم الموصول ومجيء صلته مضارعًا».","url":""}]},{"id":"s3-58","number":58,"surah":3,"verses":[16],"references":[{"surah":3,"verses":[16]}],"verseLabel":"آل عمران: 16","question":"لماذا قدّموا الإيمان على طلب المغفرة والوقاية من النار؟","answer":"قدموا الإيمان لأنه أصل الاستحقاق والرجاء، ثم بنوا عليه سؤال إزالة الذنب ودفع أثره؛ فالدعاء مرتب من السبب إلى الثمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص646، تحت «بلاغة التفريع وخروج لفظ الأمر إلى معنى الدعاء».","url":""}]},{"id":"s3-59","number":59,"surah":3,"verses":[17],"references":[{"surah":3,"verses":[17]}],"verseLabel":"آل عمران: 17","question":"لماذا جاءت الصفات: ﴿الصابرين والصادقين والقانتين والمنفقين والمستغفرين بالأسحار﴾ بهذا الترتيب؟","answer":"بدأ بالصبر لأنه يحمل على مشاق الطاعة، ثم الصدق المصحح للظاهر والباطن، ثم القنوت وهو دوام الطاعة، فالإنفاق أثر عملي، وخُتم بالاستغفار في السحر جمعًا للعبادة والخضوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص649–650، تحت «توجيه الصفات المذكورة دون غيرها بالذكر».","url":""}]},{"id":"s3-60","number":60,"surah":3,"verses":[17],"references":[{"surah":3,"verses":[17]}],"verseLabel":"آل عمران: 17","question":"لماذا خُص وقت الأسحار بالاستغفار؟","answer":"لأنه وقت سكون وخلوص، يعقب قيام الليل وتنكسر فيه النفس بعيدًا عن الرياء؛ فكان الاستغفار فيه أمارة صدق العبادة لا مجرد قول باللسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص649، تحت «نكتة تقييد الاستغفار بوقت دون غيره من الصفات»","url":""}]},{"id":"s3-61","number":61,"surah":3,"verses":[18],"references":[{"surah":3,"verses":[18]}],"verseLabel":"آل عمران: 18","question":"لماذا بدأ الله الشهادة بنفسه ثم الملائكة ثم أولي العلم؟","answer":"بدأ بأعلى شهادة وأقطعها، ثم ثنّى بشهادة عالم الغيب، ثم أهل العلم من البشر؛ فترتب الشهود بحسب المنزلة وقوة المعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص655–656، تحت «سر عطف الملائكة وأولي العلم في الشهادة على لفظ الجلالة».","url":""}]},{"id":"s3-62","number":62,"surah":3,"verses":[18],"references":[{"surah":3,"verses":[18]}],"verseLabel":"آل عمران: 18","question":"لماذا كرر ﴿لا إله إلا هو﴾ مرتين في آية واحدة؟","answer":"كررت الجملة لأن الأولى تقرر التوحيد في مرتبة الشهادة والعلم، والثانية تقرره في مرتبة القسط والحكم والفعل؛ فهي تأكيد بعد إقامة الحجة وتمهيد لوصفه بـ﴿العزيز الحكيم﴾، لا إعادة خالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص659–660، تحت «أوجه تكرار قوله: ﴿لا إله إلا هو﴾ في الآية».","url":""}]},{"id":"s3-63","number":63,"surah":3,"verses":[18],"references":[{"surah":3,"verses":[18]}],"verseLabel":"آل عمران: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿قائمًا بالقسط﴾ بالإفراد مع تعدد المذكورين؟","answer":"أُفرد ﴿قائمًا﴾ ليفهم أنه حال كل واحد من المذكورين منفردًا لا حال المجموع بقيد الجمع، أو لأنه حال من اسم الجلالة فيدل على تفرد الله بالقيام بالقسط؛ وسوغ الإفراد عدم اللبس.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص657، تحت «سر إفراد لفظ القيام في قوله: ﴿قائمًا﴾ دون جمعه».","url":""}]},{"id":"s3-64","number":64,"surah":3,"verses":[18],"references":[{"surah":3,"verses":[18]}],"verseLabel":"آل عمران: 18","question":"لماذا اختار ﴿القسط﴾ ولم يقل: العدل؟","answer":"اختير ﴿القسط﴾ لأنه أدق في معنى التقسيم الموزون وإعطاء كل مخلوق ما يلائم حاجته ومقداره، وهو واقع في تكوين العوالم كلها؛ أما العدل فأعم ويغلب استعماله في شؤون الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص658–659، تحت «نكتة استعمال لفظ ﴿بالقسط﴾ دون غيره من الألفاظ».","url":""}]},{"id":"s3-65","number":65,"surah":3,"verses":[18],"references":[{"surah":3,"verses":[18]}],"verseLabel":"آل عمران: 18","question":"لماذا ختمت آية الشهادة بـ﴿العزيز الحكيم﴾؟","answer":"العزة تثبت نفاذ القدرة، والحكمة تثبت أن هذا النفاذ موضوع في موضعه بلا عبث ولا ظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص660، تحت «بلاغة قرن وصف العزيز بالحكيم وتقديمه عليه».","url":""}]},{"id":"s3-66","number":66,"surah":3,"verses":[19],"references":[{"surah":3,"verses":[19]}],"verseLabel":"آل عمران: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الدين عند الله الإسلام﴾ بالتعريف والقصر؟","answer":"عُرّف الطرفان ليفيد التركيب القصر: لا دين مقبولًا عند الله إلا الإسلام، وأكدت ﴿إن﴾ هذا الحكم، وقدّم ﴿عند الله﴾ لبيان أن الاعتبار والقبول عنده لا بمجرد أعراف الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص662–663، تحت «القصر والحصر والتقديم في قوله تعالى: ﴿إن الدين عند الله الإسلام﴾».","url":""}]},{"id":"s3-67","number":67,"surah":3,"verses":[19],"references":[{"surah":3,"verses":[19]}],"verseLabel":"آل عمران: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿وما اختلف الذين أوتوا الكتاب إلا من بعد ما جاءهم العلم﴾؟","answer":"جيء بالاستثناء لإثبات أن اختلاف أهل الكتاب لم يقع عن جهل، بل بعد أن علموا الحق علمًا يقينيًا وقامت عليهم الحجج والآيات؛ فانتفى عذرهم واشتد توبيخهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص665–666، تحت «سر استعمال الاستثناء المفرغ في أسلوب الحصر».","url":""}]},{"id":"s3-68","number":68,"surah":3,"verses":[19],"references":[{"surah":3,"verses":[19]}],"verseLabel":"آل عمران: 19","question":"لماذا علّل اختلافهم بالبغي بينهم؟","answer":"ليبين أن الحجة لم تكن ناقصة، وإنما حملهم الحسد وطلب الرياسة على مخالفة ما علموه؛ فمصدر الفرقة أخلاقي إرادي لا غموض الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص668، تحت «أثر معنى قوله: ﴿بغيًا بينهم﴾ في إعرابها».","url":""}]},{"id":"s3-69","number":69,"surah":3,"verses":[20],"references":[{"surah":3,"verses":[20]}],"verseLabel":"آل عمران: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن حاجوك فقل أسلمت وجهي لله﴾ فخص الوجه؟","answer":"خُص الوجه لأنه أشرف الأعضاء الظاهرة ومظهر القوى والحواس وموضع التوجه والخضوع في العبادة، فعُبر به عن الذات كلها؛ فإسلام الوجه لله إعلان لإخلاص النفس والدين له.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص674–675، تحت «المجاز في قوله تعالى: ﴿أسلمت وجهي لله ومن اتبعن﴾».","url":""}]},{"id":"s3-70","number":70,"surah":3,"verses":[20],"references":[{"surah":3,"verses":[20]}],"verseLabel":"آل عمران: 20","question":"لماذا عبّر بالماضي ﴿أسلمت﴾ لا بالمضارع: أُسلم؟","answer":"عبر بالماضي ﴿أسلمت﴾ لأن إسلام النبي ﷺ أمر متحقق ثابت يعلنه جوابًا للمحاجين، لا فعلًا يستأنفه الآن أو يعد به مستقبلًا؛ فالماضي أدل على الرسوخ والإنجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص675–676، تحت «نكتة إيثار صيغة الماضي في قوله: ﴿أأسلمتم﴾».","url":""}]},{"id":"s3-71","number":71,"surah":3,"verses":[20],"references":[{"surah":3,"verses":[20]}],"verseLabel":"آل عمران: 20","question":"ما دلالة توجيه السؤال إليهم بقوله تعالى: ﴿أَأَسْلَمْتُمْ﴾؟","answer":"الاستفهام في ﴿أأسلمتم﴾ ليس طلبًا للعلم، بل إنكار وتوبيخ يحمل المخاطب على مواجهة تناقضه وإصدار الحكم على نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص675–676، تحت «نكتة إيثار صيغة الماضي في قوله: ﴿أأسلمتم﴾»، وفي تتمة المبحث بيان أغراض الاستفهام.","url":""}]},{"id":"s3-72","number":72,"surah":3,"verses":[20],"references":[{"surah":3,"verses":[20]}],"verseLabel":"آل عمران: 20","question":"لماذا ختم ﴿فإنما عليك البلاغ والله بصير بالعباد﴾؟","answer":"خُتمت الآية بقصر مهمة الرسول على التبليغ، فلا يضره إعراضهم ولا يكلف هدايتهم، ثم جاء ﴿والله بصير بالعباد﴾ لبيان أن الله محيط بأحوالهم وهو الذي يتولى حسابهم وجزاءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص677، تحت «جواب الشرط وإيجازه البديع».","url":""}]},{"id":"s3-73","number":73,"surah":3,"verses":[21],"references":[{"surah":3,"verses":[21]}],"verseLabel":"آل عمران: 21","question":"لماذا جمع بين الكفر بالآيات وقتل الأنبياء وقتل الآمرين بالقسط؟","answer":"جمع فساد الاعتقاد وذروة العدوان على المبلغين ثم على أتباعهم؛ فدل التدرج أن رفض الحق لم يبق فكرةً، بل تحول إلى إسكات كل صوت يقيم العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص680–681، تحت «بلاغة التدلي في ذكر أوصاف اليهود الذين استحقوا عذاب الله».","url":""}]},{"id":"s3-74","number":74,"surah":3,"verses":[21],"references":[{"surah":3,"verses":[21]}],"verseLabel":"آل عمران: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿يبشرهم بعذاب أليم﴾ فاستعمل البشارة في العذاب؟","answer":"استعملت البشارة في ضد حقيقتها تهكمًا بهم؛ فنُزل الإنذار بالعذاب الأليم منزلة الخبر السار الذي تظهر آثاره على الوجه، وفي ذلك استهزاء بآمالهم وتشديد للوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص684–685، تحت «بلاغة الاستعارة التهكمية في البشارة».","url":""}]},{"id":"s3-75","number":75,"surah":3,"verses":[22],"references":[{"surah":3,"verses":[22]}],"verseLabel":"آل عمران: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿حبطت أعمالهم في الدنيا والآخرة﴾؟ وكيف تحبط الأعمال في الدنيا؟","answer":"حبوط الأعمال هو زوال آثارها النافعة؛ فتحبط في الدنيا بحرمانهم الحياة الطيبة والمدح وبقاء اللعنة والخزي، وتحبط في الآخرة بسقوط الثواب والنعيم، لأن العمل لا ينفع مع فساد العقيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص688–689، تحت «فائدة التمثيل في قوله: ﴿حبطت أعمالهم﴾».","url":""}]},{"id":"s3-76","number":76,"surah":3,"verses":[23],"references":[{"surah":3,"verses":[23]}],"verseLabel":"آل عمران: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿أوتوا نصيبًا من الكتاب﴾ لا: أوتوا الكتاب؟","answer":"قيل ﴿نصيبًا من الكتاب﴾ لأنهم أوتوا بعض الوحي، أو حظًا من التلاوة لم يصحبه فهم وعمل، وفي ذلك توهين لحالهم وتعريض بأنهم لم يؤدوا حق ما بأيديهم من الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص694–695، تحت «المجاز في ذكر النصيب من الكتاب».","url":""}]},{"id":"s3-77","number":77,"surah":3,"verses":[23],"references":[{"surah":3,"verses":[23]}],"verseLabel":"آل عمران: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿يدعون إلى كتاب الله ليحكم بينهم ثم يتولى فريق منهم﴾؟","answer":"جاءت الأفعال مضارعة لتصوير تجدد دعوتهم إلى كتاب الله وجاهزية حكمه، فيقابلها تجدد توليهم؛ و﴿ثم﴾ تستبعد إعراضهم بعد أن أخذوا زمنًا كافيًا لمعرفته، ونسب التولي إلى فريق لأن منهم من أسلم ولم يتول.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص696–697، تحت «دلالة الأفعال المضارعة: ﴿يدعون﴾، ﴿ليحكم﴾، ﴿يتولى﴾».","url":""}]},{"id":"s3-78","number":78,"surah":3,"verses":[24],"references":[{"surah":3,"verses":[24]}],"verseLabel":"آل عمران: 24","question":"لماذا عبّروا عن عذاب النار بقولهم ﴿لن تمسنا النار﴾ لا: لن ندخلها؟","answer":"اختاروا ﴿تمسنا﴾ لأن المس أدنى المخالطة، فصوروا العذاب في زعمهم هينًا لا يتجاوز إصابة الجلد زمنًا قليلًا، بدل الاعتراف بدخول النار والإحاطة بعذابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص658، تحت «المسّ والإصابة».","url":""}]},{"id":"s3-79","number":79,"surah":3,"verses":[24],"references":[{"surah":3,"verses":[24]}],"verseLabel":"آل عمران: 24","question":"ما سرّ قولهم: ﴿أَيَّامًا مَعْدُودَاتٍ﴾ هنا، وقولهم في البقرة: ﴿أَيَّامًا مَعْدُودَةً﴾؟","answer":"جاءت ﴿معدودات﴾ في آل عمران بالجمع السالم الأدل على القلة، لأن هذا الفريق زعم أقل القليل من أيام العذاب؛ أما ﴿معدودة﴾ في البقرة فتناسب قول فريق آخر بمدة أكثر، فاختلاف اللفظ تابع لاختلاف القائلين والسياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص700–702، تحت «سر العدول عن ﴿معدودة﴾ إلى ﴿معدودات﴾».","url":""}]},{"id":"s3-80","number":80,"surah":3,"verses":[24],"references":[{"surah":3,"verses":[24]}],"verseLabel":"آل عمران: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿وغرهم في دينهم ما كانوا يفترون﴾ فجعل الافتراء سبب غرورهم؟","answer":"لأنهم كرروا افتراءهم وأدخلوه في الدين حتى تحول في نفوسهم إلى عقيدة بديلة عن الحق، فخدعوا أنفسهم به ورسخ غرورهم واستمر إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص702–703، تحت «سر تقديم الجار والمجرور في ﴿في دينهم﴾».","url":""}]},{"id":"s3-81","number":81,"surah":3,"verses":[25],"references":[{"surah":3,"verses":[25]}],"verseLabel":"آل عمران: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿فكيف إذا جمعناهم ليوم لا ريب فيه﴾؟ ما الذي تحمله ﴿كيف﴾ هنا؟","answer":"خرجت ﴿كيف﴾ عن طلب الكيفية إلى التعجيب من حالهم والتهديد والتهويل والتفظيع؛ أي كيف يكون شأنهم حين يجمعون قهرًا ليوم محقق لا حيلة لهم في دفعه؟","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص705، تحت «بلاغة الاستفهام في قوله تعالى: ﴿فكيف اذا جمعناهم ليوم لا ريب فيه﴾»","url":""}]},{"id":"s3-82","number":82,"surah":3,"verses":[25],"references":[{"surah":3,"verses":[25]}],"verseLabel":"آل عمران: 25","question":"لماذا عطف ﴿ووفيت كل نفس ما كسبت﴾ بالواو لا بـ﴿ثم﴾؟","answer":"عطفت التوفية بالواو لا بـ﴿ثم﴾ لتناسب مقام التهديد وسرعة الحساب، فجعلت الجمع والجزاء في سياق متصل بلا إبراز تراخ، ولأن حساب كل إنسان يبدأ من لحظة موته.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص707، تحت «دلالة العطف بـ(الواو) دون (ثم) في قوله: ﴿ووفيت﴾».","url":""}]},{"id":"s3-83","number":83,"surah":3,"verses":[25],"references":[{"surah":3,"verses":[25]}],"verseLabel":"آل عمران: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم لا يظلمون﴾ بعد توفية كل نفس؟","answer":"جاءت الخاتمة بعد التوفية لتقرر أن استيفاء الجزاء عدل تام؛ فلا تزاد سيئة ولا ينقص حق، وبذلك يزول كل توهم للظلم في الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص708، تحت «دلالة التعبير بـ﴿ما﴾ في قوله تعالى: ﴿ما كسبت وهم لا يظلمون﴾».","url":""}]},{"id":"s3-84","number":84,"surah":3,"verses":[26],"references":[{"surah":3,"verses":[26]}],"verseLabel":"آل عمران: 26","question":"لماذا افتتح الدعاء بـ﴿قل اللهم مالك الملك﴾؟","answer":"افتتح بذلك ردًا على من استبعد غلبة المؤمنين؛ فالملك كله لله يؤتيه وينزعه، وجاء الأمر ﴿قل﴾ لتعليم النبي والمؤمنين دعاءً يقرر هذه الحقيقة ويطلب التمكين من مالك الملك.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص709–710، تحت «مناسبة الآية لما قبلها».","url":""}]},{"id":"s3-85","number":85,"surah":3,"verses":[26],"references":[{"surah":3,"verses":[26]}],"verseLabel":"آل عمران: 26","question":"ما سرّ الجمع بين ﴿تُؤْتِي الْمُلْكَ﴾ و﴿تَنْزِعُ الْمُلْكَ﴾، وبين الإعزاز والإذلال؟","answer":"لم يقع التكرار حشوًا؛ فالإيتاء والنزع حالتان مستقلتان تكشفان شمول القدرة في العطاء والمنع، وتكرار ﴿الملك﴾ و﴿من تشاء﴾ يصور دوران السلطان وتعاقبه بين الناس والأمم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص711، تحت «بلاغة ذكر البيان والخاص بعد الإجمال والعموم مع الإيجاز».","url":""}]},{"id":"s3-86","number":86,"surah":3,"verses":[26],"references":[{"surah":3,"verses":[26]}],"verseLabel":"آل عمران: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿تنزع الملك﴾ فصوّر زواله بالنزع؟","answer":"النزع إخراج بقوة بعد تمكن والتصاق؛ فصوّر زوال الملك على الرغم من رسوخه الظاهر، ليبين أن السلطان عارية بيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص712، تحت «يستعار النزع لإزالة الصفات والمعاني».","url":""}]},{"id":"s3-87","number":87,"surah":3,"verses":[26],"references":[{"surah":3,"verses":[26]}],"verseLabel":"آل عمران: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿وتعز من تشاء وتذل من تشاء﴾، دون أن يقال: ترفع وتخفض؟","answer":"اختير العز والذل لأن العز يتضمن القوة والغلبة والامتناع، والذل يتضمن الضعف والخضوع والقهر؛ فهما يصفان حقيقة الحال وآثارها، لا مجرد رفع المنزلة وخفضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص712–713، تحت «الاستعارة التمثيلية في قوله: ﴿وتعز من تشاء وتذل من تشاء﴾».","url":""}]},{"id":"s3-88","number":88,"surah":3,"verses":[26],"references":[{"surah":3,"verses":[26]}],"verseLabel":"آل عمران: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿بيدك الخير﴾ ولم يذكر الشر؟","answer":"اقتصر على الخير أدبًا في خطاب الله، ولأن المقام مقام ثناء وافتقار؛ والشر ليس إليه استقلالًا بل يقع ضمن حكمته وعدله وتقديره.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص713–714، تحت «الإيجاز بالحذف، أو الاكتفاء في قوله: ﴿بيدك الخير﴾».","url":""}]},{"id":"s3-89","number":89,"surah":3,"verses":[27],"references":[{"surah":3,"verses":[27]}],"verseLabel":"آل عمران: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿تولج الليل في النهار وتولج النهار في الليل﴾ بفعل الإيلاج؟","answer":"الإيلاج إدخال تدريجي؛ فيدخل الليل في النهار والنهار في الليل بالزيادة والنقص والتعاقب، وجاء المضارع لاستحضار هذه الحركة الكونية المتجددة التي لا تتوقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص718–719، تحت «علاقة التكوير بإيلاج الليل في النهار، وإيلاج النهار في الليل».","url":""}]},{"id":"s3-90","number":90,"surah":3,"verses":[27],"references":[{"surah":3,"verses":[27]}],"verseLabel":"آل عمران: 27","question":"ماذا يثبت الجمع بين ﴿تُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ﴾ و﴿تُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ﴾؟","answer":"يثبت تمام قدرة الله على إنشاء الضدين بعضهما من بعض: كإخراج النبات الحي من الحب الجامد والحب من النبات، ويدخل فيه مجازًا إخراج المؤمن من الكافر والكافر من المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص722، تحت «بين الحقيقة والمجاز في قوله: ﴿وتخرج الحي من الميت وتخرج الميت من الحي﴾».","url":""}]},{"id":"s3-91","number":91,"surah":3,"verses":[27],"references":[{"surah":3,"verses":[27]}],"verseLabel":"آل عمران: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿وترزق من تشاء بغير حساب﴾ بعد مشاهد الكون والحياة والموت؟","answer":"جاءت الخاتمة تذييلًا واستدلالًا: فمن قدر على تقليب الليل والنهار وإخراج الحي والميت يقدر على رزق من يشاء عطاءً واسعًا بلا تضييق ولا عد؛ وفي السياق بشارة للمؤمنين بالعز والتمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص723، تحت «بلاغة التذييل في قوله تعالى: ﴿وترزق من تشاء بغير حساب﴾»","url":""}]},{"id":"s3-92","number":92,"surah":3,"verses":[28],"references":[{"surah":3,"verses":[28]}],"verseLabel":"آل عمران: 28","question":"لماذا نهى المؤمنين عن اتخاذ الكافرين أولياء ﴿من دون المؤمنين﴾؟","answer":"قُيد النهي بـ﴿من دون المؤمنين﴾ لأن المؤمنين هم الأحق بالموالاة وفي موالاتهم غنية عن موالاة الكافرين، ولتشنيع مفارقة جماعتهم إلى من تضر موالاته بهم، مع الإيغال في لزوم جماعة الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص727، تحت «دلالة قوله تعالى: ﴿من دون المؤمنين﴾».","url":""}]},{"id":"s3-93","number":93,"surah":3,"verses":[28],"references":[{"surah":3,"verses":[28]}],"verseLabel":"آل عمران: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يفعل ذلك فليس من الله في شيء﴾ بهذه الصياغة الشديدة؟","answer":"جاءت الصياغة الشديدة للمبالغة في انقطاع المتولي للكافرين عن ولاية الله ودينه وحزبه، وعمم ﴿في شيء﴾ النفي في كل حال، وحذف متعلق الشيء ليتسع لكل ما يوصل إلى رضا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص728، تحت «الحذف في قوله تعالى: ﴿فليس من الله في شيء﴾».","url":""}]},{"id":"s3-94","number":94,"surah":3,"verses":[28],"references":[{"surah":3,"verses":[28]}],"verseLabel":"آل عمران: 28","question":"لماذا استثنى التقية بقوله ﴿إلا أن تتقوا منهم تقاة﴾؟","answer":"استثنيت التقية احتراسًا من إطلاق النهي؛ فيجوز إظهار معاملة تشبه الموالاة عند خوف ضرر الكافرين، لا موالاتهم بالقلب، وهي حالة ضرورة محققة عارضة لا تستمر فتتحول إلى ولاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص728–729، تحت «الاستثناء والاحتراس في قوله: ﴿إلا أن تتقوا منهم تقاة﴾».","url":""}]},{"id":"s3-95","number":95,"surah":3,"verses":[28],"references":[{"surah":3,"verses":[28]}],"verseLabel":"آل عمران: 28","question":"لماذا تكرر قوله تعالى: ﴿ويحذركم الله نفسه﴾ في آل عمران؟","answer":"لتأكيد الوعيد وزيادة تقريره. ويجوز أن يكون التحذير الأول من موالاة الكافرين، والثاني من أن يجدوا يوم القيامة أعمال السوء محضرة أمامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص745، تحت عنوان «فائدة التحذير بعد الوعيد والتهديد»","url":""}]},{"id":"s3-777","number":777,"surah":3,"verses":[28],"references":[{"surah":3,"verses":[28]}],"verseLabel":"آل عمران: 28","question":"ما دلالة ذكر ﴿نفسه﴾ في قوله تعالى: ﴿ويحذركم الله نفسه﴾؟","answer":"يزيد التهديد شدة وعمومًا؛ فالمحذَّر منه عقاب يصدر من الله، ولا يقيده نوع معين من العقاب، فيحذر المخاطب من مجاوزة حدوده ومخالفة أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص730، تحت عنوان «بلاغة الكناية في قوله: ﴿ويحذركم﴾، وبلاغة الإيغال في التحذير في ﴿نفسه﴾»","url":""}]},{"id":"s3-96","number":96,"surah":3,"verses":[29],"references":[{"surah":3,"verses":[29]}],"verseLabel":"آل عمران: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿إن تخفوا ما في صدوركم أو تبدوه يعلمه الله﴾ فقدم الإخفاء؟","answer":"قدم الإخفاء لأن حقيقة الموالاة المنهي عنها تبدأ باطنًا في الصدور ثم قد يظهر أثرها، فجاء التحذير مما وراء الفعل الظاهر أولًا، مع التسوية بين السر والعلن في علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص734–735، تحت «الترقي من الإخفاء إلى الإبداء».","url":""}]},{"id":"s3-97","number":97,"surah":3,"verses":[29],"references":[{"surah":3,"verses":[29]}],"verseLabel":"آل عمران: 29","question":"لماذا عدل من السماء إلى جمع السماوات في ﴿ويعلم ما في السماوات وما في الأرض﴾؟","answer":"عُدل إلى جمع ﴿السماوات﴾ للدلالة على طبقاتها السبع وشمول علم الله وقدرته للكون كله، ولمناسبة سياق ملك الملك وتقليب الليل والنهار، والترقي من خفايا الصدور إلى العالم العلوي كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص735–736، تحت «سر العدول عن (السماء) إلى ﴿السماوات﴾».","url":""}]},{"id":"s3-98","number":98,"surah":3,"verses":[29],"references":[{"surah":3,"verses":[29]}],"verseLabel":"آل عمران: 29","question":"لماذا أظهر اسم الجلالة في ﴿والله على كل شيء قدير﴾ ولم يضمره؟","answer":"أظهر اسم الجلالة لتستقل الجملة وتجري مجرى المثل، ولما في ذكر الاسم من الثناء والتعظيم، وليجتمع تقرير العلم المحيط مع القدرة المطلقة فيشتد التهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص737، تحت «أظهر اسم الجلالة في موضع الإضمار استقلالًا للجملة وتمثيلًا».","url":""}]},{"id":"s3-99","number":99,"surah":3,"verses":[30],"references":[{"surah":3,"verses":[30]}],"verseLabel":"آل عمران: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿تجد كل نفس ما عملت من خير محضرًا﴾ باسم المفعول لا حاضرًا؟","answer":"قيل ﴿محضرًا﴾ لا حاضرًا لأن الإحضار يكون لشيء غائب موجود محفوظ، فتُجلب الأعمال يوم القيامة وتوضع أمام أصحابها كاملة لا مجال لإنكارها، وفي ذلك تهويل وتبكيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص742، تحت «سر إيثار التعبير باسم المفعول ﴿محضرًا﴾ بدل اسم الفاعل (حاضرًا)».","url":""}]},{"id":"s3-100","number":100,"surah":3,"verses":[30],"references":[{"surah":3,"verses":[30]}],"verseLabel":"آل عمران: 30","question":"لماذا تتمنى النفس ﴿لو أن بينها وبينه أمدًا بعيدًا﴾ بدل أن تتمنى زوال السيئة؟","answer":"لأنها ترى السيئة محضرة ثابتة لا سبيل إلى زوالها، فتتمنى أقصى ما بقي ممكنًا في تصورها: أن يبعد عنها أثرها زمانًا أو مكانًا أمدًا طويلًا، وفي ذلك كشف لتحسرها وهول اللقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص743–744، تحت «دلالة التمني في قوله: ﴿تود لو أن بينها وبينه أمدًا بعيدًا﴾».","url":""}]},{"id":"s3-101","number":101,"surah":3,"verses":[30],"references":[{"surah":3,"verses":[30]}],"verseLabel":"آل عمران: 30","question":"لماذا جمع بين ﴿ويحذركم الله نفسه﴾ و﴿والله رؤوف بالعباد﴾؟","answer":"التحذير يمنع الاغترار، والرأفة تبين أن هذا التحذير نفسه رحمة تحمي العباد من أسباب السخط؛ فاجتمع الجلال والجمال بلا تناقض.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص745–746، تحت «سر التذييل بذكر الرأفة بعد التحذير والوعيد».","url":""}]},{"id":"s3-102","number":102,"surah":3,"verses":[31],"references":[{"surah":3,"verses":[31]}],"verseLabel":"آل عمران: 31","question":"لماذا جعل الله دليل محبته اتباع الرسول في ﴿إن كنتم تحبون الله فاتبعوني﴾؟","answer":"جعل اتباع الرسول دليل المحبة لأنه المبيّن عن الله والطريق إلى طاعته ورضاه؛ فعلق حصول محبة الله على الاتباع ليكون محكًا عمليًا يكشف صدق من يدعي محبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص749–750، تحت «دلالة الشرط وجوابه».","url":""}]},{"id":"s3-103","number":103,"surah":3,"verses":[31],"references":[{"surah":3,"verses":[31]}],"verseLabel":"آل عمران: 31","question":"لماذا جاء جواب الاتباع ﴿يحببكم الله ويغفر لكم ذنوبكم﴾؟","answer":"جاء جواب الاتباع بمحبة الله ومغفرته لأن اتباع الرسول سبب لمحبة الله، وهذه المحبة تدعو إلى الطاعة وترك المعصية فتستجلب المغفرة؛ وفي الجمع تشويق لتحصيل أسباب الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص749، تحت «دلالة الشرط وجوابه».","url":""}]},{"id":"s3-104","number":104,"surah":3,"verses":[32],"references":[{"surah":3,"verses":[32]}],"verseLabel":"آل عمران: 32","question":"لماذا أعاد الأمر ﴿قل أطيعوا الله والرسول﴾ بعد آية الاتباع؟","answer":"أعيد الأمر لتأكيد أن دعوى المحبة لا تصح إلا بطاعة الله ورسوله، ولرد شبهة من يفصل بين متابعة محمد وطاعة الله؛ وأظهر ﴿الله والرسول﴾ لتعيين جهة الطاعة وعمومها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص752–753، تحت «مناسبة الآية لما قبلها».","url":""}]},{"id":"s3-105","number":105,"surah":3,"verses":[32],"references":[{"surah":3,"verses":[32]}],"verseLabel":"آل عمران: 32","question":"لماذا ختم الإعراض بـ﴿فإن الله لا يحب الكافرين﴾ ولم يقل: لا يحبهم؟","answer":"أظهر وصف ﴿الكافرين﴾ بدل الضمير ليعمم الحكم ويبين علته: إنما انتفت محبة الله عنهم لكفرهم الناشئ من الإعراض عن الطاعة، وفيه بالمقابل إشعار بخصوص محبته للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص754–755، تحت «تقييد انتفاء المحبة مع وصف الكفر».","url":""}]},{"id":"s3-106","number":106,"surah":3,"verses":[33],"references":[{"surah":3,"verses":[33]}],"verseLabel":"آل عمران: 33","question":"لماذا جمع الله في الاصطفاء آدم ونوحًا وآل إبراهيم وآل عمران؟","answer":"جمعهم لعرض سلسلة الاصطفاء من آدم، ثم نوح أول رسول لأهل الأرض، ثم آل إبراهيم الذين في ذريتهم الأنبياء وخاتمهم محمد، ثم آل عمران تمهيدًا لقصة مريم وعيسى؛ فهو إجمال ينتقل منه إلى تفصيل المصطفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص758، تحت «لفظ (آل) كناية عن الأسر التي اصطفى الله أبناءها للنبوة».","url":""}]},{"id":"s3-107","number":107,"surah":3,"verses":[34],"references":[{"surah":3,"verses":[34]}],"verseLabel":"آل عمران: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿ذرية بعضها من بعض﴾ مع اختلاف أزمانهم وأنسابهم؟","answer":"لأنهم ذرية متصلة في النسب من آدم ثم نوح ثم إبراهيم، ومتصلون كذلك في العقيدة ووحدة مصدر الرسالة؛ و﴿من﴾ تبين شدة الاتصال والوثاقة بين بعضهم وبعض رغم تباعد الأزمنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص763، تحت «سر التعبير بلفظ ﴿ذرية﴾».","url":""}]},{"id":"s3-108","number":108,"surah":3,"verses":[34],"references":[{"surah":3,"verses":[34]}],"verseLabel":"آل عمران: 34","question":"لماذا ختم الاصطفاء بـ﴿والله سميع عليم﴾؟","answer":"ختم بـ﴿سميع عليم﴾ لأن الله يسمع أقوال العباد ويعلم أعمالهم ومن يصلح للاصطفاء والرسالة، فلا يكون الاختيار لمجرد دعوى نسب، وفي التذييل تهديد لمن افترى من أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص765، تحت «دلالة التذييل في قوله: ﴿والله سميع عليم﴾».","url":""}]},{"id":"s3-109","number":109,"surah":3,"verses":[35],"references":[{"surah":3,"verses":[35]}],"verseLabel":"آل عمران: 35","question":"ما سرّ قول امرأة عمران: ﴿نَذَرْتُ لَكَ مَا فِي بَطْنِي مُحَرَّرًا﴾ دون «نذرت ولدي»؟","answer":"قالت ﴿ما في بطني﴾ لأن أمر الجنين وجنسه كانا مجهولين لها، فناسبه اسم مبهم لغير العاقل، ثم قيدته بـ﴿محررًا﴾ أي خالصًا من الشواغل لخدمة بيت المقدس والتقرب إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص769، تحت «سر التعبير عن الولد بـ﴿ما﴾ بدل (من)».","url":""}]},{"id":"s3-110","number":110,"surah":3,"verses":[35],"references":[{"surah":3,"verses":[35]}],"verseLabel":"آل عمران: 35","question":"ما دلالة قول امرأة عمران: ﴿فَتَقَبَّلْ مِنِّي﴾ قبل أن تعلم ما ستلد؟","answer":"طلبت القبول لأن قبول النذر لا يتصور بلا مولود صالح للخدمة، فكان دعاؤها استدعاءً ضمنيًا لأن يجعل ما في بطنها ذكرًا؛ إما لأنها بنت نذرها على ذلك التقدير أو جعلته وسيلة لطلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص769–770، تحت «نكتة الدعاء بالقبول للنذر».","url":""}]},{"id":"s3-111","number":111,"surah":3,"verses":[36],"references":[{"surah":3,"verses":[36]}],"verseLabel":"آل عمران: 36","question":"ما دلالة قولها: ﴿رَبِّ إِنِّي وَضَعْتُهَا أُنْثَى﴾ مع أن الله يعلم ما وضعت؟","answer":"لم تخبر الله ليعلم، بل ناجته تحسرًا ودهشة واعتذارًا حين خاب رجاؤها في مولود ذكر يصلح للخدمة؛ فحكى القول اضطرابها ومحاولة تسلية نفسها، ثم قرر الوحي أن الله أعلم بما وضعت وبما أودعه فيها من الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص775، تحت «توجيه ما ورد من القراءات في ﴿وضعتها﴾ وبلاغتها».","url":""}]},{"id":"s3-112","number":112,"surah":3,"verses":[36],"references":[{"surah":3,"verses":[36]}],"verseLabel":"آل عمران: 36","question":"لماذا جاء الاعتراض ﴿والله أعلم بما وضعت﴾؟","answer":"جاءت ﴿والله أعلم بما وضعت﴾ اعتراضًا إلهيًا يقرر أن الله أعلم بحقيقة مريم ومآلها وما أودع فيها من الخير، لا مجرد علم جنس المولود، ويمهد لأن الأنثى التي وهبها الله خير من الذكر الذي كانت ترجوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص777–778، تحت «دلالة الاعتراض بأكثر من جملة».","url":""}]},{"id":"s3-113","number":113,"surah":3,"verses":[36],"references":[{"surah":3,"verses":[36]}],"verseLabel":"آل عمران: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿وليس الذكر كالأنثى﴾، دون أن يقال: وليست الأنثى كالذكر؟","answer":"قدّم الذكر لأنه المقصود المتوقع للخدمة في تصورها، ثم جاء التشبيه ليقرر أن الأنثى التي وهبها الله ليست كالذكر الذي تمنته؛ بل سيكون لها شأن آخر أعظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص776–777، تحت «معنى التشبيه المنفي في قوله: ﴿وليس الذكر كالأنثى﴾».","url":""}]},{"id":"s3-115","number":115,"surah":3,"verses":[37],"references":[{"surah":3,"verses":[37]}],"verseLabel":"آل عمران: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿فتقبلها ربها بقبول حسن﴾ بالتضعيف، دون أن يقال: قبلها؟","answer":"اختير ﴿تقبلها﴾ للدلالة على كمال القبول والعناية بها، ثم أكد المصدر ﴿بقبول﴾ تحقق ذلك القبول، ووصفه بالحسن ليبين أنه قبول مقرون بالرعاية والإكرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص784–785، تحت «سر العدول عن (قبلها) إلى ﴿فتقبلها﴾».","url":""}]},{"id":"s3-116","number":116,"surah":3,"verses":[37],"references":[{"surah":3,"verses":[37]}],"verseLabel":"آل عمران: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنبتها نباتًا حسنًا﴾ فشبّه نشأة مريم بالنبات؟","answer":"استعير الإنبات لتربية مريم ونشأتها المتدرجة؛ فكما ينمى النبات بالرعاية حتى يحسن ويثمر، أنشأها الله نشأة حسنة في بدنها وروحها وأثمرت صلاحًا وطهرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص785–786، تحت «دلالة استعارة الإنبات لمعنى الرعاية».","url":""}]},{"id":"s3-117","number":117,"surah":3,"verses":[37],"references":[{"surah":3,"verses":[37]}],"verseLabel":"آل عمران: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿وكفلها زكريا﴾؟ وما دلالة التشديد في القراءة؟","answer":"في قراءة التشديد أسند التكفيل إلى الله: جعل زكريا كافلًا لها وهيأ له رعايتها، وفي قراءة التخفيف يكون زكريا هو الكافل القائم بنفقتها وصيانتها؛ فالقراءتان تجمعان التدبير الإلهي ومباشرة زكريا للكفالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص786، تحت «دلالة عطف الخاص على العام».","url":""}]},{"id":"s3-118","number":118,"surah":3,"verses":[37],"references":[{"surah":3,"verses":[37]}],"verseLabel":"آل عمران: 37","question":"لماذا كان زكريا يجد عند مريم رزقًا كلما دخل عليها المحراب؟","answer":"جعل الله الرزق المتجدد كرامةً لمريم ودليلًا لزكريا على أن العطاء لا تحكمه الأسباب المألوفة؛ لذلك انتقل المشهد مباشرة إلى دعائه بالذرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص787، تحت «تنوع الفوائد البلاغية لـ﴿كلما﴾».","url":""}]},{"id":"s3-119","number":119,"surah":3,"verses":[38],"references":[{"surah":3,"verses":[38]}],"verseLabel":"آل عمران: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿هنالك دعا زكريا ربه﴾؟ ماذا أضاف اسم الإشارة؟","answer":"يشير ﴿هنالك﴾ إلى اللحظة والمقام اللذين شاهد فيهما رزق مريم؛ فحرّك المشهد رجاءه ودعاءه بالذرية على الفور.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص794–795، تحت «سر التعبير بـ﴿هنالك﴾ ووجه زيادة اللام فيه».","url":""}]},{"id":"s3-120","number":120,"surah":3,"verses":[38],"references":[{"surah":3,"verses":[38]}],"verseLabel":"آل عمران: 38","question":"لماذا طلب زكريا ﴿ذرية طيبة﴾ لا ولدًا فقط؟","answer":"اختار ﴿ذرية﴾ لأنها تطلق على الواحد والجمع وتستحضر امتداد النسل الصالح، ثم قيدها بـ﴿طيبة﴾ لطلب ولد صالح في دينه وخلقه وطبعه، لا مجرد حصول ولد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص798–799، تحت «نكتة الدعاء بالعموم لـ﴿ذرية﴾ وإرادة الخصوص (الولد الذكر)».","url":""}]},{"id":"s3-121","number":121,"surah":3,"verses":[39],"references":[{"surah":3,"verses":[39]}],"verseLabel":"آل عمران: 39","question":"لماذا نادته الملائكة وهو قائم يصلي في المحراب؟","answer":"جاءت البشارة في موطن الطاعة الذي خرج منه الدعاء، وفي حال قيام بين يدي الله؛ فوافق الجواب مقام التضرع وأشعر بسرعة القبول.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص13–14، تحت «سر التعبير بالجملة الحالية».","url":""}]},{"id":"s3-122","number":122,"surah":3,"verses":[39],"references":[{"surah":3,"verses":[39]}],"verseLabel":"آل عمران: 39","question":"لماذا وصف يحيى بأنه ﴿مصدق بكلمة من الله وسيدًا وحصورًا ونبيًا﴾ بهذا الترتيب؟","answer":"رُتبت الخصال في ترقٍّ: بدأ بتصديقه بعيسى، ثم سيادته الجامعة لخصال الفضل، ثم عفته وزهده مع القدرة في ﴿حصورًا﴾، وختم بالنبوة وهي الذروة؛ وعطفها بالواو لإظهار استقلال كل خصلة في شخصيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص19–21، تحت «براعة الترقي في تعداد صفات يحيى».","url":""}]},{"id":"s3-123","number":123,"surah":3,"verses":[39],"references":[{"surah":3,"verses":[39]}],"verseLabel":"آل عمران: 39","question":"لماذا سمّى عيسى ﴿كلمة من الله﴾؟","answer":"سمي عيسى ﴿كلمة من الله﴾ لأنه خُلق بكلمة الله ﴿كن﴾ من غير أب ولا سبب بشري معتاد، فأطلق اسم السبب، وهو الكلمة، على المسبب الناشئ عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص17، تحت «تنوع المجاز في قوله: ﴿بكلمة﴾».","url":""}]},{"id":"s3-124","number":124,"surah":3,"verses":[39,45],"references":[{"surah":3,"verses":[39,45]}],"verseLabel":"آل عمران: 39؛ آل عمران: 45","question":"ما سرّ التعبير بقوله تعالى: في بشارة يحيى ﴿مصدقًا بكلمة من الله﴾، وقيل في بشارة عيسى ﴿بكلمة منه﴾؟","answer":"ذُكر اسم الله ظاهرًا مع يحيى لأن وصفه تابع لبشارة مستقلة ويؤكد أن عيسى كلمة صادرة بأمر الله، أما في بشارة عيسى فجيء بالضمير ﴿منه﴾ لقرب مرجعه في قوله ﴿إن الله يبشرك﴾، ولتركيز الكلام على خصوص هذه الكلمة الموهوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص15–19، تحت «بلاغة التشابه اللفظي».","url":""}]},{"id":"s3-125","number":125,"surah":3,"verses":[40],"references":[{"surah":3,"verses":[40]}],"verseLabel":"آل عمران: 40","question":"ما دلالة سؤال زكريا: ﴿أَنَّى يَكُونُ لِي غُلَامٌ﴾ بعد أن دعا بالذرية؟","answer":"سؤاله ليس شكًا في القدرة، بل طلب لمعرفة الكيفية مع اجتماع الكبر والعقر؛ لذلك جاء الجواب بتقرير إطلاق المشيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص27–28، تحت «بلاغة الاستفهام في الآية».","url":""}]},{"id":"s3-126","number":126,"surah":3,"verses":[40],"references":[{"surah":3,"verses":[40]}],"verseLabel":"آل عمران: 40","question":"لماذا قدّم في آل عمران ﴿بلغني الكبر﴾ على ﴿وامرأتي عاقر﴾، وعكس الترتيب في مريم؟","answer":"قدم الكبر في آل عمران لأنه العائق الأظهر عند زكريا، وجعل عقر امرأته أمرًا إضافيًا؛ أما في مريم فقد سبق وصف وهنه وكبره وسبق ذكر عقر امرأته، فقدمها عند إعادة الحالين، وأخر ﴿عتيًا﴾ لمناسبة فواصل ﴿سويًا﴾ و﴿عشيًا﴾ و﴿صبيًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص29–31، تحت «بلاغة القلب في جملة ﴿وقد بلغني الكبر﴾».","url":""}]},{"id":"s3-127","number":127,"surah":3,"verses":[40],"references":[{"surah":3,"verses":[40]}],"verseLabel":"آل عمران: 40","question":"ما سرّ التعبير بقوله تعالى: لزكريا ﴿الله يفعل ما يشاء﴾، وقيل لمريم ﴿الله يخلق ما يشاء﴾؟","answer":"قصة زكريا تتعلق بردّ القدرة والخصوبة إلى حالهما فناسب عموم ﴿يفعل﴾، أما مريم فالمقام إنشاء ولد بلا أب فناسب التصريح بـ﴿يخلق﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص96، تحت «يخلق، ويفعل، وينشئ، ويصنع».","url":""}]},{"id":"s3-128","number":128,"surah":3,"verses":[41],"references":[{"surah":3,"verses":[41]}],"verseLabel":"آل عمران: 41","question":"لماذا طلب زكريا آية بعد البشارة؟","answer":"لم يطلب الآية شكًا في القدرة، بل طلب علامة يعرف بها بدء تحقق البشارة ليستقبل الموهبة بالسرور والاستبشار، ويتفرغ لشكر الله عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص38–40، تحت «التناسب المعنوي بين لفظي ﴿آية﴾ و﴿رمزًا﴾».","url":""}]},{"id":"s3-129","number":129,"surah":3,"verses":[41],"references":[{"surah":3,"verses":[41]}],"verseLabel":"آل عمران: 41","question":"لماذا كانت آيته ألا يكلم الناس ثلاثة أيام إلا رمزًا؟","answer":"كانت علامة خارقة في آلة الكلام نفسها مع بقاء القدرة على الذكر، لتفصل بين مخاطبة الخلق ومناجاة الخالق وتفرغه لشكر النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص39، تحت «فن الإشارة في قوله: ﴿رمزًا﴾».","url":""}]},{"id":"s3-130","number":130,"surah":3,"verses":[41],"references":[{"surah":3,"verses":[41]}],"verseLabel":"آل عمران: 41","question":"لماذا أُمر بكثرة الذكر والتسبيح بالعشي والإبكار وهو ممنوع من الكلام؟","answer":"خُص المنع بكلام الناس، وأُمر زكريا بالذكر شكرًا لله على نعمته، وبالتسبيح تنزيهًا له عن كل نقص. وذُكر العشي والإبكار، أي وقت العشاء وأول النهار، مع الحث على كثرة الذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص42، تحت عنوان «خروج أمر الذكر إلى معنى التوجيه والإرشاد»","url":""}]},{"id":"s3-131","number":131,"surah":3,"verses":[42],"references":[{"surah":3,"verses":[42]}],"verseLabel":"آل عمران: 42","question":"ما سرّ تكرار الاصطفاء في قول الملائكة: ﴿إِنَّ اللَّهَ اصْطَفَاكِ وَطَهَّرَكِ وَاصْطَفَاكِ عَلَى نِسَاءِ الْعَالَمِينَ﴾؟","answer":"ليس الثاني تكرارًا خاليًا؛ فالاصطفاء الأول لاختيار مريم للولاية والكرامة والتربية الطاهرة، والثاني اصطفاء خاص لولادة عيسى من غير أب وما منحها ذلك من منزلة على نساء العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص52–53، تحت «سر تكرار لفظ الاصطفاء».","url":""}]},{"id":"s3-132","number":132,"surah":3,"verses":[43],"references":[{"surah":3,"verses":[43]}],"verseLabel":"آل عمران: 43","question":"ما سرّ تقديم السجود على الركوع في ﴿واسجدي واركعي﴾؟","answer":"لا تدل الواو على أن السجود يسبق الركوع في هيئة الصلاة؛ وإنما قُدّم السجود في الذكر لعظيم فضله، إذ يكون العبد فيه أقرب إلى ربه، ثم ذُكر الركوع مع جماعة المصلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص58–59، تحت «سر تقديم لفظ السجود».","url":""}]},{"id":"s3-133","number":133,"surah":3,"verses":[43],"references":[{"surah":3,"verses":[43]}],"verseLabel":"آل عمران: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿مع الراكعين﴾ لا الراكعات؟","answer":"قيل ﴿مع الراكعين﴾ لأن جمع المذكر يدخل فيه الرجال والنساء بطريق التغليب، وهو أنسب بمعنى الصلاة مع الجماعة، كما يلائم فاصلة الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص60–61، تحت «سر الجمع بصيغة ﴿الراكعين﴾ دون (الراكعات)».","url":""}]},{"id":"s3-134","number":134,"surah":3,"verses":[44],"references":[{"surah":3,"verses":[44]}],"verseLabel":"آل عمران: 44","question":"لماذا سُمّيت قصة مريم ﴿من أنباء الغيب﴾؟","answer":"سميت ﴿من أنباء الغيب﴾ لأن النبي ﷺ لم يشهد وقائع مريم واقتراع الكافلين، ولم يتلق خبرها من أحد، فجاء إخباره المحكم بها دليلًا على الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص68–69، تحت «براعة الكناية في ﴿أنباء الغيب﴾».","url":""}]},{"id":"s3-135","number":135,"surah":3,"verses":[44],"references":[{"surah":3,"verses":[44]}],"verseLabel":"آل عمران: 44","question":"لماذا صُوّر اقتراع الكافلين بإلقاء الأقلام؟","answer":"لأن الأقلام أدوات علمهم وكتابتهم للتوراة، فجعل إلقاؤها في القرعة مشهدًا يجمع شرف الكفالة وشرف العلم، ويظهر أن اختيار زكريا لم يكن محاباة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص71، تحت «براعة الاستعارة في قوله: ﴿أقلامهم﴾».","url":""}]},{"id":"s3-136","number":136,"surah":3,"verses":[45],"references":[{"surah":3,"verses":[45]}],"verseLabel":"آل عمران: 45","question":"لماذا بشّرت الملائكة مريم بـ﴿كلمة منه اسمه المسيح عيسى ابن مريم﴾ بهذا التفصيل؟","answer":"بدأ بالمبهم ﴿كلمة منه﴾ لتفخيم شأن المبشَّر به وتشويق السامع إلى بيانه، ثم فُسر باسمه ولقبه ونسبته إلى أمه؛ وفي ﴿ابن مريم﴾ تقرير من أول البشارة أنه يولد بلا أب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص77–78، تحت «توجيه الإطناب بتعداد ذكر اللقب والاسم والوصف».","url":""}]},{"id":"s3-137","number":137,"surah":3,"verses":[45],"references":[{"surah":3,"verses":[45]}],"verseLabel":"آل عمران: 45","question":"لماذا نُسب عيسى إلى أمه في البشارة قبل ولادته؟","answer":"لتقرير نسبه الوحيد من أول البشارة ونفي الأب عنه، مع تشريف مريم؛ وفي ذلك تمهيد للمعجزة ورد على من ألّهه أو بهتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص78–79، تحت «براعة الكناية في قوله: ﴿ابن مريم﴾».","url":""}]},{"id":"s3-138","number":138,"surah":3,"verses":[45],"references":[{"surah":3,"verses":[45]}],"verseLabel":"آل عمران: 45","question":"لماذا جمع له الوجاهة في الدنيا والآخرة والقرب؟","answer":"الوجاهة في الدنيا قبول الرسالة وظهور الآيات، وفي الآخرة كرامة الجزاء، والقرب يبين أصل المنزلة عند الله؛ فاستوعبت البشارة الحالين ومصدر شرفهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص80، تحت «الكناية في معنى الوجاهة في قوله: ﴿وجيها في الدنيا والآخرة﴾».","url":""}]},{"id":"s3-139","number":139,"surah":3,"verses":[45],"references":[{"surah":3,"verses":[45]}],"verseLabel":"آل عمران: 45","question":"لماذا جاءت البشارة بمريم في آل عمران على لسان ﴿الملائكة﴾ جمعًا، وفي سورة مريم جاءها رسول واحد؟","answer":"المراد في الموضعين جبريل؛ وجاء ﴿الملائكة﴾ جمعًا في آل عمران تعظيمًا له بوصفه رئيسهم أو لأنه كان في جماعة منهم، وأُفرد في مريم لأن السورة فصلت مشهد التمثل وعيّنت الرسول الذي باشر مهمة النفخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص62–63، تحت «المتشابه اللفظي».","url":""}]},{"id":"s3-140","number":140,"surah":3,"verses":[45],"references":[{"surah":3,"verses":[45]}],"verseLabel":"آل عمران: 45","question":"ما سرّ التعبير بقوله تعالى: في آل عمران ﴿إن الله يبشرك بكلمة منه﴾، وفي مريم ﴿إنما أنا رسول ربك لأهب لك غلامًا زكيًا﴾؟","answer":"صرحت آل عمران بـ﴿إن الله يبشرك﴾ لأن سياقها يؤصل التوحيد وينسب الخلق والبشارة إلى الله ردًا على الغلو في عيسى، أما مريم فتفصل مشهد جبريل فقال ﴿إنما أنا رسول ربك﴾ و﴿لأهب﴾ لبيان مهمته المباشرة بإذن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص62–63، تحت «المتشابه اللفظي».","url":""}]},{"id":"s3-141","number":141,"surah":3,"verses":[46],"references":[{"surah":3,"verses":[46]}],"verseLabel":"آل عمران: 46","question":"لماذا ذُكر كلام عيسى في المهد مقرونًا بكلامه كهلًا؟","answer":"كلام المهد معجزة، وذكر كلام الكهولة يقرر استمرار حياته البشرية ورسالته ونضج بيانه؛ فالجمع يمنع حصر شأنه في الخارق وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص85–86، تحت «سر الطباق في لفظي ﴿المهد﴾ و﴿كهلًا﴾».","url":""}]},{"id":"s3-142","number":142,"surah":3,"verses":[47],"references":[{"surah":3,"verses":[47]}],"verseLabel":"آل عمران: 47","question":"ما سرّ قول مريم: ﴿وَلَمْ يَمْسَسْنِي بَشَرٌ﴾ دون «رجل»؟","answer":"اختير ﴿بشر﴾ لملاءمته ﴿يمسسني﴾؛ فالبشر مأخوذ من ظهور البشرة، والمس مباشرة لها، كما أن اللفظ يشمل الواحد والجمع والمذكر والمؤنث، فكان أبلغ في نفي كل مباشرة بشرية وصون طهارتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص91–92، تحت «نكتة التناسب بين ﴿يمسسني﴾ و﴿بشر﴾».","url":""}]},{"id":"s3-143","number":143,"surah":3,"verses":[47],"references":[{"surah":3,"verses":[47]}],"verseLabel":"آل عمران: 47","question":"لماذا عبّرت بالمسّ عن العلاقة الزوجية؟","answer":"المس كناية مهذبة تفهم المقصود من غير تصريح بما يستحيا منه، وهي أليق بطهارة مريم ومقام خطاب الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص91، تحت «بلاغة القيد بالجملة الحالية المتضمنة الكناية».","url":""}]},{"id":"s3-144","number":144,"surah":3,"verses":[47],"references":[{"surah":3,"verses":[47]}],"verseLabel":"آل عمران: 47","question":"لماذا جاء جوابها ﴿كذلك الله يخلق ما يشاء﴾ ثم ﴿إذا قضى أمرًا فإنما يقول له كن فيكون﴾؟","answer":"قررت ﴿الله يخلق ما يشاء﴾ أولًا أن الخلق تابع لمشيئته فلا يُستبعد ولد بلا أب، ثم بينت ﴿إذا قضى أمرًا فإنما يقول له كن فيكون﴾ سرعة نفاذ ما شاءه من غير توقف على الأسباب المعتادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص93، تحت «وجه مناسبة جملتي جواب الاستفهام».","url":""}]},{"id":"s3-145","number":145,"surah":3,"verses":[47],"references":[{"surah":3,"verses":[47]}],"verseLabel":"آل عمران: 47","question":"ما سرّ تصدير سؤال مريم في آل عمران بـ﴿رَبِّ﴾، وعدم تصديره بذلك في سورة مريم؟","answer":"في آل عمران حُكي سؤالها في سياق خطاب الملائكة فصدرته بنداء ربها والتجأت إليه، أما في سورة مريم فالمشهد حوار مباشر مع الرسول الذي تمثل لها، فجاء سؤالها جوابًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص71، تحت «المتشابه اللفظي».","url":""}]},{"id":"s3-146","number":146,"surah":3,"verses":[47],"references":[{"surah":3,"verses":[47]}],"verseLabel":"آل عمران: 47","question":"ما سرّ قول مريم في آل عمران ﴿وَلَدٌ﴾، وفي سورة مريم ﴿غُلَامٌ﴾؟","answer":"قالت في آل عمران ﴿ولد﴾ لأن البشارة سبقت بتسمية عيسى ووصفه فصار المقصود معلومًا، وقالت في مريم ﴿غلام﴾ محاكاةً للفظ جبريل في قوله قبلها ﴿لأهب لك غلامًا زكيًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص71، تحت «المتشابه اللفظي».","url":""}]},{"id":"s3-147","number":147,"surah":3,"verses":[47],"references":[{"surah":3,"verses":[47]}],"verseLabel":"آل عمران: 47","question":"لماذا زادت مريم في سورتها ﴿ولم أك بغيًا﴾، ولم تذكرها في آل عمران؟","answer":"ذُكرت في سورة مريم لأن الخطاب هناك مباشر والموقف أدعى لدفع تهمة الفاحشة، أما آل عمران فقد سبق فيها تطهير مريم واصطفاؤها فاستغنى السياق عن التصريح.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص71–72، تحت «المتشابه اللفظي».","url":""}]},{"id":"s3-148","number":148,"surah":3,"verses":[47],"references":[{"surah":3,"verses":[47]}],"verseLabel":"آل عمران: 47","question":"لماذا جاء جواب البشارة في آل عمران باسم الجلالة ﴿الله يخلق ما يشاء﴾، وفي سورة مريم باسم الرب ﴿هو عليّ هين﴾؟","answer":"جاء ﴿قال ربك هو علي هين﴾ في مريم لموافقة سياق الرحمة واللطف وتكرر اسم الرب منذ أول القصة، أما آل عمران فصرحت باسم الجلالة ﴿الله يخلق ما يشاء﴾ لأنها تقرر التوحيد وتنسب الخلق إلى الله وحده في مواجهة الغلو في عيسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص76، تحت «علة إيثار التعبير بالربوبية».","url":""}]},{"id":"s3-149","number":149,"surah":3,"verses":[48],"references":[{"surah":3,"verses":[48]}],"verseLabel":"آل عمران: 48","question":"لماذا جُمعت الكتب في ﴿ويعلمه الكتاب والحكمة والتوراة والإنجيل﴾؟","answer":"جمعت الآية عطايا علمية متغايرة: الكتابة أو جنس الكتب، والحكمة وهي العلم المصيب الباعث على العمل، ثم التوراة كتاب بني إسرائيل والإنجيل المنزل على عيسى؛ وخص الكتابان بالذكر من جنس الكتب لعظيم فضلهما، فجاء الترتيب متدرجًا من العام إلى الخاص أو بحسب سبق التعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص100–101، تحت «بلاغة تعدد المفاعيل وسر ترتيبها».","url":""}]},{"id":"s3-150","number":150,"surah":3,"verses":[49],"references":[{"surah":3,"verses":[49]}],"verseLabel":"آل عمران: 49","question":"لماذا كانت آية عيسى أن يصنع من الطين كهيئة الطير ثم ينفخ فيه؟","answer":"جاءت الآية في صورة محسوسة للخلق من مادة جامدة ثم ظهور الحياة فيها، وهي من جنس ما اشتهر به زمن عيسى من الطب مع تجاوزها قدرة البشر؛ وقيّدها الوحي بـ﴿بِإِذْنِ اللَّهِ﴾ حتى لا تنسب القدرة إليه استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص107–108، تحت «بلاغة كمال الاتصال ولطائف التراكيب في بسط المعجزة».","url":""}]},{"id":"s3-151","number":151,"surah":3,"verses":[49],"references":[{"surah":3,"verses":[49]}],"verseLabel":"آل عمران: 49","question":"لماذا تكرر قيد ﴿بإذن الله﴾ في معجزات عيسى؟","answer":"كرر القيد مع الخوارق الكبرى لنزع أي توهم في استقلال عيسى بالخلق أو الإحياء؛ فالمعجزة تجري على يده والقدرة لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص109، تحت «بلاغة تكرار إذن الله تعالى».","url":""}]},{"id":"s3-153","number":153,"surah":3,"verses":[49],"references":[{"surah":3,"verses":[49]}],"verseLabel":"آل عمران: 49","question":"لماذا عُدَّ إخبارهم بما يأكلون وما يدخرون في بيوتهم آية؟","answer":"لأنه إخبار متكرر بغيب خاص لا تدركه المشاهدة ولا التخمين، فيقيم الحجة لمن عاينه، مع كونه دون الإحياء حتى تتنوع دلائل الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص110، تحت «بلاغة التعبير عن الإنباء، والادخار بالمضارع».","url":""}]},{"id":"s3-154","number":154,"surah":3,"verses":[50],"references":[{"surah":3,"verses":[50]}],"verseLabel":"آل عمران: 50","question":"ما دلالة قول عيسى عليه السلام: ﴿مُصَدِّقًا لِمَا بَيْنَ يَدَيَّ مِنَ التَّوْرَاةِ وَلِأُحِلَّ لَكُمْ بَعْضَ الَّذِي حُرِّمَ عَلَيْكُمْ﴾؟","answer":"جمع بين تصديق التوراة وتحليل بعض المحرمات ليقرر أنه مؤمن بأصلها ومحيٍ لأحكامها، وأن النسخ الجزئي لا يناقض التصديق؛ فكل حكم حق في زمنه، وكان رفع بعض ما حرم عليهم عقوبةً تخفيفًا وآية على رسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص116، تحت «سر اختصاص التوراة بالذكر».","url":""}]},{"id":"s3-155","number":155,"surah":3,"verses":[50],"references":[{"surah":3,"verses":[50]}],"verseLabel":"آل عمران: 50","question":"ما سرّ التعبير في قوله تعالى: ﴿بعض الذي حرم عليكم﴾ ولم يعيّن المحرمات؟","answer":"قال ﴿بعض﴾ لأن النسخ لا يرفع جميع الأحكام بل يقع في بعضها بحسب الأزمنة والأحوال، وأبهم فاعل ﴿حرم﴾ ليشمل ما حرموه على أنفسهم ونسبوه إلى الله وما حرمه الله عليهم عقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص118، تحت «قصدية تبعيض المحرم».","url":""}]},{"id":"s3-156","number":156,"surah":3,"verses":[50],"references":[{"surah":3,"verses":[50]}],"verseLabel":"آل عمران: 50","question":"لماذا كرر ﴿فاتقوا الله وأطيعون﴾ بعد ذكر الآية والمعجزة؟","answer":"جاءت الفاء لتفرع النتيجة على الآيات: فإذا ثبتت رسالته وجب اتقاء غضب الله وطاعة عيسى فيما بلغه عنه؛ فامتثال أمر الله ورسوله هو الغاية من إرسال الرسل وتأييدهم بالمعجزات.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص119–121، تحت «دلالة الفاء وفعلي الأمر في جملة الفاصلة».","url":""}]},{"id":"s3-157","number":157,"surah":3,"verses":[51],"references":[{"surah":3,"verses":[51]}],"verseLabel":"آل عمران: 51","question":"ما دلالة قول عيسى عليه السلام: ﴿إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ﴾؟","answer":"أعلن عيسى أن الله ربه ورب قومه ليقرر اشتراكهم جميعًا في العبودية، وينفي عن نفسه دعوى الربوبية والألوهية، ثم فرع ﴿فاعبدوه﴾ على ذلك: ما دام هو الرب وحده فالعبادة له وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص121–122، تحت «بلاغة الاحتراس في قوله: ﴿إن الله ربي وربكم فاعبدوه﴾».","url":""}]},{"id":"s3-158","number":158,"surah":3,"verses":[51],"references":[{"surah":3,"verses":[51]}],"verseLabel":"آل عمران: 51","question":"لماذا سمّى عبادة الله ﴿صراطًا مستقيمًا﴾؟","answer":"شُبهت عبادة الله وحده بطريق مستقيم يوصل إلى الغاية من غير انحراف؛ فالتوحيد منهج سير، لا فكرة مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص122–125، تحت «بلاغة التشبيه التمثيلي في الفاصلة».","url":""}]},{"id":"s3-159","number":159,"surah":3,"verses":[52],"references":[{"surah":3,"verses":[52]}],"verseLabel":"آل عمران: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما أحس عيسى منهم الكفر﴾، وهل يُحَسّ الكفر بالحواس؟","answer":"الكفر لا يحس بالحواس، فاستعير ﴿أحس﴾ للعلم اليقيني القريب من المشاهدة؛ واللفظ أنسب من ﴿علم﴾ أو ﴿وجد﴾ لأنه يصور استشعار عيسى ما أخفاه القوم من الكفر والعداوة والمكر قبل أن يعلنوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص125–126، تحت «بلاغة التعبير بقوله: ﴿فلما أحس عيسى منهم الكفر﴾ وتكاتف الأساليب البلاغية في إثراء المعنى».","url":""}]},{"id":"s3-160","number":160,"surah":3,"verses":[52],"references":[{"surah":3,"verses":[52]}],"verseLabel":"آل عمران: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿من أنصاري إلى الله﴾، دون أن يقال: من أنصار الله؟","answer":"﴿إلى﴾ تجعل النصرة متجهة إلى الله ودينه؛ أي من يضم نصرته إليّ في الطريق إلى إقامة أمر الله، لا أن الله محتاج إلى ناصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص127، تحت «بيان الإطناب في قوله: ﴿إلى الله﴾».","url":""}]},{"id":"s3-161","number":161,"surah":3,"verses":[52],"references":[{"surah":3,"verses":[52]}],"verseLabel":"آل عمران: 52","question":"لماذا أجاب الحواريون ﴿نحن أنصار الله﴾ فغيّروا صيغة سؤال عيسى؟","answer":"قالوا ﴿نحن أنصار الله﴾ بدل الاكتفاء بـ﴿نحن﴾ أو قولهم أنصارك؛ ليؤكدوا فورًا ثباتهم ورغبتهم في نصرة الدين، وليقرروا أن نصرة عيسى الرسول هي في حقيقتها نصرة لله ودعوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص126–127، تحت «بلاغة تكرار لفظ النصرة».","url":""}]},{"id":"s3-162","number":162,"surah":3,"verses":[52],"references":[{"surah":3,"verses":[52]}],"verseLabel":"آل عمران: 52","question":"ما دلالة قول الحواريين: ﴿آمَنَّا بِاللَّهِ﴾ ثم طلبهم الشهادة بأنهم مسلمون؟","answer":"أعلنوا ﴿آمنا بالله﴾ بالفعل لتجدد إيمانهم، ثم قالوا ﴿واشهد بأنا مسلمون﴾ بالجملة الاسمية المؤكدة لإثبات دوام انقيادهم وثباتهم على الإسلام، فجعلوا عيسى شاهدًا على صدق نصرتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص128، تحت «بلاغة عطف الإنشاء على الخبر في الفاصلة».","url":""}]},{"id":"s3-163","number":163,"surah":3,"verses":[53],"references":[{"surah":3,"verses":[53]}],"verseLabel":"آل عمران: 53","question":"لماذا قدّم الحواريون ﴿آمنا بما أنزلت﴾ على ﴿واتبعنا الرسول﴾؟","answer":"قدموا الإيمان بالوحي لأنه أصل العلم والتصديق، ثم عطفوا عليه اتباع الرسول بوصفه أثر ذلك الإيمان في العمل؛ فالإيمان الصحيح يستلزم الاتباع ولا يبقى دعوى مجملة بلا سلوك.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص135، تحت «سر تقديم الإيمان على الاتباع».","url":""}]},{"id":"s3-164","number":164,"surah":3,"verses":[53],"references":[{"surah":3,"verses":[53]}],"verseLabel":"آل عمران: 53","question":"ما سرّ قولهم: ﴿وَاتَّبَعْنَا الرَّسُولَ﴾ دون ذكر اسم عيسى؟","answer":"قالوا ﴿الرَّسُولَ﴾ لإبراز الصفة التي من أجلها وجب اتباع عيسى، لا لمجرد تعريف شخصه؛ فاتباعهم استجابة لرسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص138، تحت «الرَّسول والنَّبي».","url":""}]},{"id":"s3-165","number":165,"surah":3,"verses":[53],"references":[{"surah":3,"verses":[53]}],"verseLabel":"آل عمران: 53","question":"لماذا طلبوا ﴿فاكتبنا مع الشاهدين﴾ لا: واجعلنا من المؤمنين؟","answer":"طلبوا ﴿فاكتبنا﴾ أي أثبتنا على الإيمان وأدخلنا في زمرة الشاهدين، وهي منزلة تتجاوز مجرد دعوى الإيمان إلى أداء الشهادة للرسل بالصدق؛ والفاء تفيد استعجال هذا الخير بعد سرعة استجابتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص136، تحت «بلاغة الكناية في لفظة الكتابة».","url":""}]},{"id":"s3-166","number":166,"surah":3,"verses":[53],"references":[{"surah":3,"verses":[53]}],"verseLabel":"آل عمران: 53","question":"من هم ﴿الشاهدون﴾ الذين رغب الحواريون أن يُكتبوا معهم؟","answer":"هم الأنبياء وأتباعهم الصادقون الذين يشهدون للرسل بأنهم بلغوا الحق، ويشهدون على أقوامهم بما كان منهم من إيمان أو جحود؛ فسأل الحواريون أن يلحقوا بهذه الزمرة المؤدية للشهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص134، تحت «الموجب من تفرع الدعاء على دعاء آخر».","url":""}]},{"id":"s3-167","number":167,"surah":3,"verses":[54],"references":[{"surah":3,"verses":[54]}],"verseLabel":"آل عمران: 54","question":"لماذا عبّر عن تدبير أعداء عيسى وتدبير الله بلفظ واحد: ﴿ومكروا ومكر الله﴾؟","answer":"سُمّي تدبير الجزاء مكرًا مشاكلةً لفعلهم؛ فمكرهم خفي لإبطال الحق، وتدبير الله عدل يقلب كيدهم عليهم، ولا يستويان في الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص142، تحت «لفظ المكر بين الحقيقة والمجاز المرسل».","url":""}]},{"id":"s3-169","number":169,"surah":3,"verses":[54],"references":[{"surah":3,"verses":[54]}],"verseLabel":"آل عمران: 54","question":"لماذا ختمت الآية بـ﴿والله خير الماكرين﴾؟","answer":"ختم بـ﴿والله خير الماكرين﴾ ليقرر أن تدبير الله أقوى وأنفذ من تدبيرهم، فقد أبطل كيدهم وجعل هلاك مكرهم في تدبيرهم نفسه، ومكره سبحانه خير وعدل لا يلحقه وصف السوء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص143–144، تحت «المكر والكيد».","url":""}]},{"id":"s3-170","number":170,"surah":3,"verses":[54],"references":[{"surah":3,"verses":[54]}],"verseLabel":"آل عمران: 54","question":"كيف يوصف تدبير الله بالمكر مع أن المكر مذموم في البشر؟","answer":"سمي الجزاء من جنس فعلهم مكرًا للمشاكلة: هم دبروا خفيةً لإبطال الحق ظلمًا، والله أحاط بكيدهم وردّه عليهم عدلًا؛ فالاشتراك في اللفظ لا في الحقيقة والحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص142–143، تحت «الدلالة القرآنية للفظة المكر».","url":""}]},{"id":"s3-171","number":171,"surah":3,"verses":[55],"references":[{"surah":3,"verses":[55]}],"verseLabel":"آل عمران: 55","question":"ما سرّ التعبير في قوله تعالى لعيسى ﴿إني متوفيك ورافعك إليّ﴾، وقدّم التوفي على الرفع؟","answer":"لا يلزم من تقديم ﴿متوفيك﴾ وقوع التوفي قبل الرفع؛ فالواو لا تقتضي الترتيب. وعلى وجه التقديم والتأخير يكون المعنى: رافعك إلي ومطهرك من الكافرين الآن، ثم متوفيك بعد نزولك في آخر الزمان، مع بقاء وجوه أخرى لمعنى التوفي كالقبض أو النوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص149، تحت «وجه تفسير التوفي على طريق التقديم والتأخير».","url":""}]},{"id":"s3-172","number":172,"surah":3,"verses":[55],"references":[{"surah":3,"verses":[55]}],"verseLabel":"آل عمران: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿ورافعك إليّ﴾ مع تنزّه الله عن المكان؟","answer":"﴿إِلَيَّ﴾ تفيد رفع عيسى إلى جهة التشريف والقرب والموضع الذي اختاره الله له، ولا تقتضي حلول الله في مكان؛ فالله منزه عن المكان والحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص144–147، تحت «عناية من الله تعالى، ورد لكيد الكافرين: رفع عيسى».","url":""}]},{"id":"s3-173","number":173,"surah":3,"verses":[55],"references":[{"surah":3,"verses":[55]}],"verseLabel":"آل عمران: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿ومطهرك من الذين كفروا﴾، فجعل النجاة منهم تطهيرًا؟","answer":"عبّر عن تخليص عيسى من الكافرين بالتطهير كنايةً عن إخراجه سالمًا من بينهم؛ لأن مخالطتهم وصحبتهم بمنزلة الدنس، وفي اللفظ تشريف له ورفع لمرتبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص150، تحت «إيثار لفظ التطهير على التخليص».","url":""}]},{"id":"s3-174","number":174,"surah":3,"verses":[55],"references":[{"surah":3,"verses":[55]}],"verseLabel":"آل عمران: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿وجاعل الذين اتبعوك فوق الذين كفروا﴾، دون أن يقال: غالبين لهم؟","answer":"اختيرت ﴿فوق﴾ لأنها أوسع من مجرد الغلبة؛ فهي تشمل علو أتباع عيسى في الإيمان والإخلاص والحجة والبرهان، وتشمل ما يظهر لهم في الدنيا من عزة وقوة ونصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص151، تحت «علة التعبير بلفظ الفوقية»","url":""}]},{"id":"s3-175","number":175,"surah":3,"verses":[55],"references":[{"surah":3,"verses":[55]}],"verseLabel":"آل عمران: 55","question":"لماذا قيّد الفوقية بـ﴿إلى يوم القيامة﴾؟","answer":"قُيدت الفوقية إلى يوم القيامة لأن هذا هو أمد الجعل المتعلق بأحوال الدنيا؛ ولا يفيد القيد أن الكافرين يخرجون بعدها من الذلة، بل ينتقل الأمر إلى حكم الله وجزائه يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص152، تحت «دلالة الغاية في جعل الفوقية».","url":""}]},{"id":"s3-176","number":176,"surah":3,"verses":[55],"references":[{"surah":3,"verses":[55]}],"verseLabel":"آل عمران: 55","question":"لماذا انتقل من خطاب عيسى إلى خطاب الفريقين في ﴿ثم إليّ مرجعكم﴾؟","answer":"التفت من ذكر الفريقين بضمير الغيبة إلى خطابهم مباشرة لأن المرجع والحكم يشملانهم جميعًا؛ والمواجهة بالخطاب أبلغ في تنبيههم وتقوية الوعد للمؤمن والوعيد للكافر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص152–153، تحت «بلاغة الالتفات في الآية».","url":""}]},{"id":"s3-177","number":177,"surah":3,"verses":[56],"references":[{"surah":3,"verses":[56]}],"verseLabel":"آل عمران: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿فأعذبهم عذابًا شديدًا في الدنيا والآخرة﴾، وكيف يكون العذاب في الدنيا؟","answer":"عذابهم في الدنيا يكون بالقتل والسبي والجزية والصغار، وفي الآخرة بالنار؛ وأكد الفعل بالمصدر ووصف العذاب بالشدة لتعظيمه وبيان شدته في الدارين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص159، تحت «صور توكيد شدة العذاب في الآية».","url":""}]},{"id":"s3-178","number":178,"surah":3,"verses":[56],"references":[{"surah":3,"verses":[56]}],"verseLabel":"آل عمران: 56","question":"لماذا ختم شأن الكافرين بـ﴿وما لهم من ناصرين﴾ بصيغة الجمع؟","answer":"جُمع ﴿ناصرين﴾ لمواجهة فرض كثرة الأنصار: فمهما كثر مناصروهم لن يدفعوا عنهم العذاب، وزادت ﴿من﴾ النفي استغراقًا حتى لا يثبت لهم ناصر واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص160، تحت «دلالة المقابلة والتوكيد في بناء الفاصلة».","url":""}]},{"id":"s3-179","number":179,"surah":3,"verses":[56,57],"references":[{"surah":3,"verses":[56,57]}],"verseLabel":"آل عمران: 56–57","question":"ما سرّ التعبير في قوله تعالى في الكافرين ﴿فأعذبهم﴾ بضمير المتكلم، ثم قال في المؤمنين ﴿فيوفيهم أجورهم﴾ بضمير الغائب، دون أن يقال: فأوفيهم؟","answer":"في قراءة حفص وقع التفات من المتكلم في ﴿فأعذبهم﴾ إلى الغائب في ﴿فيوفيهم﴾ للتنوع في الأسلوب وزيادة الفصاحة وقوة البشارة والنذارة، وقرأ الجمهور ﴿فنوفيهم﴾ بنون العظمة الملائمة لتعظيم جزاء المؤمن العامل.","sources":[{"label":"فاضل السامرائي، برنامج «لمسات بيانية»؛ منقول في Quranpedia، ملاحظة 48962","url":"https://quranpedia.net/note/48962"}]},{"id":"s3-180","number":180,"surah":3,"verses":[57],"references":[{"surah":3,"verses":[57]}],"verseLabel":"آل عمران: 57","question":"لماذا قابل الكافرين بـ﴿الذين آمنوا وعملوا الصالحات﴾ ولم يكتف بالإيمان؟","answer":"لم يكتف بالإيمان لأن الإيمان الكامل يصدقه العمل الصالح بفعل الأوامر وترك النواهي؛ فجاءت التوفية جزاءً لإيمان ظهر أثره في الطاعة والسلوك.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص158، تحت «وجه المقابلة بين الآيتين».","url":""}]},{"id":"s3-181","number":181,"surah":3,"verses":[57],"references":[{"surah":3,"verses":[57]}],"verseLabel":"آل عمران: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿فيوفيهم أجورهم﴾، فصوّر الثواب أجرًا يُستوفى؟","answer":"سمي الثواب أجرًا لأنه جزاء نافع على العمل، وقيل ﴿فيوفيهم﴾ ليؤكد أن الله يؤدي هذا الجزاء كاملًا من غير نقص؛ ففي التعبير ضمان تمام النفع وعدل المكافأة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص448، تحت «أصل الدلالة في التوفية، في قوله: ﴿فيوفيهم أجورهم﴾».","url":""}]},{"id":"s3-182","number":182,"surah":3,"verses":[57],"references":[{"surah":3,"verses":[57]}],"verseLabel":"آل عمران: 57","question":"لماذا خُتمت الآية بـ﴿والله لا يحب الظالمين﴾ لا: والله يحب المؤمنين؟","answer":"خُتم بنفي محبة الظالمين لأن السياق يقابل جزاء الفريقين: فعدم محبتهم يستلزم كراهتهم وإنالتهم العذاب، كما تستلزم توفية المؤمنين أجورهم محبتهم؛ وفي ذلك إعلان أن الكفر والظلم قرينان وأن الجزاء عدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص161، تحت «علة التعبير بلفظ ﴿الظالمين﴾».","url":""}]},{"id":"s3-183","number":183,"surah":3,"verses":[58],"references":[{"surah":3,"verses":[58]}],"verseLabel":"آل عمران: 58","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك نتلوه عليك من الآيات والذكر الحكيم﴾ بالإشارة إلى البعيد؟","answer":"أشير بـ﴿ذلك﴾ إلى مجموع ما سبق من أخبار عيسى وآل عمران، واستعملت إشارة البعيد لتعظيم هذا الوحي ورفع منزلته، مع استحضار القصص السابقة كأنها أمر مشاهد حاضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص163–164، تحت «دلالة البدء باسم الإشارة».","url":""}]},{"id":"s3-184","number":184,"surah":3,"verses":[58],"references":[{"surah":3,"verses":[58]}],"verseLabel":"آل عمران: 58","question":"لماذا عطف ﴿الذكر الحكيم﴾ على ﴿الآيات﴾، وهما من القرآن نفسه؟","answer":"عطفهما لاختلاف الاعتبار أو المحتمل: فالآيات قد تكون آيات القرآن أو دلائل صدق الرسالة، والذكر الحكيم قد يراد به القرآن من جهة كونه ذكرًا محكمًا، أو اللوح المحفوظ؛ فليس العطف تكرارًا محضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص164–165، تحت «وجه عطف الذكر الحكيم على الآيات».","url":""}]},{"id":"s3-185","number":185,"surah":3,"verses":[58],"references":[{"surah":3,"verses":[58]}],"verseLabel":"آل عمران: 58","question":"لماذا وُصف الذكر بأنه ﴿حكيم﴾، والحكمة وصف للعاقل؟","answer":"وُصف الذكر بصفة من صدر عنه، وهو الله الحكيم، أو صُوّر كأنه ينطق بالحكمة لما اشتمل عليه منها؛ ففي الوجه الأول إسناد الصفة إلى الكلام لصلته بمتكلمه، وفي الثاني تصوير للذكر كأنه حكيم ينطق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص165، تحت عنوان «بيان الاستعارة، أو المجاز العقلي في لفظ (الحكيم)»","url":""}]},{"id":"s3-186","number":186,"surah":3,"verses":[59],"references":[{"surah":3,"verses":[59]}],"verseLabel":"آل عمران: 59","question":"لماذا شبّه خلق عيسى بخلق آدم مع أن حال آدم أعجب؟","answer":"لأن الغرض إلزام من جعل عدم الأب دليل ألوهية: فآدم أولى بهذا الوهم إذ خُلق بلا أب ولا أم، ومع ذلك أقروا ببشريته؛ فالأعجب صار حجة على الأدنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص166–168، تحت «مثل عيسى كمثل آدم، كلاهما خُلق بالنفخة الإلهية المعجزة».","url":""}]},{"id":"s3-187","number":187,"surah":3,"verses":[59],"references":[{"surah":3,"verses":[59]}],"verseLabel":"آل عمران: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿خلقه من تراب﴾، دون أن يقال: من طين؟","answer":"عدل إلى التراب لأنه أدنى عنصري الطين وأبعد عن هيئة الجسد الحي، فكان أبلغ في بيان القدرة وأمعن في تصغير شأن من ادعيت له الألوهية، وأحكم في الاحتجاج بخلق آدم الأعجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص170–171، تحت «نكتة العدول عن لفظ الطين إلى ذكر التراب».","url":""}]},{"id":"s3-188","number":188,"surah":3,"verses":[59],"references":[{"surah":3,"verses":[59]}],"verseLabel":"آل عمران: 59","question":"لماذا جاء ﴿ثم قال له كن فيكون﴾ بـ﴿ثم﴾ مع أن أمر الله لا تراخي فيه؟","answer":"﴿ثم﴾ هنا لترتيب الإخبار والانتقال إلى بيان نفاذ القدرة، لا للدلالة على مهلة في الخلق؛ وشبهت سرعة تأثير القدرة بأمر مطاع يقع فورًا من غير إبطاء ولا توقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص171، تحت «بلاغة الاستعارة التمثيلية».","url":""}]},{"id":"s3-189","number":189,"surah":3,"verses":[59],"references":[{"surah":3,"verses":[59]}],"verseLabel":"آل عمران: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿فيكون﴾ بالمضارع، مع أن خلق آدم قد وقع؟","answer":"جاء ﴿فَيَكُونُ﴾ بالمضارع حكايةً لنتيجة الأمر الإلهي واستحضارًا لسرعة التكوين، كما يقرر سنةً عامة: كلما قضى الله أمرًا قال له كن فيكون؛ فلا يدل على أن خلق آدم ما زال متكررًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص171، تحت «دلالة التعبير بالفعل المضارع ﴿فيكون﴾».","url":""}]},{"id":"s3-190","number":190,"surah":3,"verses":[60],"references":[{"surah":3,"verses":[60]}],"verseLabel":"آل عمران: 60","question":"لماذا جاء ﴿الحق من ربك﴾ جملة قصيرة بعد تفصيل قصة عيسى؟","answer":"جاءت جملة موجزة فاصلة بعد التفصيل لتلخص الحكم: ما قصه الله في شأن عيسى هو الحق الثابت الذي لا مجال للشك فيه؛ وفيها تثبيت للنبي ﷺ وإغلاق لباب جدال المعاندين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص174–175، تحت «تعدد صور تأكيد الحق في الآية».","url":""}]},{"id":"s3-192","number":192,"surah":3,"verses":[60],"references":[{"surah":3,"verses":[60]}],"verseLabel":"آل عمران: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تكن من الممترين﴾ للنبي ﷺ مع يقينه؟","answer":"النهي موجه إليه والمراد تثبيته وقطع طمع المجادلين، كما يتضمن تعليم الأمة ألا تتردد بعد قيام البرهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص173–174، تحت «الخطاب للنبي ﷺ والمراد أمته».","url":""}]},{"id":"s3-193","number":193,"surah":3,"verses":[60],"references":[{"surah":2,"verses":[147]},{"surah":3,"verses":[60]},{"surah":6,"verses":[114]},{"surah":10,"verses":[94]}],"verseLabel":"آل عمران: 60؛ البقرة: 147؛ الأنعام: 114؛ يونس: 94","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران ﴿فلا تكن من الممترين﴾، وقوله تعالى في نظائرها ﴿فلا تكونن من الممترين﴾ بنون التوكيد؟","answer":"جاءت ﴿فلا تكن﴾ في آل عمران على أصل الصيغة بلا نون توكيد، أما في البقرة فتكرر التركيب في السياق فناسب الازدواج والتقوية أن يقال ﴿فلا تكونن﴾ بنون التوكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص175، تحت «توجيه المتشابه اللفظي».","url":""}]},{"id":"s3-194","number":194,"surah":3,"verses":[61],"references":[{"surah":3,"verses":[61]}],"verseLabel":"آل عمران: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن حاجّك فيه من بعد ما جاءك من العلم﴾ فسمّى الوحي علمًا؟","answer":"سمي الوحي علمًا لأنه بينات ودليل يوجب اليقين بحقيقة عيسى، ويجوز أن يكون من إطلاق المصدر على المعلوم؛ و﴿العلم﴾ للعهد، أي الدليل الذي قرر خلق عيسى ونفى ألوهيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص179، تحت «علة التعبير بلفظة ﴿العلم﴾»","url":""}]},{"id":"s3-195","number":195,"surah":3,"verses":[61],"references":[{"surah":3,"verses":[61]}],"verseLabel":"آل عمران: 61","question":"لماذا بدأ في المباهلة بـ﴿أبناءنا﴾ ثم ﴿نساءنا﴾ ثم ﴿أنفسنا﴾؟","answer":"بدأ بالأبناء لأنهم أعز ما يدافع عنه المرء ويفديه، ثم النساء، وختم بالأنفس التي تبذل دونهما؛ فجاء الترتيب متصاعدًا من الفرع إلى الأصل ودالًا على تمام اليقين والاستعداد للمباهلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص180–181، تحت «دلالة الترتيب في الدعوة».","url":""}]},{"id":"s3-196","number":196,"surah":3,"verses":[61],"references":[{"surah":3,"verses":[61]}],"verseLabel":"آل عمران: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنفسنا وأنفسكم﴾ مع أن الإنسان لا يدعو نفسه؟","answer":"أطلقت الأنفس على الأقربين وبني العم لأن القرابة وأخوة الدين تجري الواحد من الجماعة مجرى نفس الآخر، والمتكلم نفسه حاضر داخل الجمع فلا يحتاج إلى أن يقول: ندعو فلانًا ونفسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص181، تحت «علة ضم الأبناء والنساء إلى النفس».","url":""}]},{"id":"s3-197","number":197,"surah":3,"verses":[61],"references":[{"surah":3,"verses":[61]}],"verseLabel":"آل عمران: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم نبتهل﴾ بعد ﴿تعالوا ندع﴾؟","answer":"رتبت ﴿ثم﴾ الابتهال بعد الدعوة والاجتماع: يحضر الفريقان أهليهما ويعلن كل منهما دعواه، ثم يتضرعون إلى الله ويجتهدون في طلب لعن الكاذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص178، تتمة «شرح المفردات»، مدخل ﴿نبتهل﴾؛ وتحت «المباهلة درس للأمة لإثبات الحق أمام المكابرين».","url":""}]},{"id":"s3-199","number":199,"surah":3,"verses":[62],"references":[{"surah":3,"verses":[62]}],"verseLabel":"آل عمران: 62","question":"لماذا افتتحت الآية بـ﴿إن هذا لهو القصص الحق﴾ بثلاثة مؤكدات؟","answer":"أكدت الجملة بإن واللام وضمير الفصل، مع تعريف الطرفين، لأن المخاطبين منكرون مضطربو الاعتقاد؛ فاجتمع التوكيد والقصر لإثبات أن هذا وحده هو القصص الحق في شأن عيسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص185–186، تحت «تعدد صيغ التوكيد في قوله: ﴿إن هذا لهو القصص الحق﴾».","url":""}]},{"id":"s3-200","number":200,"surah":3,"verses":[62],"references":[{"surah":3,"verses":[62]}],"verseLabel":"آل عمران: 62","question":"لماذا سمّى خبر عيسى ﴿القصص الحق﴾ لا الخبر الحق؟","answer":"سمي قصصًا لأنه خبر متتابع يتتبع الوقائع والآثار، ووصف بالحق لأن الرواية القرآنية المطابقة للواقع هي الحق في شأن عيسى، بخلاف القصص الذي نسجه أهل الغلو.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص184–185، تحت «شرح المفردات» في بيان ﴿القصص الحق﴾.","url":""}]},{"id":"s3-201","number":201,"surah":3,"verses":[62],"references":[{"surah":3,"verses":[62]}],"verseLabel":"آل عمران: 62","question":"ما سرّ التعبير في قوله تعالى: ﴿وما من إله إلا الله﴾ بزيادة ﴿من﴾؟","answer":"زيدت ﴿من﴾ في سياق النفي لتجعل الاستغراق نصًا صريحًا: لا يوجد أي إله أصلًا إلا الله، وفي ذلك رد قاطع على التثليث وعلى كل من يدعي إلهًا غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص187، تحت «دلالة ﴿من﴾ في قوله تعالى: ﴿وما من إله إلا الله﴾».","url":""}]},{"id":"s3-202","number":202,"surah":3,"verses":[62],"references":[{"surah":3,"verses":[62]}],"verseLabel":"آل عمران: 62","question":"لماذا خُتمت الحجة بـ﴿وإن الله لهو العزيز الحكيم﴾؟","answer":"ختم بالعزيز الحكيم لقصر كمال العزة والحكمة على الله؛ فعزته قاهرة لا يلحقها عجز، وهي مقرونة بالحكمة فلا تؤول إلى ظلم، وحكمته نافذة لا يعوقها شيء، وفي ذلك نفي لألوهية المسيح المحتاج.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص189–190، تحت «دلالة اقتران ﴿العزيز﴾ بـ﴿الحكيم﴾ في الفاصلة».","url":""}]},{"id":"s3-203","number":203,"surah":3,"verses":[63],"references":[{"surah":3,"verses":[63]}],"verseLabel":"آل عمران: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن تولوا فإن الله عليم بالمفسدين﴾ فوضع المظهر موضع الضمير؟","answer":"أظهر اسم الله واسم المفسدين بدل الضمير لتربية المهابة وتسجيل أن توليهم نفسه فساد، مع تأكيد أن علم الله محيط بهم وثابت وأن الوعيد لازم لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص191–192، تحت «نكتة وضع المظهر موضع المضمر في قوله تعالى: ﴿فإن الله عليم بالمفسدين﴾».","url":""}]},{"id":"s3-204","number":204,"surah":3,"verses":[63],"references":[{"surah":3,"verses":[63]}],"verseLabel":"آل عمران: 63","question":"لماذا سمّى المتولين عن هذه الحجة ﴿المفسدين﴾؟","answer":"لأن التولي عن هذه الحجج والإعراض عن التوحيد إفساد للدين والاعتقاد، يفضي إلى فساد النفس والعالم؛ فوصفهم بالمفسدين يبين حقيقة إعراضهم وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص192، تحت عنوان «نكتة وضع المظهر موضع المضمر في قوله تعالى: ﴿فإن الله عليم بالمفسدين﴾»","url":""}]},{"id":"s3-205","number":205,"surah":3,"verses":[64],"references":[{"surah":3,"verses":[64]}],"verseLabel":"آل عمران: 64","question":"لماذا نادى النصارى واليهود بـ﴿يا أهل الكتاب﴾ في مقام الاحتجاج؟","answer":"نودوا بأحسن ألقابهم تطييبًا لقلوبهم واستدعاءً لانتباههم، وفي وصفهم بأهل الكتاب إلزام لهم بما في كتبهم؛ فخطاب الإنصاف والتشريف أدعى لقبول الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص197–198، تحت «دلالة التعبير بأهل الكتاب في قوله: ﴿يا أهل الكتاب تعالوا﴾».","url":""}]},{"id":"s3-206","number":206,"surah":3,"verses":[64],"references":[{"surah":3,"verses":[64]}],"verseLabel":"آل عمران: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿تعالوا إلى كلمة سواء بيننا وبينكم﴾، وكيف تكون الكلمة مكانًا يُؤتى إليه؟","answer":"صُورت الكلمة السواء كغاية يجتمع الخصمان عندها؛ فـ﴿تَعَالَوْا إِلَى﴾ دعوة إلى الإقبال عليها والالتقاء حولها، لا إتيان مكان حسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص199، تحت «بلاغة التمثيل في قوله: ﴿كلمة سواء بيننا وبينكم﴾».","url":""}]},{"id":"s3-207","number":207,"surah":3,"verses":[64],"references":[{"surah":3,"verses":[64]}],"verseLabel":"آل عمران: 64","question":"لماذا وصف الكلمة بأنها ﴿سواء﴾، ولم يقل: عادلة؟","answer":"وصفت بسواء لأنها كلمة مستوية عادلة تقع نَصَفًا بين الفريقين ولا تختص بمصلحة أحدهما؛ فهي تجمع معنى العدل والتساوي وكونها وسطًا مشتركًا، لا مجرد وصفها بالعدالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص199، تحت «بلاغة التمثيل في قوله: ﴿كلمة سواء بيننا﴾».","url":""}]},{"id":"s3-208","number":208,"surah":3,"verses":[64],"references":[{"surah":3,"verses":[64]}],"verseLabel":"آل عمران: 64","question":"لماذا فصّل الكلمة السواء في ثلاثة أمور: العبادة، والشرك، واتخاذ الأرباب؟","answer":"لأنها تغلق أبواب الانحراف كلها: إخلاص العبادة، ونفي الشريك، ونفي سلطة البشر الدينية التي تنازع حكم الله؛ فليست دعوة إلى شعار مجمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص199، تحت «تأكيد منطوق الألفاظ بمفهومها ولازمها».","url":""}]},{"id":"s3-209","number":209,"surah":3,"verses":[64],"references":[{"surah":3,"verses":[64]}],"verseLabel":"آل عمران: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿بعضنا بعضًا أربابًا﴾ مع أن المخاطبين لا يسمّون أحبارهم آلهة؟","answer":"لا يشترط أن يسموهم آلهة؛ فقد اتخذوهم أربابًا حين أطاعوهم طاعة دينية مطلقة فيما يحللون ويحرمون، وفرض المتبوع على التابع أمره ونهيه، فجعلوا للبشر حقًا من خصائص ربوبية الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص201، تحت «دلالة التعبير بصيغة الافتعال في قوله: ﴿ولا يتخذ بعضنا بعضًا أربابًا﴾».","url":""}]},{"id":"s3-210","number":210,"surah":3,"verses":[64],"references":[{"surah":3,"verses":[64]}],"verseLabel":"آل عمران: 64","question":"لماذا خُتمت الآية بـ﴿فقولوا اشهدوا بأنا مسلمون﴾ لا: فقاتلوهم؟","answer":"لأن المقام مقام دعوة وحجاج متدرج لا مقام قتال؛ فبعد البيان والمباهلة والدعوة إلى أصل مشترك، إن تولوا أعلن المسلمون ثباتهم على الحق وأشهدوهم عليه، لتقوم الحجة ويتميز موقف الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص201–202، تحت «براعة المبالغة في التعبير عن العلم بالشهادة».","url":""}]},{"id":"s3-211","number":211,"surah":3,"verses":[65],"references":[{"surah":3,"verses":[65]}],"verseLabel":"آل عمران: 65","question":"ما سرّ التعبير في قوله تعالى: ﴿لم تحاجّون في إبراهيم﴾، دون أن يقال: تختلفون فيه؟","answer":"قال ﴿تحاجون﴾ لأن كل فريق لم يقتصر على مخالفة الآخر، بل أقام دعوى وحجة يريد بها إثبات نسبة إبراهيم إليه ورد خصمه؛ غير أن حججهم باطلة غير مؤسسة، فالمحاجة أخص من الاختلاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص205–206، تحت «دلالة الاستفهام في قوله: ﴿لم تحاجون﴾».","url":""}]},{"id":"s3-212","number":212,"surah":3,"verses":[65],"references":[{"surah":3,"verses":[65]}],"verseLabel":"آل عمران: 65","question":"لماذا احتجّ بنزول التوراة والإنجيل من بعد إبراهيم؟","answer":"ذُكرت التوراة لإبطال قول اليهود، والإنجيل لإبطال قول النصارى؛ فكلا الكتابين نزل بعد إبراهيم، فلا يصح أن يُنسب إلى اليهودية أو النصرانية اللتين يدعيهما الفريقان.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص206، تحت عنوان «دلالة اللف والنشر في قوله: ﴿يا أهل الكتاب لم تحاجون في إبراهيم وما أنزلت التوراة والإنجيل إلا من بعده﴾»","url":""}]},{"id":"s3-213","number":213,"surah":3,"verses":[65],"references":[{"surah":3,"verses":[65]}],"verseLabel":"آل عمران: 65","question":"لماذا ختم الإنكار بـ﴿أفلا تعقلون﴾؟","answer":"ختم بـ﴿أفلا تعقلون﴾ لأن مجرد إعمال العقل يبطل دعواهم؛ فلا يعقل أن يكون إبراهيم يهوديًا أو نصرانيًا والكتابان اللذان نشأت عنهما التسميتان نزلا بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص207، تحت «التعريض بنفي العقل في قوله تعالى: ﴿أفلا تعقلون﴾».","url":""}]},{"id":"s3-214","number":214,"surah":3,"verses":[66],"references":[{"surah":3,"verses":[66]}],"verseLabel":"آل عمران: 66","question":"لماذا كرر ﴿ها أنتم هؤلاء﴾ في مقام التوبيخ؟","answer":"كررت هاء التنبيه لاستدعاء انتباههم بقوة إلى غرابة حالهم وطول لجاجهم؛ فكأنهم يواجهون أنفسهم بما فعلوا ويُنبهون إلى أمر كان عنادهم قد أعماهم عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص211–212، تحت «دلالات التركيب ﴿ها أنتم هؤلاء﴾».","url":""}]},{"id":"s3-215","number":215,"surah":3,"verses":[66],"references":[{"surah":3,"verses":[66]}],"verseLabel":"آل عمران: 66","question":"لماذا فرّق بين المحاجة فيما لهم به علم وما ليس لهم به علم؟","answer":"وبّخهم على انتقالهم من جدل له أصل في كتبهم إلى دعوى لا سند لها في شأن إبراهيم؛ فمن أخطأ مع علمه لا يُعذر إذا جادل فيما يجهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص210، تحت «مناسبة الآية لما قبلها».","url":""}]},{"id":"s3-216","number":216,"surah":3,"verses":[66],"references":[{"surah":3,"verses":[66]}],"verseLabel":"آل عمران: 66","question":"لماذا خُتمت الآية بـ﴿والله يعلم وأنتم لا تعلمون﴾؟","answer":"ختم بإثبات العلم المطلق لله ونفي العلم عنهم في شأن إبراهيم؛ فهو يعلم حقيقة الشرائع والأحوال، أما دعواهم فتحجبها الأهواء والجحود والحسد عن العلم الصحيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص213–214، تحت «دلالة حذف مفعول العلم في قوله: ﴿والله يعلم وأنتم لا تعلمون﴾».","url":""}]},{"id":"s3-217","number":217,"surah":3,"verses":[67],"references":[{"surah":3,"verses":[67]}],"verseLabel":"آل عمران: 67","question":"لماذا نفى عن إبراهيم اليهودية والنصرانية قبل إثبات الحنيفية والإسلام؟","answer":"بدأ بإبطال الدعويين المتنازعتين حتى يخلو الذهن من النسب المحدثة، ثم أثبت الوصف الأصيل الجامع: الميل عن الشرك والاستسلام لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص218، تحت «نكتة البدء بالنفي قبل الإثبات في قوله: ﴿ما كان إبراهيم﴾».","url":""}]},{"id":"s3-218","number":218,"surah":3,"verses":[67],"references":[{"surah":3,"verses":[67]}],"verseLabel":"آل عمران: 67","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكن كان حنيفًا مسلمًا﴾، وما الذي يضيفه ﴿حنيفًا﴾ إلى ﴿مسلمًا﴾؟","answer":"الحنيف يبين الميل عن الشرك والملل المحرفة، والمسلم يثبت الوجهة الإيجابية وهي الاستسلام لله؛ فالأول براءة والثاني ولاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص219، تحت «دلالات الأوصاف الموصوف بها إبراهيم».","url":""}]},{"id":"s3-219","number":219,"surah":3,"verses":[67],"references":[{"surah":3,"verses":[67]}],"verseLabel":"آل عمران: 67","question":"لماذا ختم وصف إبراهيم بـ﴿وما كان من المشركين﴾ بعد إثبات إسلامه؟","answer":"زيد نفي الشرك ليعم كل طوائفه ويقطع دعوى مشركي العرب أنهم على ملة إبراهيم؛ فالحنيف المسلم لا يجتمع معه شيء من الإشراك.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص220، تحت «دلالة العطف بالواو في قوله: ﴿وما كان من المشركين﴾».","url":""}]},{"id":"s3-220","number":220,"surah":3,"verses":[68],"references":[{"surah":3,"verses":[68]}],"verseLabel":"آل عمران: 68","question":"لماذا عبّر عن أحق الناس بإبراهيم بـ﴿أولى الناس بإبراهيم﴾؟","answer":"عبّر بأولى لأن القرب من إبراهيم درجات، وأحق الناس وأشدهم اتصالًا به من اتبع عقيدته وطاعته، لا من اكتفى بدعوى النسب أو الاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص225، تحت «براعة التضمين في قوله: ﴿إن أولى الناس بإبراهيم﴾».","url":""}]},{"id":"s3-221","number":221,"surah":3,"verses":[68],"references":[{"surah":3,"verses":[68]}],"verseLabel":"آل عمران: 68","question":"لماذا قدّم ﴿الذين اتبعوه﴾ على ﴿هذا النبي والذين آمنوا﴾؟","answer":"قدم أتباع إبراهيم لسبقهم في الوجود، ثم عطف هذا النبي والذين آمنوا تخصيصًا بعد تعميم وتشريفًا لهم وبيانًا أنهم أكمل الناس اتباعًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص226، تحت «بلاغة الإطناب في قوله: ﴿الذين اتبعوه وهذا النبي والذين آمنوا﴾».","url":""}]},{"id":"s3-222","number":222,"surah":3,"verses":[68],"references":[{"surah":3,"verses":[68]}],"verseLabel":"آل عمران: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿وهذا النبي﴾ باسم الإشارة لا باسمه؟","answer":"أشير إليه بـ﴿هذا﴾ لاستحضاره قريبًا معلومًا بين المخاطبين، وفي القرب تعظيم وتمييز، ثم جاء وصف النبي تشريفًا وبيانًا لعلو رتبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص225–226، تحت «دلالة اسم الإشارة ﴿وهذا﴾ في قوله: ﴿وهذا النبي﴾».","url":""}]},{"id":"s3-223","number":223,"surah":3,"verses":[68],"references":[{"surah":3,"verses":[68]}],"verseLabel":"آل عمران: 68","question":"لماذا ختمت الآية بـ﴿والله ولي المؤمنين﴾؟","answer":"في وصفهم بالمؤمنين بيان أن الإيمان سبب ولاية الله لهم، والوعد بنصرهم في الدنيا وفوزهم في الآخرة. واللفظ يشمل الأنبياء وأتباعهم من كل شريعة، فيرغّب في الإيمان الذي تنال به هذه الولاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص227، تحت عنوان «دلالة تخصيص المؤمنين في قوله: ﴿ولي المؤمنين﴾»","url":""}]},{"id":"s3-224","number":224,"surah":3,"verses":[69],"references":[{"surah":3,"verses":[69]}],"verseLabel":"آل عمران: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿ودّت طائفة من أهل الكتاب لو يضلونكم﴾ فجعل الإضلال أمنية؟","answer":"صيغ إضلال المؤمنين في صورة أمنية لأنه متعذر على المؤمنين الراسخين أو بالغ الصعوبة، ولفظ ﴿ودّت﴾ يكشف شدة رغبتهم وحقدهم وإن عجزوا عن تحقيق مرادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص231، تحت «دلالة التمني في قوله تعالى: ﴿ودت طائفة من أهل الكتاب﴾».","url":""}]},{"id":"s3-225","number":225,"surah":3,"verses":[69],"references":[{"surah":3,"verses":[69]}],"verseLabel":"آل عمران: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يضلون إلا أنفسهم﴾ مع أنهم يحاولون إضلال غيرهم؟","answer":"لأن مكرهم لا يضر المؤمن الراسخ، وإنما يرتد عليهم: فيهلكون أنفسهم باستحقاق غضب الله، ويزدادون ضلالًا كلما أعرضوا عن الحجج وبدلوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص232، تحت «توجيه معنى الإضلال في قوله: ﴿وما يضلون إلا أنفسهم﴾».","url":""}]},{"id":"s3-226","number":226,"surah":3,"verses":[69],"references":[{"surah":3,"verses":[69]},{"surah":6,"verses":[26,123]}],"verseLabel":"آل عمران: 69؛ الأنعام: 26؛ الأنعام: 123","question":"ما دلالة ختم الآية بقوله تعالى: ﴿وما يشعرون﴾، دون: وما يعلمون؟","answer":"في آل عمران: 69: اختير الشعور لأنه إدراك دقيق خفي قريب من الحس؛ وهم لا يدركون أدنى إدراك أن تدبيرهم يعود عليهم بالضرر ويضاعف ضلالهم وعذابهم.\n\nفي الأنعام: 26: الشعور إدراك دقيق لما قد يخفى، فنفى عنهم حتى الإحساس الأول بأن سعيهم يرتد هلاكًا عليهم؛ أما العلم فأعم وقد يأتي بعد نظر واستدلال. والفاصلة تناسب هلاكًا يصنعونه لأنفسهم وهم غافلون عن بداياته وعاقبته.\n\nفي الأنعام: 123: نُفي عنهم الشعور، وهو أدنى مراتب الإدراك، للمبالغة في غفلتهم عن رجوع المكر عليهم؛ فهم لا يحسون حتى أمارات عاقبته.","sources":[{"label":"[آل عمران: 69] موسوعة التفسير البلاغي، ج5، ص229–236","url":""},{"label":"[الأنعام: 26] موسوعة التفسير البلاغي، ج10، ص451–458","url":""},{"label":"[الأنعام: 123] موسوعة التفسير البلاغي، ج11، ص793–807","url":""}]},{"id":"s3-227","number":227,"surah":3,"verses":[70],"references":[{"surah":3,"verses":[70]}],"verseLabel":"آل عمران: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿لم تكفرون بآيات الله وأنتم تشهدون﴾؟","answer":"الاستفهام توبيخي يكشف التناقض بين معرفتهم دلائل الصدق وكفرهم بها؛ وجملة ﴿وأنتم تشهدون﴾ تجعل الجريمة عن علم لا عن خفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص238، تحت «دلالة الاستفهام في قوله: ﴿لم تكفرون﴾».","url":""}]},{"id":"s3-228","number":228,"surah":3,"verses":[70],"references":[{"surah":3,"verses":[70]}],"verseLabel":"آل عمران: 70","question":"لماذا اختير فعل ﴿تشهدون﴾ لا: تعلمون؟","answer":"اختير ﴿تشهدون﴾ لأنها أخص من مجرد العلم؛ فهي علم بالمشهود الحاضر مع إقرار وإثبات، فكأن ما في كتبهم وما رأوه من الدلائل شهادة قائمة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص250، تحت «توجيه المتشابه اللفظي بين قوله: ﴿وأنتم تعلمون﴾ وقوله: ﴿وأنتم لا تعلمون﴾ و﴿وأنتم تشهدون﴾».","url":""}]},{"id":"s3-229","number":229,"surah":3,"verses":[70,98,99],"references":[{"surah":3,"verses":[70,98,99]}],"verseLabel":"آل عمران: 70؛ آل عمران: 98–99","question":"لماذا جاء النداء في الآيتين 70–71 بلا ﴿قل﴾، ثم قيل في الآيتين 98–99 ﴿قل يا أهل الكتاب﴾؟","answer":"خوطبوا أولًا مباشرة لأن الحجة كانت قائمة عليهم في سياق المواجهة، فلما أعرضوا ولم يستجيبوا جيء لاحقًا بـ﴿قل﴾؛ إشعارًا ببعدهم عن الحضرة وعدم استئهالهم الخطاب المباشر، وتجديدًا لتكليف الرسول بتوبيخهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص492، تحت «دلالة التنبيه مع الخطاب بالواسطة».","url":""}]},{"id":"s3-230","number":230,"surah":3,"verses":[70,98],"references":[{"surah":3,"verses":[70,98]}],"verseLabel":"آل عمران: 70؛ آل عمران: 98","question":"ما بلاغة الحذف في قوله تعالى: ﴿وأنتم تشهدون﴾؟","answer":"حُذف متعلَّق الشهادة لأن السياق قد دل عليه، فصار التعبير موجزًا وأعمَّ في إلزامهم بما يعرفونه ويقرّون به من صدق الرسول؛ وبذلك قامت الحجة عليهم من شهادتهم نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص238–239، تحت «بلاغة الحذف في قوله: ﴿وأنتم تشهدون﴾»","url":""}]},{"id":"s3-779","number":779,"surah":3,"verses":[70,98],"references":[{"surah":3,"verses":[70,98]}],"verseLabel":"آل عمران: 70؛ آل عمران: 98","question":"ما دلالة ختم الآية بقوله تعالى: ﴿والله شهيد على ما تعملون﴾؟","answer":"الختم بشهادة الله وعيد وتهديد؛ فعلمه المحيط بأعمالهم يمنعهم من الجرأة على الكفر والصدّ، وينذرهم بالغضب والعقوبة إن استمروا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص494، تحت «دلالة ختم الآية بذكر شهادة الله على الأعمال»","url":""}]},{"id":"s3-231","number":231,"surah":3,"verses":[71],"references":[{"surah":3,"verses":[71]}],"verseLabel":"آل عمران: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿تلبسون الحق بالباطل﴾، وكيف يُلبس الحق؟","answer":"استعير اللبس من كسوة الثوب؛ فهم يكسون الحق بالباطل والشبهات حتى تختفي صورته ويصعب تمييزه، واختير اللبس لأنه يلائم المعاني المشتبهة أكثر من الخلط الحسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص250–254، تحت «اللبس والخلط».","url":""}]},{"id":"s3-232","number":232,"surah":3,"verses":[71],"references":[{"surah":3,"verses":[71]}],"verseLabel":"آل عمران: 71","question":"لماذا قدّم خلط الحق بالباطل على كتمان الحق؟","answer":"قُدّم اللبس لأنه الطريق الأول لإفساد دلالة الحق بتشويهه بالشبهات، ثم ذُكر الكتمان لأنه الطريق الآخر عند عجز التشويه: إخفاء الدلائل عمن لم تنطل عليه الشبهة؛ فجمع السياق بين مسلكي إضلالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص248، تحت «دلالة ذكر كتمان الحق بعد ذكر لبسه بالباطل في قوله تعالى: ﴿لم تلبسون الحق بالباطل وتكتمون الحق﴾».","url":""}]},{"id":"s3-233","number":233,"surah":3,"verses":[71],"references":[{"surah":3,"verses":[71]}],"verseLabel":"آل عمران: 71","question":"لماذا قيّد الكتمان بـ﴿وأنتم تعلمون﴾؟","answer":"قُيّد الكتمان بعلمهم لإقامة الحجة عليهم؛ فقد عرفوا الحق وثبت لهم أمر النبي ﷺ من كتبهم، ثم كتموه وجحدوه عمدًا، فكانت جنايتهم عن علم لا عن جهل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص250، تحت «توجيه المتشابه اللفظي بين قوله: ﴿وأنتم تعلمون﴾ وقوله: ﴿وأنتم لا تعلمون﴾ و﴿وأنتم تشهدون﴾».","url":""}]},{"id":"s3-234","number":234,"surah":3,"verses":[72],"references":[{"surah":3,"verses":[72]}],"verseLabel":"آل عمران: 72","question":"لماذا اقترحت الطائفة أن يؤمنوا أول النهار ويكفروا آخره؟","answer":"ليوهموا أن رجوعهم السريع نتج عن اكتشاف عيب في الدين بعد تجربته، فيزعزعوا ثقة المؤمنين ويغووا المترددين بالاقتداء بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص258، تحت «نكتة الاستعارة والإضافة في قوله: ﴿وجه النهار واكفروا آخره﴾».","url":""}]},{"id":"s3-235","number":235,"surah":3,"verses":[72],"references":[{"surah":3,"verses":[72]}],"verseLabel":"آل عمران: 72","question":"ما سرّ تعبيرهم بـ﴿الَّذِي أُنْزِلَ عَلَى الَّذِينَ آمَنُوا﴾ دون التصريح باسم القرآن؟","answer":"عدلوا عن التصريح بالقرآن إلى الموصول المبهم لأن تسمية القرآن تتضمن اعترافًا به، وهم يريدون التلبيس؛ فاختاروا عبارة تحتمل وجوهًا وتوهم السامع دون إقرار صريح بالوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص256–257، تحت «سر التعبير بالاسم الموصول وصلته في قوله: ﴿بالذي أُنزل﴾».","url":""}]},{"id":"s3-236","number":236,"surah":3,"verses":[72],"references":[{"surah":3,"verses":[72]}],"verseLabel":"آل عمران: 72","question":"لماذا ختمت حيلتهم بـ﴿لعلهم يرجعون﴾؟","answer":"ختم بـ﴿لعلهم يرجعون﴾ لتصوير غاية كيدهم: رجاؤهم أن يشك بعض المؤمنين فيرجع عن دينه، مع إخفاء الخطة في صيغة الرجاء والمبالغة في تعميتها؛ لا لأن رجوع المؤمنين جميعًا ممكن.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص259، تحت «سر اختيار (لعل) في قوله: ﴿لعلهم يرجعون﴾».","url":""}]},{"id":"s3-237","number":237,"surah":3,"verses":[73],"references":[{"surah":3,"verses":[73]}],"verseLabel":"آل عمران: 73","question":"ما دلالة قول بعض أهل الكتاب: ﴿وَلَا تُؤْمِنُوا إِلَّا لِمَنْ تَبِعَ دِينَكُمْ﴾؟","answer":"أرادوا: لا تصدقوا تصديقًا حقيقيًا إلا من بقي تابعًا لدينكم، ولا تعترفوا بمحمد ﷺ لأنه لم يتبعكم؛ وفي العبارة وصية بحفظ الأتباع وإحكام سيطرة الرؤساء عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص265، تحت «تعليل النهي في قوله تعالى: ﴿ولا تؤمنوا إلا لمن تبع دينكم﴾».","url":""}]},{"id":"s3-238","number":238,"surah":3,"verses":[73],"references":[{"surah":3,"verses":[73]}],"verseLabel":"آل عمران: 73","question":"لماذا اعترض القرآن قولهم بجملة ﴿قل إن الهدى هدى الله﴾؟","answer":"اعترضت الجملة لتقرر بالقصر أن الهدى الحقيقي هو ما يقدره الله ويهدي إليه، لا ما يصنعونه من صورة إيمان ومكر؛ فحيلتهم لا تمنع هداية الله ولا يحتاج الحق إلى متابعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص269، تحت «دلالة القصر في قوله: ﴿قل إن الهدى هدى الله﴾».","url":""}]},{"id":"s3-239","number":239,"surah":3,"verses":[73],"references":[{"surah":3,"verses":[73]}],"verseLabel":"آل عمران: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يؤتى أحد مثل ما أوتيتم﴾ بالبناء للمجهول؟","answer":"صيغ الفعل للمفعول لأن موضع خوفهم هو وقوع الإيتاء لغيرهم ومساواته لهم في الكتاب والنبوة، لا ذكر المعطي؛ ثم جاء الرد بأن الفضل بيد الله يؤتيه من يشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص272، تحت «﴿أن يؤتى أحد مثل ما أوتيتم﴾».","url":""}]},{"id":"s3-240","number":240,"surah":3,"verses":[73],"references":[{"surah":3,"verses":[73]}],"verseLabel":"آل عمران: 73","question":"لماذا ختمت الآية بـ﴿إن الفضل بيد الله يؤتيه من يشاء﴾؟","answer":"ختمت الآية بذلك لإبطال احتكارهم الرسالة والفضل؛ فالعطاء ملك الله وحده، متجدد لمن يشاء، لا يوقفه قوم ولا يحصرونه في أمة، ومنه اصطفاء هذه الأمة ورسولها وكتابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص274، تحت «سر اختيار لفظ ﴿الفضل﴾ في قوله: ﴿قل إن الفضل بيد الله﴾».","url":""}]},{"id":"s3-241","number":241,"surah":3,"verses":[73],"references":[{"surah":3,"verses":[73]}],"verseLabel":"آل عمران: 73","question":"لماذا جمع بين ﴿واسع﴾ و﴿عليم﴾ في هذا المقام؟","answer":"سعة الفضل تنفي احتكاره في قوم، والعلم يثبت أن منحه واقع في موضعه؛ فالاختيار ليس عجزًا ولا محاباة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص275، تحت «مناسبة الفاصلة في قوله تعالى: ﴿والله واسع عليم﴾ للسياق».","url":""}]},{"id":"s3-242","number":242,"surah":3,"verses":[74],"references":[{"surah":3,"verses":[74]}],"verseLabel":"آل عمران: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿يختص برحمته من يشاء﴾، دون أن يقال: يعطي رحمته؟","answer":"اختير ﴿يختص﴾ لأنه لا يدل على مجرد العطاء، بل على اصطفاء الله بعض خلقه برحمة لا يشاركهم فيها غيرهم، مع دلالة المضارع على تجدد هذا الاختيار واستمراره، ومن الرحمة هنا النبوة والوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص283، تحت «دلالة التعبير بالفعل ﴿يختص﴾ مادة وصيغة في قوله تعالى: ﴿يختص برحمته من يشاء﴾».","url":""}]},{"id":"s3-243","number":243,"surah":3,"verses":[74],"references":[{"surah":3,"verses":[74]}],"verseLabel":"آل عمران: 74","question":"لماذا ختم بـ﴿والله ذو الفضل العظيم﴾ لا: والله رحيم؟","answer":"ختم بذي الفضل العظيم لأن المقام لا يقتصر على الرحمة، بل يعم النبوة والوحي وسائر عطايا الله؛ و﴿العظيم﴾ يدل على فضل لا يتناهى ولا تحده أوهام المحتكرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص285، تحت «دلالة التعبير بـ﴿الفضل﴾ في قوله: ﴿والله ذو الفضل العظيم﴾».","url":""}]},{"id":"s3-244","number":244,"surah":3,"verses":[75],"references":[{"surah":3,"verses":[75]}],"verseLabel":"آل عمران: 75","question":"لماذا قابل القرآن بين من يؤتمن بقنطار ومن يؤتمن بدينار؟","answer":"جعل القنطار والدينار طرفي الكثرة والقلة ليبين أن الأمانة والخيانة خُلُقان لا تحددهما قيمة المال؛ فقد يحفظ الأمين الكثير ويجحد الخائن القليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص295–296، تحت «دلالة التعبير بـ﴿بقنطار﴾ وبـ﴿بدينار﴾».","url":""}]},{"id":"s3-245","number":245,"surah":3,"verses":[75],"references":[{"surah":3,"verses":[75]}],"verseLabel":"آل عمران: 75","question":"ما سرّ التعبير في قوله تعالى في حفظ الدينار ﴿إلا ما دمت عليه قائمًا﴾، وما صورة القيام هنا؟","answer":"صورة القيام هي ملازمة المدين ومداومة مطالبته، كأن صاحب الحق قائم عليه لا يفارقه؛ وقدم ﴿عليه﴾ للاهتمام وبيان أن استرداد الدينار لا يكون إلا بالإلحاح المتصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص297، تحت «بلاغة المجاز في التعبير بالقيام من قوله تعالى: ﴿ما دمت عليه قائمًا﴾».","url":""}]},{"id":"s3-246","number":246,"surah":3,"verses":[75],"references":[{"surah":3,"verses":[75]}],"verseLabel":"آل عمران: 75","question":"ما دلالة قولهم: ﴿لَيْسَ عَلَيْنَا فِي الْأُمِّيِّينَ سَبِيلٌ﴾؟","answer":"السبيل كناية عن الحجة والمؤاخذة؛ أي زعموا أنه لا طريق إلى لومهم في أموال غير اليهود، فكشف القرآن تحريفهم الأخلاقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص299، تحت «القيمة الدلالية لكلمة ﴿سبيل﴾ من قوله تعالى: ﴿ليس علينا في الأميين سبيل﴾».","url":""}]},{"id":"s3-247","number":247,"surah":3,"verses":[75],"references":[{"surah":3,"verses":[75]}],"verseLabel":"آل عمران: 75","question":"لماذا ختم الآية بـ﴿ويقولون على الله الكذب وهم يعلمون﴾؟","answer":"ختم بذلك ليفضح أن دعواهم ليست حكمًا في دينهم، بل كذب ينسبونه إلى الله وهم يعلمون بطلانه؛ وصيغة المضارع تدل على استمرار هذا الافتراء وتجدد صدوره منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص299، تحت «فائدة التعبير بالفعل المضارع في قوله: ﴿ويقولون على الله الكذب وهم يعلمون﴾».","url":""}]},{"id":"s3-248","number":248,"surah":3,"verses":[76],"references":[{"surah":3,"verses":[76]}],"verseLabel":"آل عمران: 76","question":"لماذا أُجيب عن دعواهم بكلمة ﴿بلى﴾؟","answer":"جاءت ﴿بلى﴾ لإبطال نفيهم: بل عليهم في الأميين سبيل ومؤاخذة، وهي أوفق جواب للنفي وأوجز لفظًا، ثم انتقل السياق إلى القاعدة العامة: الوفاء بالعهد والتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص304، تحت «دلالة ﴿بلى﴾ في قوله تعالى: ﴿بلى من أوفى بعهده﴾».","url":""}]},{"id":"s3-249","number":249,"surah":3,"verses":[76],"references":[{"surah":3,"verses":[76]}],"verseLabel":"آل عمران: 76","question":"لماذا جمع بين الوفاء بالعهد والتقوى؟","answer":"جمع بينهما لأن الوفاء بالعهد عمل مخصوص لا تتم محبة الله بدونه، والتقوى أصل عام يحمل على الطاعة والوفاء ويمنع الخيانة والعدوان؛ فذكرت القاعدة الباطنة الجامعة مع أثرها العملي البارز.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص306، تحت «فائدة قوله: ﴿واتقى﴾ بعد قوله: ﴿من أوفى بعهده﴾».","url":""}]},{"id":"s3-250","number":250,"surah":3,"verses":[76],"references":[{"surah":3,"verses":[76]}],"verseLabel":"آل عمران: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن الله يحب المتقين﴾، دون أن يقال: يحبه؟","answer":"أظهر اسم الله ولفظ المتقين بدل الضمير للتعليل والتعميم والتشريف؛ أي إن الله يحب الموفي لأنه من المتقين، وحكم المحبة لا يختص به بل يشمل كل من تحقق بالتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص306، تحت «دلالة وضع الظاهر موضع المضمر في قوله تعالى: ﴿فإن الله يحب المتقين﴾».","url":""}]},{"id":"s3-251","number":251,"surah":3,"verses":[77],"references":[{"surah":3,"verses":[77]}],"verseLabel":"آل عمران: 77","question":"لماذا وصف ثمن نقض العهد بأنه ﴿قليل﴾ مهما كان كبيرًا؟","answer":"وصف بالقليل لأن كل منفعة دنيوية عاجلة تُنال بإضاعة عهد الله قليلة إذا قيست بمنافع الآخرة، مهما عظمت في أعين أصحابها؛ بل إن الثمن القليل لا يصلح عوضًا عن كل ما يباع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص314، تحت «سر وصف الثمن بالقلة في قوله تعالى: ﴿وأيمانهم ثمنًا قليلًا﴾».","url":""}]},{"id":"s3-252","number":252,"surah":3,"verses":[77],"references":[{"surah":3,"verses":[77]}],"verseLabel":"آل عمران: 77","question":"لماذا تتابعت العقوبات: لا خلاق، ولا كلام، ولا نظر، ولا تزكية؟","answer":"استوعبت الحرمان من نعيم الآخرة ومن وجوه القرب والتكريم: لا نصيب، ولا خطاب رضا، ولا نظر رحمة، ولا تطهير؛ فناسب تعدد الجناية تعدد العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص315، تحت «تعدد الكنايات في قوله تعالى: ﴿ولا يكلمهم الله ولا ينظر إليهم يوم القيامة ولا يزكيهم﴾».","url":""}]},{"id":"s3-253","number":253,"surah":3,"verses":[77],"references":[{"surah":3,"verses":[77]}],"verseLabel":"آل عمران: 77","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا ينظر إليهم يوم القيامة﴾ مع إحاطة علم الله بهم؟","answer":"المنفي ليس علم الله بهم، فعلمه محيط بكل شيء، وإنما نظر الرحمة والرضا والتكريم؛ أي يعاملون معاملة من أعرض الله عنه وسخط عليه يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص315–316، تحت «تعدد الكنايات في قوله تعالى: ﴿ولا يكلمهم الله ولا ينظر إليهم يوم القيامة ولا يزكيهم ولهم عذاب أليم﴾»، ولا سيما بيان الكناية الثانية في ص316.","url":""}]},{"id":"s3-254","number":254,"surah":3,"verses":[77],"references":[{"surah":3,"verses":[77]}],"verseLabel":"آل عمران: 77","question":"لماذا ختم بـ﴿ولهم عذاب أليم﴾ بعد ذكر الحرمانات السابقة؟","answer":"بعد أن عددت الآية ما يُحرمونه من النصيب والكلام والنظر والتزكية، ختمت بإثبات العذاب الأليم؛ فجمع الوعيد بين حرمان الخير وإيقاع الشر والعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص315–316، تحت «تعدد الكنايات في قوله تعالى: ﴿ولا يكلمهم الله ولا ينظر إليهم يوم القيامة ولا يزكيهم ولهم عذاب أليم﴾».","url":""}]},{"id":"s3-255","number":255,"surah":3,"verses":[77],"references":[{"surah":2,"verses":[174]},{"surah":3,"verses":[77]}],"verseLabel":"آل عمران: 77؛ البقرة: 174","question":"لماذا زادت آية آل عمران في وعيد المشترين بالثمن القليل: ﴿لا خلاق لهم في الآخرة﴾ و﴿لا ينظر إليهم﴾، ولم تردا في نظير البقرة؟","answer":"آل عمران تتحدث عن نقض عهد الله والأيمان مع العلم، وهو جمع لحرمة الدين والعهد، فناسبه استقصاء ألوان الحرمان والإهانة؛ أما آية البقرة فركزت على كتمان الكتاب وأكل الثمن، فجاء وعيدها ملائمًا لجريمتها دون استيعاب الأوصاف نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص316–317، تحت «توجيه المتشابه اللفظي بين قوله: ﴿ولا يكلمهم الله يوم القيامة﴾ وقوله: ﴿ولا يكلمهم الله ولا ينظر إليهم يوم القيامة﴾».","url":""}]},{"id":"s3-256","number":256,"surah":3,"verses":[78],"references":[{"surah":3,"verses":[78]}],"verseLabel":"آل عمران: 78","question":"ما سرّ التعبير في قوله تعالى: ﴿يلوون ألسنتهم بالكتاب﴾، وكيف يُلوى اللسان؟","answer":"لَيُّ اللسان تصوير لتحريف التلاوة نفسها؛ يفتلون النطق ويكسرون الكلمات ويمزجون بعضها ببعض حتى يلتبس معناها على السامع ويحسب المحرّف من الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص327، تحت «نكتة نسبة اللَّيِّ إلى الألسنة في قوله: ﴿يلوون ألسنتهم بالكتاب﴾».","url":""}]},{"id":"s3-257","number":257,"surah":3,"verses":[78],"references":[{"surah":3,"verses":[78]}],"verseLabel":"آل عمران: 78","question":"ما سرّ التعبير في قوله تعالى: ﴿لتحسبوه من الكتاب﴾، دون أن يقال: لتظنوه؟","answer":"اختير الحسبان لأنه يدل هنا على اعتقاد راجح يقارب اليقين، فغاية تحريفهم أن يصدّق المسلمون أن الكلام من الكتاب، لا أن يقعوا في ظن ضعيف متردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص328، تحت «سر التعبير بالحسبان دون الظن».","url":""}]},{"id":"s3-258","number":258,"surah":3,"verses":[78],"references":[{"surah":3,"verses":[78]}],"verseLabel":"آل عمران: 78","question":"لماذا كرر النفي: ﴿وما هو من الكتاب... وما هو من عند الله﴾؟","answer":"كرر النفي لإبطال جهتين: فالمحرّف ليس من الكتاب الذي بأيديهم، وليس وحيًا من عند الله أصلًا؛ وبذلك يسد احتمال أن يكون خارج التوراة لكنه منزلًا من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص330، تحت «سر تكرار النفي في قوله تعالى: ﴿وما هو من عند الله﴾ وقوله: ﴿وما هو من الكتاب﴾».","url":""}]},{"id":"s3-259","number":259,"surah":3,"verses":[78],"references":[{"surah":3,"verses":[78]}],"verseLabel":"آل عمران: 78","question":"لماذا ختم بـ﴿وهم يعلمون﴾ كما ختمت آية 75؟","answer":"ختم بالعلم ليقرر أن تحريفهم ونسبته إلى الله كذب متعمد لا خطأ ناشئًا عن جهل، وهو المعنى نفسه الذي شددت عليه آية 75 في افترائهم على الله وهم يعلمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص332، تحت «دلالة تقديم المسند إليه على الخبر الفعلي في قوله: ﴿وهم يعلمون﴾».","url":""}]},{"id":"s3-260","number":260,"surah":3,"verses":[79],"references":[{"surah":3,"verses":[79]}],"verseLabel":"آل عمران: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كان لبشر أن يؤتيه الله الكتاب والحكم والنبوة ثم يقول للناس كونوا عبادًا لي﴾؟","answer":"صيغ بـ﴿ما كان﴾ لأن هذا الادعاء ممتنع لا يليق برسول آتاه الله الكتاب والحكم والنبوة؛ فهذه المواهب تقتضي عبادة الله وتعليمه، لا أن ينقلب النبي داعيًا إلى عبادة نفسه، وفيه تنزيه للأنبياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص339، تحت «توجيه قوله تعالى: ﴿ما كان لبشر أن يؤتيه الله الكتاب والحكم والنبوة ثم يقول للناس كونوا عبادًا لي من دون الله﴾».","url":""}]},{"id":"s3-261","number":261,"surah":3,"verses":[79],"references":[{"surah":3,"verses":[79]}],"verseLabel":"آل عمران: 79","question":"لماذا اختير لفظ ﴿بشر﴾ في مقام نفي ادعاء الألوهية؟","answer":"اختير ﴿بشر﴾ لاستحضار حقيقة الإنسان الظاهرة المحدودة؛ فاللفظ مشتق من ظهور البشرة والهيئة، ومن كان بشرًا ظاهر البشرية لا يليق أن يدعو الناس إلى عبادته من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص350، تحت «البشر والناس».","url":""}]},{"id":"s3-262","number":262,"surah":3,"verses":[79],"references":[{"surah":3,"verses":[79]}],"verseLabel":"آل عمران: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿كونوا ربانيين﴾، دون أن يقال: علماء أو صالحين؟","answer":"الرباني من ينتسب إلى الرب علمًا وعملاً وتربيةً للناس؛ فهو أوسع من مجرد العالم الذي قد يحمل المعرفة ولا يزكي بها نفسه وغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص346، تحت «بلاغة القصر في قوله تعالى: ﴿ولكن كونوا ربانيين﴾».","url":""}]},{"id":"s3-263","number":263,"surah":3,"verses":[79],"references":[{"surah":3,"verses":[79]}],"verseLabel":"آل عمران: 79","question":"لماذا قدّم ﴿بما كنتم تعلمون الكتاب﴾ على ﴿وبما كنتم تدرسون﴾؟","answer":"قدم التعليم لأنه المرتبة الأرفع والأظهر في الربانية؛ فالمعلم يجمع فهم الكتاب والعمل به ونقله إلى الناس، ثم عطف الدراسة التي هي دوام القراءة والتعلم وأساس ذلك التعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص349، تحت «نكتة تقديم التعليم على الدراسة».","url":""}]},{"id":"s3-264","number":264,"surah":3,"verses":[80],"references":[{"surah":3,"verses":[80]}],"verseLabel":"آل عمران: 80","question":"لماذا جمع بين اتخاذ الملائكة والنبيين أربابًا؟","answer":"لأنهما أعلى من قد يغلُو فيه البشر من الخلق؛ فإذا امتنع أن يأمر الرسول بتأليههما فامتناع تأليه من دونهما أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص358–359، تحت «فائدة التخصيص في قوله: ﴿ولا يأمركم أن تتخذوا الملائكة والنبيين أربابًا﴾».","url":""}]},{"id":"s3-265","number":265,"surah":3,"verses":[80],"references":[{"surah":3,"verses":[80]}],"verseLabel":"آل عمران: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿أيأمركم بالكفر بعد إذ أنتم مسلمون﴾ بالاستفهام لا بالنفي المباشر؟","answer":"الاستفهام في ﴿أيأمركم بالكفر بعد إذ أنتم مسلمون﴾ ليس طلبًا للعلم، بل إنكار وتوبيخ يحمل المخاطب على مواجهة تناقضه وإصدار الحكم على نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص360، تحت «دلالة الاستفهام في قوله تعالى: ﴿أيأمركم بالكفر بعد إذ أنتم مسلمون﴾».","url":""}]},{"id":"s3-266","number":266,"surah":3,"verses":[81],"references":[{"surah":3,"verses":[81]}],"verseLabel":"آل عمران: 81","question":"لماذا أخذ الله ميثاق النبيين على الإيمان برسول يأتي بعدهم؟","answer":"ليقرر وحدة مصدر الرسالات وأن السابق يمهد للاحق ولا يناقضه؛ فيلزم أتباع الأنبياء بنصرة الرسول المصدق لما معهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص366، تحت «تعيين المعطوف عليه في قوله تعالى: ﴿وإذ أخذ الله ميثاق النبيين﴾».","url":""}]},{"id":"s3-267","number":267,"surah":3,"verses":[81],"references":[{"surah":3,"verses":[81]}],"verseLabel":"آل عمران: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿لما آتيتكم من كتاب وحكمة﴾ فجمع الكتاب والحكمة؟","answer":"جمع الكتاب والحكمة لأن الميثاق متعلق بما أوتيه الأنبياء من أصل الوحي المنزل ومن الفهم والحكم الذي يكشف مراده ويقيم العمل به؛ فبهما تكتمل الحجة التي يصدقها الرسول الآتي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص372، تحت «سر تقديم الكتاب على الحكمة في قوله تعالى: ﴿لما آتيتكم من كتاب وحكمة﴾».","url":""}]},{"id":"s3-268","number":268,"surah":3,"verses":[81],"references":[{"surah":3,"verses":[81]}],"verseLabel":"آل عمران: 81","question":"لماذا وصف الرسول الآتي بأنه ﴿مصدق لما معكم﴾؟","answer":"وصفه بالمصدق ليبين أن مجيئه لا ينقض ما سبق، بل يوافق أصله الحق ويشهد له؛ فذلك يوجب على الأنبياء وأتباعهم الإيمان به ونصره ويسقط دعوى التعارض بين الرسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص373، تحت «فائدة وصف الرسول بكونه مصدقًا في قوله: ﴿مصدق لما معكم﴾».","url":""}]},{"id":"s3-269","number":269,"surah":3,"verses":[81],"references":[{"surah":3,"verses":[81]}],"verseLabel":"آل عمران: 81","question":"لماذا كرر الإقرار في قوله ﴿أأقررتم وأخذتم على ذلكم إصري قالوا أقررنا﴾؟","answer":"سئلوا أولًا ليواجهوا مضمون الميثاق ويقبلوا حمله، ثم أعادوا لفظ الإقرار في جوابهم تثبيتًا صريحًا للرضا والالتزام؛ فصار العهد موثقًا بالسؤال والجواب والشهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص375، تحت «دلالة التعبير بالإقرار في قوله تعالى: ﴿قال أأقررتم وأخذتم على ذلكم إصري قالوا أقررنا﴾».","url":""}]},{"id":"s3-270","number":270,"surah":3,"verses":[81],"references":[{"surah":3,"verses":[81]}],"verseLabel":"آل عمران: 81","question":"لماذا ختم الميثاق بـ﴿فاشهدوا وأنا معكم من الشاهدين﴾؟","answer":"ختم بالشهادة لتوثيق الميثاق وحفظه وإبلاغه، وليشهد بعضهم على بعض بالالتزام؛ ثم جعل الله نفسه معهم من الشاهدين تعظيمًا للعهد وتحذيرًا من كتمه أو تحريفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص378، تحت «سر التعبير بالجمع (الشاهدين) في قوله: ﴿وأنا معكم من الشاهدين﴾».","url":""}]},{"id":"s3-272","number":272,"surah":3,"verses":[82],"references":[{"surah":3,"verses":[82]}],"verseLabel":"آل عمران: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن تولى بعد ذلك﴾، وما الذي يفيده ﴿بعد ذلك﴾؟","answer":"تشير ﴿بعد ذلك﴾ إلى ما سبق من أخذ الميثاق والإقرار به والإشهاد عليه؛ فالتولي بعد هذا التوثيق أغلظ وأدل على الفسق، لا مجرد إعراض وقع بلا حجة سابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص382، تحت «سر التعبير بالتولي دون الإعراض في قوله تعالى: ﴿فمن تولى بعد ذلك﴾».","url":""}]},{"id":"s3-273","number":273,"surah":3,"verses":[82],"references":[{"surah":3,"verses":[82]}],"verseLabel":"آل عمران: 82","question":"لماذا حُصر المتولون في قوله ﴿فأولئك هم الفاسقون﴾؟","answer":"جيء باسم الإشارة للبعيد وضمير الفصل وتعريف ﴿الفاسقون﴾ لقصر كمال الفسق عليهم؛ إذ خرجوا عن طاعة الله بعد ميثاق مؤكد، فبلغ توليهم الغاية في الشر والبعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص384، تحت «علة توالي المؤكدات في الآية».","url":""}]},{"id":"s3-274","number":274,"surah":3,"verses":[83],"references":[{"surah":3,"verses":[83]}],"verseLabel":"آل عمران: 83","question":"لماذا جاء الإنكار في صورة سؤال: ﴿أفغير دين الله يبغون﴾ بدل النهي المباشر؟","answer":"الاستفهام في ﴿أفغير دين الله يبغون﴾ ليس طلبًا للعلم، بل إنكار وتوبيخ يحمل المخاطب على مواجهة تناقضه وإصدار الحكم على نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص388، تحت «دلالة الاستفهام في قوله تعالى: ﴿أفغير دين الله يبغون﴾».","url":""}]},{"id":"s3-275","number":275,"surah":3,"verses":[83],"references":[{"surah":3,"verses":[83]}],"verseLabel":"آل عمران: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿وله أسلم من في السماوات والأرض﴾، دون أن يقال: وما فيهما؟","answer":"اختيرت ﴿من﴾ لأنها الأصل في العقلاء، والمقام في خضوع ذوي الإرادة والتكليف لله طوعًا أو كرهًا؛ أما ﴿ما﴾ فتعم العقلاء وغيرهم ولا تبرز جهة المسؤولية نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص392–393، تحت «دلالة ﴿من﴾ في قوله: ﴿من في السماوات والأرض﴾».","url":""}]},{"id":"s3-276","number":276,"surah":3,"verses":[83],"references":[{"surah":3,"verses":[83]}],"verseLabel":"آل عمران: 83","question":"لماذا قابل بين ﴿طوعًا وكرهًا﴾؟","answer":"جمع الضدين لاستيعاب الخلق: فمنهم من أسلم لله اختيارًا وانقيادًا، ومنهم من يخضع لقضائه وتكوينه ومآله قهرًا وإن رفض الطاعة الشرعية؛ فلا يخرج أحد عن سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص394، تحت «دلالة الجمع بين ﴿طوعًا﴾ و﴿كرهًا﴾».","url":""}]},{"id":"s3-277","number":277,"surah":3,"verses":[83],"references":[{"surah":3,"verses":[83]}],"verseLabel":"آل عمران: 83","question":"لماذا خُتمت الآية بـ﴿وإليه يرجعون﴾ بعد ذكر إسلام الخلق؟","answer":"ختم بالرجوع إليه ليكتمل معنى السلطان: كما خضع له الخلق في السماوات والأرض، فمرجعهم جميعًا إليه للحساب والجزاء، ولا يملك الرافض لدينه مهربًا من حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص394، تحت «مناسبة قوله تعالى: ﴿وإليه يرجعون﴾».","url":""}]},{"id":"s3-278","number":278,"surah":3,"verses":[84],"references":[{"surah":3,"verses":[84]}],"verseLabel":"آل عمران: 84","question":"ما سرّ التعبير هنا في قوله تعالى ﴿قل آمنا بالله وما أنزل علينا﴾، وقال في البقرة ﴿قولوا آمنا... وما أنزل إلينا﴾؟","answer":"الخطاب في البقرة للأمة فقال ﴿قولوا﴾ و﴿إلينا﴾، أما هنا فبدأ بالنبي ممثلًا للأمة فقال ﴿قل﴾ و﴿علينا﴾ بما يوحي بعلو الوحي وثقل التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص399–402، تحت «نكتة تكرار الموصول ﴿وما﴾ والفعل ﴿أنزل﴾ في قوله: ﴿وما أنزل علينا﴾».","url":""}]},{"id":"s3-279","number":279,"surah":3,"verses":[84],"references":[{"surah":3,"verses":[84]}],"verseLabel":"آل عمران: 84","question":"لماذا قدّم ما أُنزل على المسلمين على ما أُنزل على إبراهيم وسائر النبيين؟","answer":"لأن المتكلم مأمور بإعلان إيمانه من موقع الرسالة الحاضرة، فبدأ بالوحي الذي يخاطبه ويكلفه، ثم وصلَه بأصول الوحي السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص400، تحت «سر تقديم الإيمان بالله تعالى على غيره».","url":""}]},{"id":"s3-280","number":280,"surah":3,"verses":[84],"references":[{"surah":3,"verses":[84]}],"verseLabel":"آل عمران: 84","question":"لماذا أفرد ﴿وما أوتي موسى وعيسى﴾ ثم عمّم ﴿والنبيون من ربهم﴾؟","answer":"خُص موسى وعيسى لأن المخاطبين من اليهود والنصارى يدّعون اتباعهما، فكان التصريح بهما ألزم للحجة؛ ثم عمم النبيين لاستيعاب سائر الرسل وإعلان الإيمان بهم جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص403، تحت «نكتة الإطناب في قوله: ﴿وما أوتي موسى وعيسى والنبيون من ربهم﴾».","url":""}]},{"id":"s3-281","number":281,"surah":3,"verses":[84],"references":[{"surah":3,"verses":[84]}],"verseLabel":"آل عمران: 84","question":"لماذا ختم الإيمان بالرسل بـ﴿لا نفرق بين أحد منهم﴾؟","answer":"ختم بنفي التفريق لأن الإيمان الحق يصدق جميع رسل الله، ردًا على من آمن ببعضهم وكفر ببعض؛ فالرسل متحدون في أصل الوحي ولا يكون الانتقاء بينهم إيمانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص404، تحت «سبب فصل قوله تعالى: ﴿لا نفرق بين أحد منهم﴾ عما قبله».","url":""}]},{"id":"s3-282","number":282,"surah":3,"verses":[84],"references":[{"surah":3,"verses":[84]}],"verseLabel":"آل عمران: 84","question":"لماذا كرر في البقرة ﴿وما أوتي﴾ قبل النبيين، وحذف التكرار في آل عمران: ﴿وما أوتي موسى وعيسى والنبيون﴾؟","answer":"حُذف التكرار في آل عمران لعطف النبيين على موسى وعيسى تحت إيتاء واحد، تشديدًا لوحدة مصدر الجميع في مقام الرد على المفرقين؛ أما البقرة فكرر الفعل للفصل البياني بين المذكورين والمجموعة العامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص402، تحت «نكتة تكرار الموصول (ما) والفعل (أنزل)».","url":""}]},{"id":"s3-283","number":283,"surah":3,"verses":[85],"references":[{"surah":3,"verses":[85]}],"verseLabel":"آل عمران: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يبتغ غير الإسلام دينًا﴾ بتقديم ﴿غير الإسلام﴾؟","answer":"قدم ﴿غير الإسلام﴾ لأنه بؤرة الإنكار والتحذير؛ فاستُحضر الدين البديل المرفوض أولًا، ثم حكم عليه بأنه لن يقبل، وفي التقديم تشنيع لاختيار غير دين الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص411، تحت «دلالة التقديم في قوله تعالى: ﴿ومن يبتغ غير الإسلام دينًا﴾».","url":""}]},{"id":"s3-284","number":284,"surah":3,"verses":[85],"references":[{"surah":3,"verses":[85]}],"verseLabel":"آل عمران: 85","question":"لماذا بُني ﴿فلن يقبل منه﴾ للمجهول؟","answer":"بُني للمفعول لأن الفاعل معلوم، وهو الله، فترك ذكره للتركيز على القطع بعدم القبول، وفي الحذف إهانة لطالب غير الإسلام كأن عمله لا يستحق أن ينسب رفضه تصريحًا إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص413، تحت «نكتة بناء الفعل ﴿يقبل﴾ للمفعول في قوله تعالى: ﴿فلن يقبل منه﴾».","url":""}]},{"id":"s3-285","number":285,"surah":3,"verses":[85],"references":[{"surah":3,"verses":[85]}],"verseLabel":"آل عمران: 85","question":"لماذا جمع بين عدم القبول والخسران في الآخرة؟","answer":"عدم القبول حكم على العمل في ذاته، والخسران وصف لعاقبة صاحبه بعد ضياع رأس ماله وعمره؛ فجمع بطلان الطريق وسوء المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص413–414، تحت «دلالة قوله تعالى: ﴿وهو في الآخرة من الخاسرين﴾».","url":""}]},{"id":"s3-286","number":286,"surah":3,"verses":[86],"references":[{"surah":3,"verses":[86]}],"verseLabel":"آل عمران: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿كيف يهدي الله قومًا كفروا بعد إيمانهم﴾ بصيغة الاستفهام؟","answer":"الاستفهام للاستبعاد والتوبيخ: كيف يطلبون ثمرة الهداية وقد نقضوا مقتضياتها بعد العلم والشهادة؟ وهو لا يغلق التوبة التي استثنتها الآيات التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص421–423، تحت «دلالة الاستفهام في قوله تعالى: ﴿كيف يهدي الله قومًا كفروا بعد إيمانهم﴾».","url":""}]},{"id":"s3-287","number":287,"surah":3,"verses":[86],"references":[{"surah":3,"verses":[86]}],"verseLabel":"آل عمران: 86","question":"لماذا عطف ﴿وشهدوا أن الرسول حق﴾ على إيمانهم؟","answer":"عُطفت الشهادة لأنها أخص من أصل الإيمان؛ فهي علم بالرسول وإقرار صريح بحقه بعد قيام الحجة، فذكرها يبين أن كفرهم وقع بعد يقين واعترفوا به لا بعد إيمان مجمل فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص423–424، تحت «نكتة التوكيد في قوله: ﴿وشهدوا أن الرسول حق﴾».","url":""}]},{"id":"s3-288","number":288,"surah":3,"verses":[86],"references":[{"surah":3,"verses":[86]}],"verseLabel":"آل عمران: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿وجاءهم البينات﴾ بعد الشهادة بأن الرسول حق؟","answer":"ذُكرت البينات بعد شهادتهم ليجتمع عليهم الإقرار الداخلي والدلائل الخارجية الواضحة؛ فليس كفرهم ناشئًا عن غموض، بل وقع بعد اعتراف وبرهان مكتمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص424–425، تحت «براعة المجاز العقلي في قوله: ﴿وجاءهم البينات﴾».","url":""}]},{"id":"s3-289","number":289,"surah":3,"verses":[86],"references":[{"surah":3,"verses":[86]}],"verseLabel":"آل عمران: 86","question":"لماذا ختم بـ﴿والله لا يهدي القوم الظالمين﴾ فوصفهم بالظلم؟","answer":"وصفوا بالظلم لأنهم وضعوا الكفر موضع الإيمان بعد العلم والشهادة والبينات، فظلموا الحق وظلموا أنفسهم باختيار الضلال؛ ومن أصر على هذا الظلم لا يوفق لطريق الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص425، تحت «بلاغة التذييل في قوله سبحانه: ﴿والله لا يهدي القوم الظالمين﴾».","url":""}]},{"id":"s3-290","number":290,"surah":3,"verses":[87],"references":[{"surah":3,"verses":[87]}],"verseLabel":"آل عمران: 87","question":"لماذا جمعت اللعنة من الله والملائكة والناس أجمعين؟","answer":"لتصوير نبذهم في العوالم كلها: حكم الله بإبعادهم، وموافقة الملائكة، وظهور استحقاقهم عند الناس؛ فلا يبقى لهم موطن كرامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص427–428، تحت «دلالة اللام في قوله تعالى: ﴿أن عليهم لعنة الله والملائكة والناس أجمعين﴾».","url":""}]},{"id":"s3-292","number":292,"surah":3,"verses":[88],"references":[{"surah":3,"verses":[88]}],"verseLabel":"آل عمران: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿خالدين فيها﴾ مع أن المذكور قبلها ﴿لعنة الله﴾؟","answer":"عاد الضمير إلى النار المفهومة من اللعنة والعقوبة، ورجوعه إلى أقرب معنى سياقي ظاهر جائز ولو لم يصرح بلفظ النار؛ فالمقام دل عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص428، تحت «تعيين مرجع الضمير في قوله تعالى: ﴿خالدين فيها﴾».","url":""}]},{"id":"s3-293","number":293,"surah":3,"verses":[88],"references":[{"surah":3,"verses":[88]}],"verseLabel":"آل عمران: 88","question":"لماذا جمع بين عدم تخفيف العذاب وعدم إنظارهم؟","answer":"نُفي النقص في شدة العذاب ونُفي تأخيره؛ فلا راحة بتخفيف الحاضر ولا أمل بمهلة تنقطع بها العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص428، تحت «دلالة قوله: ﴿ولا هم ينظرون﴾ بعد قوله: ﴿لا يخفف عنهم العذاب﴾».","url":""}]},{"id":"s3-294","number":294,"surah":3,"verses":[89],"references":[{"surah":3,"verses":[89]}],"verseLabel":"آل عمران: 89","question":"لماذا استثنى ﴿إلا الذين تابوا من بعد ذلك وأصلحوا﴾، ولم يكتف بالتوبة؟","answer":"لم يكتف بالتوبة لأن الرجوع القولي لا يتم حتى يصلحوا ما أفسدوه، وحذف المفعول ليشمل كل فساد؛ و﴿من بعد ذلك﴾ تحثهم على المبادرة بعد الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص429، تحت «حذف متعلق الفعل ﴿وأصلحوا﴾ في قوله تعالى: ﴿إلا الذين تابوا من بعد ذلك وأصلحوا﴾».","url":""}]},{"id":"s3-295","number":295,"surah":3,"verses":[89],"references":[{"surah":3,"verses":[89]}],"verseLabel":"آل عمران: 89","question":"لماذا ختمت آية التوبة بـ﴿فإن الله غفور رحيم﴾؟","answer":"ختم بها لبيان نتيجة التوبة والإصلاح وعلتها: إن تابوا وأصلحوا غفر الله لهم؛ فبعد الوعيد يفتح باب الرجاء ويجمع بين الترهيب والترغيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص430، تحت «بلاغة التذييل في قوله: ﴿فإن الله غفور رحيم﴾».","url":""}]},{"id":"s3-296","number":296,"surah":3,"verses":[90],"references":[{"surah":3,"verses":[90]}],"verseLabel":"آل عمران: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم ازدادوا كفرًا﴾، وكيف يزداد الكفر؟","answer":"يزداد الكفر بتتابع أسبابه وآثاره: الإصرار بعد الردة، والطعن في الرسول، ونقض العهود والصد عن الحق؛ وأفادت ﴿ثم﴾ تماديهم حتى بلغ الكفر غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص440، تحت «دلالة صيغة الافتعال في قوله تعالى: ﴿ثم ازدادوا كفرًا﴾».","url":""}]},{"id":"s3-297","number":297,"surah":3,"verses":[90],"references":[{"surah":3,"verses":[90]}],"verseLabel":"آل عمران: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿لن تقبل توبتهم﴾ مع أن باب التوبة مفتوح؟","answer":"باب التوبة الصادقة مفتوح، وإنما المنفي قبول توبة فاسدة غير مستوفية للشروط مع الإصرار والازدياد في الكفر، أو توبة الموت التي لا حقيقة لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص441–442، تحت «دلالة قول الله تعالى: ﴿لن تقبل توبتهم﴾».","url":""}]},{"id":"s3-298","number":298,"surah":3,"verses":[90],"references":[{"surah":3,"verses":[90]}],"verseLabel":"آل عمران: 90","question":"لماذا خُتمت الآية بالقصر ﴿وأولئك هم الضالون﴾؟","answer":"جيء باسم الإشارة وضمير الفصل وتعريف ﴿الضالون﴾ لقصر كمال الضلال عليهم؛ إذ رسخوا فيه بالإصرار على الكفر حتى صارت ضلالة غيرهم بالنسبة إليها قليلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص442–443، تحت «بلاغة القصر في قوله تعالى: ﴿وأولئك هم الضالون﴾».","url":""}]},{"id":"s3-299","number":299,"surah":3,"verses":[91],"references":[{"surah":3,"verses":[91]}],"verseLabel":"آل عمران: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿فلن يقبل من أحدهم ملء الأرض ذهبًا﴾؟","answer":"ذكر ملء الأرض ذهبًا للمبالغة في تصوير أعظم فدية ممكنة كثرةً ونفاسةً؛ فإذا لم يقبل هذا القدر ممن مات كافرًا، انتفى قبول ما دونه من باب أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص450–451، تحت «بلاغة الكناية في قوله سبحانه: ﴿فلن يقبل من أحدهم ملء الأرض ذهبًا﴾».","url":""}]},{"id":"s3-300","number":300,"surah":3,"verses":[91],"references":[{"surah":3,"verses":[91]}],"verseLabel":"آل عمران: 91","question":"لماذا خُصّ الذهب في الفداء دون سائر الأموال؟","answer":"خُص الذهب لأنه مثال أنفس الأموال وأعزها، وجمع معه ملء الأرض ليبلغ التصوير غاية النفاسة والكثرة؛ فحتى هذا لا يخلص الكافر من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص450–451، تحت «بلاغة الكناية في قوله سبحانه: ﴿فلن يقبل من أحدهم ملء الأرض ذهبًا﴾».","url":""}]},{"id":"s3-301","number":301,"surah":3,"verses":[91],"references":[{"surah":3,"verses":[91]}],"verseLabel":"آل عمران: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو افتدى به﴾ بعد نفي قبول ملء الأرض ذهبًا؟","answer":"أضيف ﴿ولو افتدى به﴾ لاستقصاء الأحوال؛ أي لا يقبل ملء الأرض ذهبًا منه على أي وجه، حتى لو قدمه صراحةً فديةً لنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص451، تحت «دلالة ﴿ولو﴾ في قوله تعالى: ﴿ولو افتدى به﴾».","url":""}]},{"id":"s3-302","number":302,"surah":3,"verses":[91],"references":[{"surah":3,"verses":[91]}],"verseLabel":"آل عمران: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿وما لهم من ناصرين﴾ بعد فرض الفداء؟","answer":"لما نفي خلاصهم بأعظم فدية نفي عنهم طريق النجدة من الغير أيضًا؛ فـ﴿من﴾ تستغرق كل ناصر، وجمع ﴿ناصرين﴾ يبالغ في انتفاء النجاة ولو اجتمعت جماعات.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص452–453، تحت «دلالة ﴿من﴾ في قوله: ﴿وما لهم من ناصرين﴾».","url":""}]},{"id":"s3-303","number":303,"surah":3,"verses":[92],"references":[{"surah":3,"verses":[92]}],"verseLabel":"آل عمران: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿لن تنالوا البر﴾، فجعل البر شيئًا يُنال؟","answer":"صوّر البر منزلةً عالية تُنال بعد سعي، وربطه ببذل المحبوب لأن صدق الإيمان يظهر عند مفارقة ما تتعلق به النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص457، تحت «بلاغة التعبير بـ﴿حتى﴾ دون غيرها من الألفاظ».","url":""}]},{"id":"s3-304","number":304,"surah":3,"verses":[92],"references":[{"surah":3,"verses":[92]}],"verseLabel":"آل عمران: 92","question":"لماذا عُلّق نيل البر بالإنفاق ﴿مما تحبون﴾ لا بمجرد الإنفاق؟","answer":"لأن بذل ما تحبه النفس هو الذي يكشف صدق الإيمان وتقديم طاعة الله على التعلق بالمال؛ فصار الإنفاق من المحبوب عنوانًا لسائر خصال البر لا مجرد إخراج أي مال.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص458، تحت «معنى ﴿مما تحبون﴾ بين الحقيقة والمجاز».","url":""}]},{"id":"s3-305","number":305,"surah":3,"verses":[92],"references":[{"surah":3,"verses":[92]}],"verseLabel":"آل عمران: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿وما تنفقوا من شيء فإن الله به عليم﴾ بعد ذكر المحبوب؟","answer":"ليدخل كل إنفاق قليل أو كثير، وليقرر أن الله يعلم قيمة المبذول في قلب صاحبه وصدق نيته؛ فالعبرة ليست بمظهر المال وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص459، تحت «بلاغة التذييل في ﴿وما تنفقوا من شيء فان الله به عليم﴾»","url":""}]},{"id":"s3-306","number":306,"surah":3,"verses":[93],"references":[{"surah":3,"verses":[93]}],"verseLabel":"آل عمران: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿كل الطعام كان حلًا لبني إسرائيل﴾ ثم استثنى ما حرّم إسرائيل على نفسه؟","answer":"قرر أولًا عموم الحل قبل التوراة، ثم استثنى ما حرمه يعقوب على نفسه لسبب خاص فتابعه بنوه؛ ليفرق بين أصل الإباحة وذلك التحريم العارض، ويبطل دعوى اليهود أنه شريعة قديمة عامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص464، تحت «دلالة اسمية الجملة في ﴿كل الطعام كان حلًّا﴾».","url":""}]},{"id":"s3-307","number":307,"surah":3,"verses":[93],"references":[{"surah":3,"verses":[93]}],"verseLabel":"آل عمران: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿إسرائيل﴾، دون أن يقال: يعقوب؟","answer":"سمي إسرائيل لأنه الاسم الذي ينتسب إليه بنوه المخاطبون، فذكره بهذا الاسم ألزم لهم في الحجة وأدعى لاستحضار أن التحريم الشخصي لأبيهم لا يثبت شريعة عامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص464، تحت «دلالة تخصيص التحريم بإسرائيل».","url":""}]},{"id":"s3-308","number":308,"surah":3,"verses":[93],"references":[{"surah":3,"verses":[93]}],"verseLabel":"آل عمران: 93","question":"لماذا أمرهم أن يأتوا بالتوراة ثم يتلوها إن كانوا صادقين؟","answer":"نقل الخصومة من الدعوى إلى النص الذي يحتجون به، وألزمهم أن يظهروه بأنفسهم؛ فتقوم الحجة من كتابهم وتنكشف جرأة التحريم المكذوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص466، تحت «دلالة الشرط في قوله: ﴿إن كنتم صادقين﴾».","url":""}]},{"id":"s3-309","number":309,"surah":3,"verses":[94],"references":[{"surah":3,"verses":[94]}],"verseLabel":"آل عمران: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن افترى على الله الكذب من بعد ذلك﴾؟","answer":"قيد الافتراء بـ﴿من بعد ذلك﴾ لأن الكذب بعد ظهور الحق وإقامة الحجة بالتوراة والبيان القرآني أبلغ قبحًا، ويكشف إصرار صاحبه على الضلال بعد انقطاع العذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص468، تحت «دلالة الجمع بين الكذب والافتراء في قوله: ﴿افترى على الله الكذب﴾».","url":""}]},{"id":"s3-310","number":310,"surah":3,"verses":[94],"references":[{"surah":3,"verses":[94]}],"verseLabel":"آل عمران: 94","question":"لماذا حصر المفترين في ﴿فأولئك هم الظالمون﴾؟","answer":"جيء باسم الإشارة وضمير الفصل وتعريف ﴿الظالمون﴾ لقصر غاية الظلم عليهم؛ إذ تعمدوا الكذب على الله بعد ظهور الحق، فاستحقوا أشد الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص469، تحت «دلالة القصر الإضافي في قوله: ﴿فأولئك هم الظالمون﴾».","url":""}]},{"id":"s3-311","number":311,"surah":3,"verses":[95],"references":[{"surah":3,"verses":[95]}],"verseLabel":"آل عمران: 95","question":"لماذا جاء الجواب المختصر ﴿قل صدق الله﴾ بعد تحديهم بالتوراة؟","answer":"قيل ﴿صدق الله﴾ بدل التصريح «كذب اليهود» لأن ثبوت صدق خبر الله بعد قيام الحجة يستلزم بطلان قولهم، وفيه تعظيم للحق وقائله وتمهيد لاتباع ملة إبراهيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص472–473، تحت «سر التعبير بصدق الله تعالى لا بكذب اليهود».","url":""}]},{"id":"s3-312","number":312,"surah":3,"verses":[95],"references":[{"surah":3,"verses":[95]}],"verseLabel":"آل عمران: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿فاتبعوا ملة إبراهيم﴾، دون أن يقال: دين إبراهيم؟","answer":"اختيرت ﴿ملة إبراهيم﴾ لأن الملة تطلق على الشريعة والطريقة المتبعة وتضاف إلى النبي الذي ظهرت على لسانه؛ فالمقام مقام اقتداء بمنهج إبراهيم العملي، لا مجرد تسمية الدين في ذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص395، تحت «الدِّين والملّة».","url":""}]},{"id":"s3-313","number":313,"surah":3,"verses":[95],"references":[{"surah":3,"verses":[95]}],"verseLabel":"آل عمران: 95","question":"لماذا وصف إبراهيم مرة أخرى بـ﴿حنيفًا﴾ ثم نفى عنه الشرك؟","answer":"وصفه بالحنيف لإثبات استقامته وميله عن الباطل إلى التوحيد، ثم نُفي عنه الشرك توكيدًا لذلك وتعريضًا بمن زعم اتباعه مع وقوعه في الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص474–476، تحت «بلاغة الإطناب في قوله تعالى: ﴿وما كان من المشركين﴾».","url":""}]},{"id":"s3-314","number":314,"surah":3,"verses":[96],"references":[{"surah":3,"verses":[96]}],"verseLabel":"آل عمران: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿إن أول بيت وضع للناس﴾، دون أن يقال: بُني؟","answer":"قيل ﴿وضع﴾ لأنه أوسع من مجرد تشييد البناء؛ فهو يدل على تأسيس البيت وتعيينه للناس موضعًا للعبادة، أما بناء إبراهيم فكان رفعًا لقواعد بيت موضوع قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص478، تحت «دلالة البناء للمفعول في ﴿وضع للناس﴾».","url":""}]},{"id":"s3-315","number":315,"surah":3,"verses":[96],"references":[{"surah":3,"verses":[96]}],"verseLabel":"آل عمران: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿للذي ببكة﴾، دون أن يقال: بمكة؟","answer":"اختير ﴿بكة﴾ لأنه الاسم القديم الأول لموضع البيت، وفيه تصريح بأولية هذا البيت وقدم اسمه، مع ما ذكر من دلالته على موضع الطواف أو ازدحام الناس فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص479، تحت «دلالة اختيار لفظ بكة دون غيرها من الألفاظ».","url":""}]},{"id":"s3-316","number":316,"surah":3,"verses":[96],"references":[{"surah":3,"verses":[96]}],"verseLabel":"آل عمران: 96","question":"لماذا وصف البيت بـ﴿مباركًا وهدى للعالمين﴾؟","answer":"وصف بالمبارك لكثرة خيراته ومنافعه الدينية والدنيوية، وبالهدى لأنه بما فيه من آيات وشعائر وقبلة يدل العالمين على التوحيد وطريق العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص479، تحت «نكتة المجاز بالحذف في قوله: ﴿وهدى للعالمين﴾».","url":""}]},{"id":"s3-317","number":317,"surah":3,"verses":[97],"references":[{"surah":3,"verses":[97]}],"verseLabel":"آل عمران: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿فيه آيات بينات مقام إبراهيم﴾، فذكر المقام بعد جمع الآيات؟","answer":"ذُكر مقام إبراهيم بعد الجمع بيانًا له؛ لأن هذا المقام الواحد يشتمل على آيات متعددة: أثر القدم، وما اتصل به من بناء البيت وبقاء الأثر وحفظه، فكأنه آيات لا آية واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص482–483، تحت «نكتة بيان الجمع بالمفرد في قوله: ﴿آيات بينات مقام إبراهيم﴾».","url":""}]},{"id":"s3-318","number":318,"surah":3,"verses":[97],"references":[{"surah":3,"verses":[97]}],"verseLabel":"آل عمران: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن دخله كان آمنًا﴾ بصيغة الخبر؟","answer":"جاء خبرًا يتضمن تشريع حرمة البيت وتذكيرًا بما أودع الله فيه من أمن؛ فصيغة الخبر أثبت وأبلغ من أمر عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص483، تحت «الإنشاء بلفظ الخبر في قوله: ﴿ومن دخله كان آمنًا﴾».","url":""}]},{"id":"s3-319","number":319,"surah":3,"verses":[97],"references":[{"surah":3,"verses":[97]}],"verseLabel":"آل عمران: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿ولله على الناس حج البيت﴾ فجعل الحج حقًا لله على الناس؟","answer":"صيغت الجملة هكذا لإثبات الحج حقًا مستحقًا لله ودينًا واجبًا على الناس؛ فاللام للاستحقاق و﴿على﴾ للوجوب، وتقديم ﴿لله﴾ يخص العبادة به ويقوي ثبوتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص486، تحت «دلالة التعبير بالجملة الاسمية في ﴿ولله على الناس حج البيت﴾».","url":""}]},{"id":"s3-320","number":320,"surah":3,"verses":[97],"references":[{"surah":3,"verses":[97]}],"verseLabel":"آل عمران: 97","question":"لماذا قيّد وجوب الحج بـ﴿من استطاع إليه سبيلًا﴾؟","answer":"قُيد الوجوب بالمستطيع تخفيفًا وإخراجًا للعاجز؛ وعبر بالسبيل استعارةً عن القدرة التامة التي توصل إلى الحج، من زاد وراحلة وسائر الشروط.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص486–487، تحت «بلاغة استعارة السبيل عن كلفة الحج».","url":""}]},{"id":"s3-321","number":321,"surah":3,"verses":[97],"references":[{"surah":3,"verses":[97]}],"verseLabel":"آل عمران: 97","question":"لماذا عُدل من الحج إلى قوله ﴿ومن كفر فإن الله غني عن العالمين﴾؟","answer":"عُدل إلى ﴿ومن كفر﴾ للتغليظ على من ترك الحج مع استطاعته، فشُبه صنيعه بصنيع من لا يؤمن بالله ورسله وحرمة بيته، وفي المقابلة إشعار بأن أداء الحج من مقتضيات الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص487–488، تحت «سر العدول عن ذكر عدم الحج إلى ﴿ومن كفر﴾».","url":""}]},{"id":"s3-322","number":322,"surah":3,"verses":[97],"references":[{"surah":3,"verses":[97]}],"verseLabel":"آل عمران: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿غني عن العالمين﴾ لا: غني عنه؟","answer":"قال ﴿عن العالمين﴾ لإعلان استغنائه عن الخلق كلهم، لا عن تارك الحج وحده؛ وفي وضع الظاهر موضع الضمير مبالغة في تحقيره حتى كأنه لا يستحق أن يخص بالذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص488–489، تحت «دلالة وضع الظاهر موضع الضمير في قوله: ﴿فإن الله غني عن العالمين﴾».","url":""}]},{"id":"s3-323","number":323,"surah":3,"verses":[98],"references":[{"surah":3,"verses":[98]}],"verseLabel":"آل عمران: 98","question":"لماذا تكرر النداء ﴿يا أهل الكتاب﴾ بعد الحجج السابقة؟","answer":"تجدد النداء لأن السياق انتقل إلى جريمة أخرى بعد حجج البيت: الكفر بآيات الله والصد عن سبيله؛ فاستدعى وصف أهل الكتاب مرة جديدة لإلزامهم بكتابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص497–498، تحت «دلالة تكرير الخطاب في سياق واحد».","url":""}]},{"id":"s3-324","number":324,"surah":3,"verses":[98],"references":[{"surah":3,"verses":[98]}],"verseLabel":"آل عمران: 98","question":"ما سرّ التعبير في قوله تعالى: ﴿لم تكفرون بآيات الله والله شهيد على ما تعملون﴾؟","answer":"الاستفهام توبيخ، ثم جاءت الشهادة تهديدًا بأن كفرهم ليس خافيًا ولا دعوى بلا حساب؛ فالله مطلع عليه ومجازٍ به.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص494، تحت «دلالة صيغة المبالغة في ﴿شهيد على ما تعملون﴾».","url":""}]}]);
